        /* INTRO CINEMATOGRÁFICA — camada isolada, sem alterar a lógica da corrida */
        #rr-intro-screen {
            position: fixed; inset: 0; z-index: 100000;
            display: flex; align-items: center; justify-content: center;
            overflow: hidden; padding: clamp(14px, 3vw, 36px);
            background: radial-gradient(ellipse at 50% 42%, #243c63 0%, #101a30 42%, #030711 100%);
            opacity: 1; visibility: visible;
            transition: opacity .65s ease, visibility .65s ease;
            touch-action: manipulation;
        }
        #rr-intro-screen.rr-intro-leaving { opacity: 0; visibility: hidden; pointer-events: none; }
        #rr-intro-screen::before {
            content: ''; position: absolute; inset: -30%; pointer-events: none;
            background: repeating-linear-gradient(118deg, transparent 0 95px, rgba(255,255,255,.035) 96px 99px, transparent 100px 180px);
            transform: perspective(500px) rotateX(58deg) translateY(18%);
            animation: rr-road-flow 5s linear infinite;
        }
        #rr-intro-screen .rr-intro-glow {
            position: absolute; width: min(78vw, 900px); aspect-ratio: 1; border-radius: 50%;
            background: rgba(255, 193, 7, .09); filter: blur(75px); pointer-events: none;
        }
        #rr-intro-content {
            position: relative; z-index: 2; width: min(1500px, 100%); display: flex;
            flex-direction: column; align-items: center; gap: clamp(10px, 2vh, 20px);
            text-align: center;
        }
        #rr-intro-logo {
            display: block; width: min(94vw, 1500px); height: auto; max-height: min(76vh, calc(100vh - 190px));
            object-fit: contain; filter: drop-shadow(0 16px 32px rgba(0,0,0,.58));
            opacity: 0; transform: translateY(65px) scale(.82);
            animation: rr-logo-arrive 1.05s cubic-bezier(.18,.85,.25,1.18) .25s forwards;
        }
        #rr-intro-caption {
            margin: 0; color: #dbeafe; font-size: clamp(8px, 1.2vw, 12px);
            letter-spacing: clamp(1px, .35vw, 4px); line-height: 1.8;
            text-shadow: 0 0 14px rgba(80,160,255,.5); opacity: 0;
            animation: rr-caption-in .65s ease 1.05s forwards;
        }
        #rr-intro-track {
            width: min(460px, 86vw); height: 42px; position: relative; overflow: hidden;
            border-top: 1px solid rgba(255,255,255,.18); border-bottom: 1px solid rgba(255,255,255,.18);
            background: linear-gradient(180deg, rgba(255,255,255,.025), rgba(0,0,0,.28));
            opacity: 0; animation: rr-caption-in .4s ease .7s forwards;
        }
        #rr-intro-track::before {
            content: ''; position: absolute; top: 19px; left: 0; width: 200%; height: 3px;
            background: repeating-linear-gradient(90deg, #f8fafc 0 25px, transparent 25px 48px);
            opacity: .75; animation: rr-road-dashes .6s linear infinite;
        }
        .rr-intro-car { position: absolute; top: 2px; z-index: 2; font-size: 25px; filter: drop-shadow(0 0 7px currentColor); }
        .rr-intro-car.one { left: -55px; color: #ff5353; animation: rr-car-left 1.15s cubic-bezier(.2,.75,.25,1) .1s forwards; }
        .rr-intro-car.two { right: -55px; color: #4de1ff; transform: scaleX(-1); animation: rr-car-right 1.15s cubic-bezier(.2,.75,.25,1) .25s forwards; }
        .rr-intro-car.three { left: 46%; top: -34px; color: #ffd84d; animation: rr-car-top .9s cubic-bezier(.2,.75,.25,1) .48s forwards; }
        #rr-enter-game {
            min-width: min(310px, 84vw); min-height: 56px; padding: 14px 24px;
            border: 2px solid #ffe36b; border-radius: 10px; color: #15100a;
            background: linear-gradient(135deg, #fff1a8, #ffc928 55%, #e69a00);
            box-shadow: 0 0 0 1px rgba(255,255,255,.12) inset, 0 0 26px rgba(255,190,25,.28), 0 8px 0 #8c5700;
            font: 900 clamp(10px, 1.5vw, 13px) 'Press Start 2P', monospace;
            cursor: pointer; opacity: 0; transform: translateY(12px);
            animation: rr-button-in .55s ease 1.35s forwards;
            transition: transform .18s ease, box-shadow .18s ease, filter .18s ease;
        }
        #rr-enter-game:hover { transform: translateY(-3px) scale(1.025); filter: brightness(1.08); box-shadow: 0 0 34px rgba(255,190,25,.5), 0 11px 0 #8c5700; }
        #rr-enter-game:active { transform: translateY(4px); box-shadow: 0 0 18px rgba(255,190,25,.3), 0 3px 0 #8c5700; }
        #rr-enter-game:focus-visible { outline: 3px solid #fff; outline-offset: 5px; }
        #main-menu.rr-menu-not-yet { visibility: hidden; }
        @keyframes rr-logo-arrive { 0% { opacity: 0; transform: translateY(65px) scale(.82); } 72% { opacity: 1; transform: translateY(-7px) scale(1.015); } 100% { opacity: 1; transform: translateY(0) scale(1); } }
        @keyframes rr-caption-in { to { opacity: 1; } }
        @keyframes rr-button-in { to { opacity: 1; transform: translateY(0); } }
        @keyframes rr-road-flow { to { background-position: 0 180px; } }
        @keyframes rr-road-dashes { to { transform: translateX(-48px); } }
        @keyframes rr-car-left { to { left: calc(50% - 68px); } }
        @keyframes rr-car-right { to { right: calc(50% - 68px); } }
        @keyframes rr-car-top { to { top: 5px; } }
        @media (max-height: 620px) { #rr-intro-logo { width: min(88vw, 1100px); max-height: calc(100vh - 150px); } #rr-intro-content { gap: 8px; } #rr-intro-track { height: 32px; } #rr-intro-track::before { top: 14px; } #rr-enter-game { min-height: 46px; padding: 10px 18px; } }
        @media (max-width: 700px) {
            #rr-intro-content { width: 100%; gap: clamp(8px, 1.5vh, 14px); }
            #rr-intro-logo { width: min(96vw, 900px); max-height: min(62vh, calc(100vh - 190px)); }
            #rr-intro-caption { font-size: clamp(8px, 2.6vw, 12px); }
            #rr-intro-track { width: min(460px, 92vw); }
        }
        @media (prefers-reduced-motion: reduce) {
            #rr-intro-screen *, #rr-intro-screen *::before { animation-duration: .01ms !important; animation-iteration-count: 1 !important; transition-duration: .01ms !important; }
            #rr-intro-logo, #rr-intro-caption, #rr-intro-track, #rr-enter-game { opacity: 1; transform: none; }
        }

    
