    <canvas id="gameCanvas" width="640" height="480"></canvas>

    <!-- Controles Mobile -->
    <div id="mobile-controls">
        <div class="ctrl-group">
            <button class="m-btn" id="btn-left">◀</button>
            <button class="m-btn" id="btn-right">▶</button>
        </div>
