            <button class="m-btn" id="btn-pit" style="color:#00ffff; font-size:12px; width:65px;">PIT</button>
            <button class="m-btn" id="btn-brake" style="color:red">B</button>
            <button class="m-btn" id="btn-gas" style="color:green">A</button>
        </div>
    </div>
</div>

<script src="nascar.js"></script>
<script src="rally.js"></script>
<script>
    // Move o resultado para fora do container do jogo para que o fixed cubra toda a janela.
    (function () {
      const resultOverlay = document.getElementById('game-over-menu');
      if (resultOverlay && resultOverlay.parentElement !== document.body) document.body.appendChild(resultOverlay);
    })();

    // A abertura só controla a passagem para o menu; não altera corrida, física ou progresso.
    (function initRetroRacingIntro() {
      const intro = document.getElementById('rr-intro-screen');
      const enter = document.getElementById('rr-enter-game');
      const menu = document.getElementById('main-menu');
      if (!intro || !enter || !menu) return;
      let entered = false;
      function enterMenu() {
        if (entered) return;
        entered = true;
        intro.classList.add('rr-intro-leaving');
        menu.classList.remove('rr-menu-not-yet');
        window.setTimeout(() => { intro.remove(); }, 750);
      }
      enter.addEventListener('click', enterMenu);
      enter.addEventListener('keydown', event => {
        if (event.key === 'Enter' || event.key === ' ') { event.preventDefault(); enterMenu(); }
      });
    })();

    const canvas = document.getElementById('gameCanvas');
    const ctx = canvas.getContext('2d', { alpha: false }); 
    
    const trophyCanvas = document.getElementById('trophyCanvas');
    const tCtx = trophyCanvas.getContext('2d');

    const hud = document.getElementById('hud');
    const mainMenu = document.getElementById('main-menu');
    const gameOverMenu = document.getElementById('game-over-menu');
    const returnHomeBtn = document.getElementById('return-home-btn');
    if (returnHomeBtn) returnHomeBtn.addEventListener('click', function () {
        gameOverMenu.classList.add('hidden');
        mainMenu.classList.remove('hidden');
        hud.classList.add('hidden');
        if (mControls) mControls.style.display = 'none';
        if (typeof state !== 'undefined') state = 'MENU';
    });
    const mControls = document.getElementById('mobile-controls');
    const cutsceneTitle = document.getElementById('cutscene-title');
    const lights = [document.getElementById('l1'), document.getElementById('l2'), document.getElementById('l3'), document.getElementById('l4'), document.getElementById('l5')];

    let playerCarColor = '#e10600';
    let playerHelmetColor = '#ffcc00';

    const FPS = 60;
    const STEP = 1/FPS;
    const WIDTH = canvas.width;
    const HEIGHT = canvas.height;
    const RESOLUTION = HEIGHT / 480; 
    
    const SEGMENT_LENGTH = 200;
    const RUMBLE_LENGTH = 3;
    let TRACK_WIDTH = 1350;
    let LANES = 3;
    const FOV = 100;
    let cameraHeight = 1500; 
    const CAMERA_DEPTH = 1 / Math.tan((FOV/2) * Math.PI/180);
    const DRAW_DISTANCE = 300; 
    const PLAYER_Z = (cameraHeight * CAMERA_DEPTH); 

    const MAX_SPEED = SEGMENT_LENGTH / STEP; 
    const ACCEL =  MAX_SPEED / 3.8;          
    const BREAKING = -MAX_SPEED * 1.6;             
    const DECEL = -MAX_SPEED / 5.0;          
    let OFF_ROAD_DECEL = -MAX_SPEED * 0.95; 
    let OFF_ROAD_LIMIT =  MAX_SPEED / 4.0; 
    const CENTRIFUGAL = 0.21;                

    const COLORS = {
        FOG:  '#7bc1df', 
        LIGHT:  { road: '#6B6B6B', grass: '#42b035', rumble: '#ffffff', lane: '#CCCCCC'  },
        DARK:   { road: '#696969', grass: '#399c2d', rumble: '#d00000'                   },
        START:  { road: '#6B6B6B', grass: '#42b035', rumble: '#ffffff', type: 'START'    },
        FINISH: { road: '#696969', grass: '#399c2d', rumble: '#000000', type: 'FINISH'   }
    };
    
    let currentStage = 0;
    const F1_STAGES = [
        {
            name: "FASE 1: GP DA PRAIA - DIA ENSOLARADO ☀️",
            laps: 3,
            weather: "CLEAR",
            theme: "BEACH",
            aiSpeedFactor: 0.98,
            build: function() {
                addRoad(200, 200, 200, 0, 0);
                addRoad(50, 40, 50, 6, 10);
                addRoad(180, 180, 180, 0, 0);
                addRoad(50, 40, 50, -7, -10);
                addRoad(220, 220, 220, 0, 0);
                addRoad(60, 60, 60, 7, 0);
                addRoad(150, 150, 150, 0, 0);
            }
        },
        {
            name: "FASE 2: GP DA BÉLGICA - PÔR DO SOL 🌅",
            laps: 3,
            weather: "SUNSET",
            theme: "MOUNTAIN",
            aiSpeedFactor: 1.0,
            build: function() {
                addRoad(100, 100, 100, 0, 0);
                addRoad(40, 30, 40, -7, 30);
                addRoad(60, 60, 60, 5, 50);
                addRoad(280, 280, 280, 0, 0);
                addRoad(50, 50, 50, -6, -20);
                addRoad(50, 50, 50, 6, 0);
                addRoad(180, 180, 180, 0, -30);
                addRoad(70, 70, 70, -7, 0);
            }
        },
        {
            name: "FASE 3: CIRCUIT DA COSTA - PÔR DO SOL 🌅",
            laps: 3,
            weather: "SUNSET",
            theme: "BEACH",
            aiSpeedFactor: 1.02,
            build: function() {
                addRoad(160, 160, 160, 0, 0);
                addRoad(45, 45, 45, -7, -15);
                addRoad(45, 45, 45, 7, 15);
                addRoad(250, 250, 250, 0, 0);
                addRoad(60, 60, 60, -8, -20);
                addRoad(180, 180, 180, 0, 0);
                addRoad(70, 70, 70, 7, 0);
                addRoad(140, 140, 140, 0, 0);
            }
        },
        {
            name: "FASE 4: GP DE MÔNACO - TEMPESTADE 🌧️⚡",
            laps: 3,
            weather: "RAIN",
            theme: "MOUNTAIN",
            aiSpeedFactor: 1.03,
            build: function() {
                addRoad(70, 70, 70, 0, 0);
                addRoad(40, 40, 40, 8, 25);
                addRoad(120, 120, 120, 0, 30);
                addRoad(40, 40, 40, -8, -15);
                addRoad(30, 30, 30, 9, -20);
                addRoad(150, 150, 150, 0, 0);
                addRoad(35, 35, 35, -8, 0);
                addRoad(35, 35, 35, 8, 0);
                addRoad(90, 90, 90, 0, 0);
            }
        },
        {
            name: "FASE FINAL: TEMPESTADE NA PRAIA 🌧️⚡",
            laps: 3,
            weather: "RAIN",
            theme: "BEACH",
            aiSpeedFactor: 1.05,
            build: function() {
                addRoad(180, 180, 180, 0, 0);
                addRoad(50, 40, 50, 8, 20);
                addRoad(50, 40, 50, -8, -20);
                addRoad(280, 280, 280, 0, 0);
                addRoad(70, 70, 70, -9, 0);
                addRoad(200, 200, 200, 0, 0);
                addRoad(60, 60, 60, 8, 0);
                addRoad(160, 160, 160, 0, 0);
            }
        }
    ];

    // Série ativa: Fórmula 1 por padrão. NASCAR fica em nascar.js.
    let STAGES = F1_STAGES;
    let currentSeries = 'F1';

    function getSeriesLabel() {
        if (currentSeries === 'NASCAR') return 'NASCAR';
        if (currentSeries === 'RALLY') return 'RALLY WRC';
        return 'FÓRMULA 1';
    }

    const CAMPAIGN_STORAGE_KEY = 'retroRacingCampaign_v1';
    function readCampaign() {
        try { return JSON.parse(localStorage.getItem(CAMPAIGN_STORAGE_KEY) || '{}') || {}; }
        catch (e) { return {}; }
    }
    function writeCampaign(data) {
        try { localStorage.setItem(CAMPAIGN_STORAGE_KEY, JSON.stringify(data)); } catch (e) {}
    }
    function getCampaignSeries() {
        const data = readCampaign();
        if (!data[currentSeries]) data[currentSeries] = { unlocked: 0, completed: [], champion: false };
        if (!Array.isArray(data[currentSeries].completed)) data[currentSeries].completed = [];
        data[currentSeries].unlocked = Math.max(0, Math.min(STAGES.length - 1, Number(data[currentSeries].unlocked) || 0));
        return { all: data, series: data[currentSeries] };
    }
    function refreshCampaignUI() {
        const stageSelect = document.getElementById('stage-select');
        const campaign = getCampaignSeries().series;
        if (stageSelect) {
            Array.from(stageSelect.options).forEach((option, index) => {
                const stageName = STAGES[index] ? (STAGES[index].menuName || STAGES[index].name || `Fase ${index + 1}`) : option.textContent;
                option.textContent = index <= campaign.unlocked ? `🏁 ${stageName}` : `🔒 ${stageName}`;
                option.disabled = index > campaign.unlocked;
            });
            if (currentStage > campaign.unlocked) currentStage = campaign.unlocked;
            stageSelect.value = String(currentStage);
        }
        const progress = document.getElementById('campaign-progress');
        if (progress) {
            const done = campaign.completed.length;
            progress.innerHTML = `<b>🏁 CAMPANHA ${getSeriesLabel()}</b><br>Fases concluídas: ${done}/${STAGES.length} · Próxima liberada: ${Math.min(campaign.unlocked + 1, STAGES.length)}/${STAGES.length}<br>${campaign.champion ? '🏆 TROFÉU OURO CONQUISTADO NESTA MODALIDADE!' : 'Regra: termine no TOP 3 para desbloquear a próxima fase. A fase final exige 1º lugar para o troféu.'}`;
        }
    }
    function recordCampaignResult(positionResult) {
        const data = readCampaign();
        const campaign = data[currentSeries] || { unlocked: 0, completed: [], champion: false };
        if (!Array.isArray(campaign.completed)) campaign.completed = [];
        if (positionResult <= 3) {
            if (!campaign.completed.includes(currentStage)) campaign.completed.push(currentStage);
            if (currentStage < STAGES.length - 1) campaign.unlocked = Math.max(Number(campaign.unlocked) || 0, currentStage + 1);
            if (currentStage === STAGES.length - 1 && positionResult === 1) campaign.champion = true;
        }
        data[currentSeries] = campaign;
        writeCampaign(data);
        refreshCampaignUI();
        return campaign;
    }
    function playVictoryFanfare(pos) {
        try {
            initAudio();
            const AC = window.AudioContext || window.webkitAudioContext;
            if (!AC) return;
            const ctxAudio = (typeof audioCtx !== 'undefined' && audioCtx) ? audioCtx : new AC();
            if (ctxAudio.state === 'suspended') ctxAudio.resume();
            const now = ctxAudio.currentTime;
            const p = (typeof pos === 'number' && pos > 0) ? pos : playerPos;

            // Síntese de aplausos da torcida (ruído rosa / filtrado simulando palmas)
            function playCrowdApplause(intensity, duration) {
                const bufferSize = ctxAudio.sampleRate * duration;
                const buffer = ctxAudio.createBuffer(1, bufferSize, ctxAudio.sampleRate);
                const data = buffer.getChannelData(0);
                let lastOut = 0.0;
                for (let i = 0; i < bufferSize; i++) {
                    const white = Math.random() * 2 - 1;
                    lastOut = (lastOut * 0.92) + (white * 0.08);
                    const clapPuffs = Math.sin(i / 900) * Math.sin(i / 1350);
                    data[i] = (lastOut * 0.6 + white * 0.4 * clapPuffs);
                }
                const noise = ctxAudio.createBufferSource();
                noise.buffer = buffer;
                const filter = ctxAudio.createBiquadFilter();
                filter.type = 'bandpass';
                filter.frequency.value = 1100;
                filter.Q.value = 1.2;
                const gain = ctxAudio.createGain();
                gain.gain.setValueAtTime(0.001, now);
                gain.gain.linearRampToValueAtTime(intensity, now + 0.35);
                gain.gain.exponentialRampToValueAtTime(0.0001, now + duration);
                noise.connect(filter);
                filter.connect(gain);
                gain.connect(ctxAudio.destination);
                noise.start(now);
                noise.stop(now + duration);
            }

            if (p === 1) {
                // 1º Lugar: Fanfarra Épica Triunfante e Aplausos Efusivos
                const notes = [
                    { f: 523.25, t: 0.0, d: 0.16 }, // C5
                    { f: 523.25, t: 0.16, d: 0.16 }, // C5
                    { f: 523.25, t: 0.32, d: 0.16 }, // C5
                    { f: 659.25, t: 0.48, d: 0.38 }, // E5
                    { f: 523.25, t: 0.88, d: 0.16 }, // C5
                    { f: 659.25, t: 1.04, d: 0.22 }, // E5
                    { f: 783.99, t: 1.28, d: 0.65 }, // G5
                    { f: 1046.50, t: 1.95, d: 1.10 } // C6 (agudo triunfal)
                ];
                notes.forEach(n => {
                    const osc = ctxAudio.createOscillator();
                    const gain = ctxAudio.createGain();
                    osc.type = 'sawtooth';
                    osc.frequency.setValueAtTime(n.f, now + n.t);
                    gain.gain.setValueAtTime(0.001, now + n.t);
                    gain.gain.exponentialRampToValueAtTime(0.14, now + n.t + 0.04);
                    gain.gain.exponentialRampToValueAtTime(0.0001, now + n.t + n.d);
                    osc.connect(gain);
                    gain.connect(ctxAudio.destination);
                    osc.start(now + n.t);
                    osc.stop(now + n.t + n.d + 0.05);
                });
                playCrowdApplause(0.18, 3.4);
            } else if (p === 2) {
                // 2º Lugar: Música Festiva de Pódio e Aplausos do Público
                const notes = [
                    { f: 440.00, t: 0.0, d: 0.2 }, // A4
                    { f: 554.37, t: 0.2, d: 0.2 }, // C#5
                    { f: 659.25, t: 0.4, d: 0.3 }, // E5
                    { f: 880.00, t: 0.72, d: 0.7 } // A5
                ];
                notes.forEach(n => {
                    const osc = ctxAudio.createOscillator();
                    const gain = ctxAudio.createGain();
                    osc.type = 'triangle';
                    osc.frequency.setValueAtTime(n.f, now + n.t);
                    gain.gain.setValueAtTime(0.001, now + n.t);
                    gain.gain.exponentialRampToValueAtTime(0.12, now + n.t + 0.03);
                    gain.gain.exponentialRampToValueAtTime(0.0001, now + n.t + n.d);
                    osc.connect(gain);
                    gain.connect(ctxAudio.destination);
                    osc.start(now + n.t);
                    osc.stop(now + n.t + n.d + 0.04);
                });
                playCrowdApplause(0.11, 2.6);
            } else if (p === 3) {
                // 3º Lugar: Conclusão de Prova e Palmas Moderadas
                const notes = [
                    { f: 392.00, t: 0.0, d: 0.22 }, // G4
                    { f: 493.88, t: 0.22, d: 0.22 }, // B4
                    { f: 587.33, t: 0.46, d: 0.60 }  // D5
                ];
                notes.forEach(n => {
                    const osc = ctxAudio.createOscillator();
                    const gain = ctxAudio.createGain();
                    osc.type = 'sine';
                    osc.frequency.setValueAtTime(n.f, now + n.t);
                    gain.gain.setValueAtTime(0.001, now + n.t);
                    gain.gain.exponentialRampToValueAtTime(0.10, now + n.t + 0.03);
                    gain.gain.exponentialRampToValueAtTime(0.0001, now + n.t + n.d);
                    osc.connect(gain);
                    gain.connect(ctxAudio.destination);
                    osc.start(now + n.t);
                    osc.stop(now + n.t + n.d + 0.04);
                });
                playCrowdApplause(0.06, 2.0);
            }
        } catch (e) { /* áudio bloqueado pelo navegador: efeitos visuais continuam */ }
    }

    function setSeries(series) {
        // A categoria é controlada pelo index.php, enquanto a lógica específica
        // de cada modalidade fica em seus módulos (nascar.js e rally.js).
        if (series === 'NASCAR') currentSeries = 'NASCAR';
        else if (series === 'RALLY') currentSeries = 'RALLY';
        else currentSeries = 'F1';

        if (currentSeries === 'NASCAR' && !window.NASCAR_CONFIG) {
            console.error('nascar.js não foi carregado.');
            alert('O módulo NASCAR não foi carregado. Verifique se nascar.js está na mesma pasta do index.php.');
            currentSeries = 'F1';
        }
        if (currentSeries === 'RALLY' && !window.RALLY_CONFIG) {
            console.error('rally.js não foi carregado.');
            alert('O módulo RALLY não foi carregado. Verifique se rally.js está na mesma pasta do index.php.');
            currentSeries = 'F1';
        }

        if (currentSeries === 'NASCAR') {
            STAGES = window.NASCAR_CONFIG.stages;
            TRACK_WIDTH = 2200; // Pista bem mais larga estilo Super Speedway
            LANES = 4;
        } else if (currentSeries === 'RALLY') {
            STAGES = window.RALLY_CONFIG.stages;
            TRACK_WIDTH = 1250; // Pista técnica de terra estreita
            LANES = 2;          // Sulcos duplos de terra batida
        } else {
            STAGES = F1_STAGES;
            TRACK_WIDTH = 1350;
            LANES = 3;
        }
        currentStage = 0;

        const stageSelect = document.getElementById('stage-select');
        if (stageSelect) {
            stageSelect.innerHTML = STAGES.map((stage, i) =>
                `<option value="${i}">${stage.menuName || stage.name}</option>`
            ).join('');
            stageSelect.value = '0';
        }

        const f1Btn = document.getElementById('f1-series-btn');
        const nascarBtn = document.getElementById('nascar-series-btn');
        const rallyBtn = document.getElementById('rally-series-btn');
        const desc = document.getElementById('series-description');

        if (f1Btn) f1Btn.classList.toggle('active', currentSeries === 'F1');
        if (nascarBtn) nascarBtn.classList.toggle('active', currentSeries === 'NASCAR');
        if (rallyBtn) rallyBtn.classList.toggle('active', currentSeries === 'RALLY');

        if (desc) {
            if (currentSeries === 'NASCAR') {
                desc.innerText = 'NASCAR • stock cars • ovais e circuitos de alta velocidade';
            } else if (currentSeries === 'RALLY') {
                desc.innerText = 'RALLY WRC • 4x4 e Grupo B • pistas de terra, rampas de salto e derrapagens radicais';
            } else {
                desc.innerText = 'FÓRMULA 1 • monopostos • circuitos de Grand Prix';
            }
        }

        refreshCampaignUI();

        const nascarModelGroup = document.getElementById('nascar-model-group');
        if (nascarModelGroup) {
            nascarModelGroup.classList.toggle('hidden', currentSeries !== 'NASCAR');
        }

        const rallyModelGroup = document.getElementById('rally-model-group');
        if (rallyModelGroup) {
            rallyModelGroup.classList.toggle('hidden', currentSeries !== 'RALLY');
        }

        const narrTitle = document.getElementById('narrator-title');
        if (narrTitle) {
            if (currentSeries === 'RALLY') narrTitle.innerText = '🎙️ CO-PILOTO WRC';
            else if (currentSeries === 'NASCAR') narrTitle.innerText = '🎙️ NARRADOR NASCAR';
            else narrTitle.innerText = '🎙️ GALVÃO RETRO';
        }

        // Regenera os sprites para a categoria selecionada (F1 vs NASCAR Stock Car vs RALLY WRC)
        if (typeof generateSprites === 'function') generateSprites();

        // Atualiza imediatamente a prévia do cenário, pista e clima do menu.
        if (typeof updateMenuPreview === 'function') updateMenuPreview();
    }

    // NARRATOR & RIVAL DRIVERS SYSTEM
    const narratorBox = document.getElementById('narrator-box');
    const narratorAvatarCanvas = document.getElementById('narrator-avatar');
    const nCtx = narratorAvatarCanvas ? narratorAvatarCanvas.getContext('2d') : null;
    const narratorTextEl = document.getElementById('narrator-text');

    let narratorState = {
        currentText: "PREPARE-SE PARA A LARGADA!",
        displayedText: "",
        charIdx: 0,
        typeTimer: 0,
        holdTimer: 0,
        isSpeaking: false,
        expression: 'NORMAL',
        priority: 0,
        lastCategory: '',
        mouthOpen: false,
        mouthTimer: 0
    };

    const AI_DRIVERS = [
        { name: "Senninha", team: "Lotus", colorName: "Verde", speedFactor: 1.05, accelFactor: 1.06, aggressiveness: 0.85 },
        { name: "Verstappen", team: "RedBull", colorName: "Ciano", speedFactor: 1.04, accelFactor: 1.05, aggressiveness: 0.90 },
        { name: "Hamilton", team: "Mercedes", colorName: "Laranja", speedFactor: 1.02, accelFactor: 1.03, aggressiveness: 0.75 },
        { name: "Schumi", team: "Benetton", colorName: "Roxa", speedFactor: 1.01, accelFactor: 1.02, aggressiveness: 0.80 },
        { name: "Alonso", team: "Renault", colorName: "Amarela", speedFactor: 1.00, accelFactor: 1.00, aggressiveness: 0.65 },
