    function drawProceduralCarSprite(ctx, x, y, width, height, bodyColor, accentColor, turn, helmetColor) {
        ctx.save();
        ctx.translate(x + width / 2, y + height / 2);
        
        if (turn === -1) ctx.rotate(-0.06);
        if (turn === 1) ctx.rotate(0.06);

        ctx.fillStyle = 'rgba(0,0,0,0.35)';
        ctx.beginPath();
        ctx.ellipse(0, 32, 50, 10, 0, 0, Math.PI * 2);
        ctx.fill();

        ctx.fillStyle = '#111111';
        ctx.fillRect(-52, 10, 20, 28);
        ctx.fillRect(32, 10, 20, 28);
        ctx.fillStyle = '#444444';
        ctx.fillRect(-49, 14, 14, 20);
        ctx.fillRect(35, 14, 14, 20);

        let steer = turn * 0.12;
        ctx.save(); ctx.translate(-42, -22); ctx.rotate(steer);
        ctx.fillStyle = '#111111'; ctx.fillRect(-7, -10, 14, 20);
        ctx.fillStyle = '#444444'; ctx.fillRect(-5, -7, 10, 14);
        ctx.restore();

        ctx.save(); ctx.translate(42, -22); ctx.rotate(steer);
        ctx.fillStyle = '#111111'; ctx.fillRect(-7, -10, 14, 20);
        ctx.fillStyle = '#444444'; ctx.fillRect(-5, -7, 10, 14);
        ctx.restore();

        ctx.fillStyle = accentColor || '#ffffff';
        ctx.fillRect(-44, -36, 88, 7);
        ctx.fillStyle = bodyColor;
        ctx.fillRect(-48, -40, 8, 12);
        ctx.fillRect(40, -40, 8, 12);

        ctx.fillStyle = bodyColor;
        ctx.beginPath();
        ctx.moveTo(0, -36);
        ctx.lineTo(14, -8);
        ctx.lineTo(22, 24);
        ctx.lineTo(-22, 24);
        ctx.lineTo(-14, -8);
        ctx.closePath();
        ctx.fill();

        ctx.fillRect(-32, -4, 14, 28);
        ctx.fillRect(18, -4, 14, 28);
        ctx.fillStyle = accentColor || '#ffffff';
        ctx.fillRect(-30, -4, 10, 5);
        ctx.fillRect(20, -4, 10, 5);

        ctx.fillStyle = '#111111';
        ctx.beginPath();
        ctx.ellipse(0, -2, 9, 14, 0, 0, Math.PI * 2);
        ctx.fill();

        ctx.fillStyle = helmetColor || '#ffcc00';
        ctx.beginPath();
        ctx.arc(0, -4, 6, 0, Math.PI * 2);
        ctx.fill();
        ctx.fillStyle = '#111111';
        ctx.fillRect(-3, -7, 6, 3);

        ctx.fillStyle = bodyColor;
        ctx.beginPath(); ctx.arc(0, 8, 7, 0, Math.PI * 2); ctx.fill();
        ctx.fillStyle = '#000000';
        ctx.beginPath(); ctx.arc(0, 8, 3.5, 0, Math.PI * 2); ctx.fill();

        ctx.fillStyle = '#222222';
        ctx.fillRect(-10, 20, 5, 12);
        ctx.fillRect(5, 20, 5, 12);

        ctx.fillStyle = bodyColor;
        ctx.fillRect(-44, 26, 88, 11);
        ctx.fillStyle = accentColor || '#ffffff';
        ctx.fillRect(-40, 28, 80, 7);

        ctx.fillStyle = '#ff0000';
        ctx.fillRect(-3, 33, 6, 4);

        ctx.restore();
    }

    function generateSprites() {
        sCtx.clearRect(0, 0, spriteCanvas.width, spriteCanvas.height);

        const nascarModelSelect = document.getElementById('nascar-model-select');
        const selectedNascarModel = nascarModelSelect ? nascarModelSelect.value : 'SUPERBIRD';
        const rallyModelSelect = document.getElementById('rally-model-select');
        const selectedRallyModel = rallyModelSelect ? rallyModelSelect.value : 'SUBARU';

        const drawPlayer = currentSeries === 'NASCAR' ? window.drawNascarSprite
                         : (currentSeries === 'RALLY' ? window.drawRallySprite : drawProceduralCarSprite);
        const selectedModel = currentSeries === 'NASCAR' ? selectedNascarModel : selectedRallyModel;

        drawPlayer(sCtx, SPRITES.PLAYER_STRAIGHT.x, SPRITES.PLAYER_STRAIGHT.y, SPRITES.PLAYER_STRAIGHT.w, SPRITES.PLAYER_STRAIGHT.h, playerCarColor, '#ffffff', 0, playerHelmetColor, selectedModel);
        drawPlayer(sCtx, SPRITES.PLAYER_LEFT.x, SPRITES.PLAYER_LEFT.y, SPRITES.PLAYER_LEFT.w, SPRITES.PLAYER_LEFT.h, playerCarColor, '#ffffff', -1, playerHelmetColor, selectedModel);
        drawPlayer(sCtx, SPRITES.PLAYER_RIGHT.x, SPRITES.PLAYER_RIGHT.y, SPRITES.PLAYER_RIGHT.w, SPRITES.PLAYER_RIGHT.h, playerCarColor, '#ffffff', 1, playerHelmetColor, selectedModel);

        const aiF1Colors = [
            { body: '#0055ff', accent: '#ffff00' }, 
            { body: '#00aa33', accent: '#ffffff' }, 
            { body: '#ff6600', accent: '#000000' }, 
            { body: '#9900cc', accent: '#ffcc00' }, 
            { body: '#e6b800', accent: '#000000' }, 
            { body: '#00cccc', accent: '#ffffff' }  
        ];

        const aiNascarConfigs = [
            { body: '#00a3e0', accent: '#ffffff', model: 'SUPERBIRD' },   // Plymouth Superbird "The King"
            { body: '#0055ff', accent: '#ffff00', model: 'NEXTGEN' },     // Hendrick Next-Gen #88
            { body: '#111111', accent: '#dc2626', model: 'MONTE_CARLO' }, // Earnhardt #3 Aerocoupe
            { body: '#f97316', accent: '#000000', model: 'SUPERBIRD' },   // Orange Road Runner Superbird
            { body: '#059669', accent: '#ffffff', model: 'TRUCK' },        // Craftsman Truck
            { body: '#ea580c', accent: '#fef08a', model: 'NEXTGEN' }       // #20 Cup Car
        ];

        const aiRallyConfigs = [
            { body: '#003893', accent: '#facc15', model: 'SUBARU' },       // Subaru Impreza WRC 555
            { body: '#f8fafc', accent: '#facc15', model: 'AUDI_QUATTRO' }, // Audi Sport Quattro S1 E2
            { body: '#dc2626', accent: '#ffffff', model: 'LANCER_EVO' },   // Mitsubishi Lancer Evo VI
            { body: '#ffffff', accent: '#16a34a', model: 'LANCIA_STRATOS' },// Lancia Stratos HF Alitalia
            { body: '#1e3a8a', accent: '#f59e0b', model: 'SUBARU' },       // Petter Solberg WRC
            { body: '#991b1b', accent: '#f8fafc', model: 'LANCER_EVO' }    // Ralliart Red Evo
        ];

        for (let i = 0; i < 6; i++) {
            let carKey = 'CAR0' + (i + 1);
            let carX = SPRITE_WIDTH * (i % 3);
            let carY = 800 + (Math.floor(i / 3) * SPRITE_HEIGHT);

            if (currentSeries === 'NASCAR' && window.drawNascarSprite) {
                let conf = aiNascarConfigs[i % aiNascarConfigs.length];
                window.drawNascarSprite(sCtx, carX, carY, 120, 90, conf.body, conf.accent, 0, '#ffffff', conf.model);
            } else if (currentSeries === 'RALLY' && window.drawRallySprite) {
                let conf = aiRallyConfigs[i % aiRallyConfigs.length];
                window.drawRallySprite(sCtx, carX, carY, 120, 90, conf.body, conf.accent, 0, '#ffffff', conf.model);
            } else {
                drawProceduralCarSprite(sCtx, carX, carY, 120, 90, aiF1Colors[i].body, aiF1Colors[i].accent, 0);
            }
            SPRITES[carKey] = { x: carX, y: carY, w: 120, h: 90 };
        }

        sCtx.fillStyle = '#d00'; sCtx.fillRect(SPRITES.BILLBOARD.x, SPRITES.BILLBOARD.y, SPRITES.BILLBOARD.w, SPRITES.BILLBOARD.h);
        sCtx.fillStyle = '#fff'; sCtx.font = '20px "Press Start 2P"';
        sCtx.fillText("VIRTUAL", SPRITES.BILLBOARD.x + 20, SPRITES.BILLBOARD.y + 40);
        sCtx.fillText("RACING", SPRITES.BILLBOARD.x + 30, SPRITES.BILLBOARD.y + 70);

        sCtx.fillStyle = '#422'; sCtx.fillRect(SPRITES.TREE.x + 40, SPRITES.TREE.y + 130, 20, 70); 
        sCtx.fillStyle = '#052'; sCtx.beginPath(); sCtx.arc(SPRITES.TREE.x + 50, SPRITES.TREE.y + 110, 45, 0, Math.PI*2); sCtx.fill();
        sCtx.fillStyle = '#072'; sCtx.beginPath(); sCtx.arc(SPRITES.TREE.x + 50, SPRITES.TREE.y + 60, 45, 0, Math.PI*2); sCtx.fill();

        sCtx.save(); sCtx.translate(SPRITES.GRANDSTAND.x, SPRITES.GRANDSTAND.y);
        sCtx.fillStyle = '#555'; sCtx.fillRect(0, 50, 300, 100); 
        sCtx.fillStyle = '#eee'; sCtx.beginPath(); sCtx.moveTo(0, 0); sCtx.lineTo(300, 0); sCtx.lineTo(280, 40); sCtx.lineTo(20, 40); sCtx.fill();
        for(let i = 0; i < 300; i += 40) { sCtx.fillStyle = '#d00'; sCtx.beginPath(); sCtx.moveTo(i, 0); sCtx.lineTo(i+20, 0); sCtx.lineTo(i+15, 40); sCtx.lineTo(i-5, 40); sCtx.fill(); }
        sCtx.fillStyle = '#222'; sCtx.beginPath(); sCtx.moveTo(20, 50); sCtx.lineTo(280, 50); sCtx.lineTo(300, 150); sCtx.lineTo(0, 150); sCtx.fill(); 
        const colors = ['#f00', '#0f0', '#00f', '#ff0', '#fff', '#f80', '#0ff'];
        for(let i = 0; i < 250; i++) { sCtx.fillStyle = colors[Math.floor(Math.random() * colors.length)]; sCtx.fillRect(10 + Math.random() * 280, 55 + Math.random() * 85, 4, 4); }
        sCtx.restore();

        // Inicializa sprites adicionais da NASCAR se o módulo estiver carregado
        if (window.initNascarSprites) {
            window.initNascarSprites(sCtx, SPRITES);
        }

        // Inicializa sprites adicionais de RALLY se o módulo estiver carregado
        if (window.initRallySprites) {
            window.initRallySprites(sCtx, SPRITES);
        }

        sCtx.save(); sCtx.translate(SPRITES.ROCK.x, SPRITES.ROCK.y);
        sCtx.fillStyle = '#666'; sCtx.beginPath(); sCtx.moveTo(20, 100); sCtx.lineTo(50, 30); sCtx.lineTo(90, 10); sCtx.lineTo(130, 40); sCtx.lineTo(150, 100); sCtx.fill();
        sCtx.restore();

        sCtx.save(); sCtx.translate(SPRITES.PALM_TREE.x, SPRITES.PALM_TREE.y);
        sCtx.fillStyle = '#853'; sCtx.beginPath(); sCtx.moveTo(60, 250); sCtx.quadraticCurveTo(90, 150, 95, 60); sCtx.lineTo(80, 60); sCtx.quadraticCurveTo(70, 150, 40, 250); sCtx.fill();
        sCtx.fillStyle = '#282'; 
        for(let a = 0; a < Math.PI * 2; a += Math.PI / 4) {
            sCtx.beginPath(); sCtx.moveTo(87, 60); let lx = 87 + Math.cos(a) * 70; let ly = 60 + Math.sin(a) * 40 + 30;
            sCtx.quadraticCurveTo(87 + Math.cos(a)*30, 60 + Math.sin(a)*10, lx, ly); sCtx.fill();
        }
        sCtx.restore();

        sCtx.save(); sCtx.translate(SPRITES.TENT.x, SPRITES.TENT.y);
        sCtx.fillStyle = '#eee'; sCtx.beginPath(); sCtx.moveTo(0, 100); sCtx.lineTo(30, 20); sCtx.lineTo(120, 20); sCtx.lineTo(150, 100); sCtx.fill();
        sCtx.restore();

        sCtx.save(); sCtx.translate(SPRITES.TIRE_BARRIER.x, SPRITES.TIRE_BARRIER.y);
        for(let row = 0; row < 2; row++) {
            for(let col = 0; col < 5; col++) {
                let px = col * 30; let py = row * 35;
                let color = (col + row) % 2 === 0 ? '#cc0000' : '#ffffff';
                sCtx.fillStyle = '#111'; sCtx.beginPath(); sCtx.ellipse(px + 15, py + 20, 14, 18, 0, 0, Math.PI*2); sCtx.fill();
                sCtx.fillStyle = color; sCtx.beginPath(); sCtx.ellipse(px + 15, py + 15, 12, 14, 0, 0, Math.PI*2); sCtx.fill();
                sCtx.fillStyle = '#222'; sCtx.beginPath(); sCtx.ellipse(px + 15, py + 15, 6, 7, 0, 0, Math.PI*2); sCtx.fill();
            }
        }
        sCtx.restore();

        sCtx.save(); sCtx.translate(SPRITES.FLAG_MARSHAL.x, SPRITES.FLAG_MARSHAL.y);
        sCtx.fillStyle = '#ffcc00'; sCtx.fillRect(40, 50, 20, 40); 
        sCtx.fillStyle = '#000'; sCtx.fillRect(44, 90, 6, 25); sCtx.fillRect(52, 90, 6, 25); 
        sCtx.fillStyle = '#ffdbac'; sCtx.beginPath(); sCtx.arc(50, 40, 9, 0, Math.PI*2); sCtx.fill(); 
        sCtx.fillStyle = '#d00'; sCtx.fillRect(40, 30, 20, 6); 
        sCtx.fillStyle = '#ffdbac'; sCtx.fillRect(55, 45, 15, 5);
        sCtx.fillStyle = '#aaa'; sCtx.fillRect(70, 10, 4, 70); 
        let tileSize = 8;
        for(let r=0; r<4; r++) {
            for(let c=0; c<5; c++) {
                sCtx.fillStyle = (r+c)%2===0 ? '#ffffff' : '#000000';
                sCtx.fillRect(74 + (c*tileSize), 10 + (r*tileSize), tileSize, tileSize);
            }
        }
        sCtx.restore();

        // DESENHO PROCEDURAL DA GARAGEM DO PIT STOP
        sCtx.save(); sCtx.translate(SPRITES.PIT_GARAGE.x, SPRITES.PIT_GARAGE.y);
        sCtx.fillStyle = '#222222'; sCtx.fillRect(0, 0, 220, 120);
        sCtx.fillStyle = '#cc0000'; sCtx.fillRect(0, 0, 220, 25);
        sCtx.fillStyle = '#ffffff'; sCtx.font = '12px "Press Start 2P"'; sCtx.fillText("PIT BOX", 45, 18);
        sCtx.fillStyle = '#111111'; sCtx.fillRect(20, 35, 180, 85);
        sCtx.fillStyle = '#ffcc00'; sCtx.fillRect(0, 115, 220, 5);
        sCtx.restore();

        // DESENHO PROCEDURAL DA EQUIPE DE MECÂNICOS DO PIT STOP
        sCtx.save(); sCtx.translate(SPRITES.PIT_CREW.x, SPRITES.PIT_CREW.y);
        sCtx.fillStyle = '#0055ff'; 
        sCtx.fillRect(10, 30, 18, 35); sCtx.fillRect(45, 30, 18, 35); 
        sCtx.fillRect(80, 30, 18, 35); sCtx.fillRect(115, 30, 18, 35);
        sCtx.fillStyle = '#ffffff';
        sCtx.beginPath(); sCtx.arc(19, 20, 8, 0, Math.PI*2); sCtx.fill();
        sCtx.beginPath(); sCtx.arc(54, 20, 8, 0, Math.PI*2); sCtx.fill();
        sCtx.beginPath(); sCtx.arc(89, 20, 8, 0, Math.PI*2); sCtx.fill();
        sCtx.beginPath(); sCtx.arc(124, 20, 8, 0, Math.PI*2); sCtx.fill();
        sCtx.fillStyle = '#ffcc00'; sCtx.fillRect(10, 65, 125, 6);
        sCtx.restore();
    }
    generateSprites();

    function playNarratorBeep() {
        if (!isAudioInitialized || !audioCtx) return;
        try {
            let osc = audioCtx.createOscillator();
            let gain = audioCtx.createGain();
            osc.type = 'square';
            osc.frequency.value = 360 + Math.random() * 220;
            gain.gain.setValueAtTime(0.035, audioCtx.currentTime);
            gain.gain.exponentialRampToValueAtTime(0.001, audioCtx.currentTime + 0.04);
            osc.connect(gain);
            gain.connect(audioCtx.destination);
            osc.start();
            osc.stop(audioCtx.currentTime + 0.04);
        } catch(e){}
    }

    function drawNarratorAvatar(dt) {
        if (!nCtx) return;
        nCtx.clearRect(0, 0, 52, 52);

        nCtx.fillStyle = '#0a0f1d';
        nCtx.fillRect(0, 0, 52, 52);

        nCtx.fillStyle = 'rgba(0, 255, 204, 0.08)';
        for(let y=0; y<52; y+=4) {
            nCtx.fillRect(0, y, 52, 2);
        }

        nCtx.fillStyle = '#f4c2c2';
        nCtx.fillRect(16, 14, 20, 24);
        nCtx.fillRect(14, 20, 24, 14);

        nCtx.fillStyle = '#cc0000';
        nCtx.fillRect(12, 10, 28, 7);
        nCtx.fillRect(10, 15, 32, 4);
        nCtx.fillStyle = '#ffffff';
        nCtx.fillRect(22, 11, 8, 3);

        nCtx.fillStyle = '#111111';
        nCtx.fillRect(16, 21, 20, 7);
        nCtx.fillStyle = '#00ffcc';
        nCtx.fillRect(18, 22, 7, 4);
        nCtx.fillRect(27, 22, 7, 4);

        nCtx.fillStyle = '#333333';
        nCtx.fillRect(10, 20, 5, 12);
        nCtx.fillRect(37, 20, 5, 12);
        nCtx.fillStyle = '#ffcc00';
        nCtx.fillRect(11, 22, 3, 8);
        nCtx.fillRect(38, 22, 3, 8);

        nCtx.fillStyle = '#111111';
        nCtx.fillRect(12, 30, 10, 2);
        nCtx.fillRect(20, 32, 4, 4);
        nCtx.fillStyle = '#ff0000';
        nCtx.fillRect(21, 33, 2, 2);

        nCtx.fillStyle = '#1e293b';
        nCtx.fillRect(10, 38, 32, 14);
        nCtx.fillStyle = '#ffffff';
        nCtx.fillRect(23, 38, 6, 14);
        nCtx.fillStyle = '#cc0000';
        nCtx.fillRect(25, 40, 2, 12);

        narratorState.mouthTimer += (dt || 0.016);
        if (narratorState.isSpeaking) {
            if (narratorState.mouthTimer > 0.08) {
                narratorState.mouthOpen = !narratorState.mouthOpen;
                narratorState.mouthTimer = 0;
            }
        } else {
            narratorState.mouthOpen = false;
        }

        nCtx.fillStyle = '#880000';
        if (narratorState.expression === 'SHOCKED') {
            nCtx.beginPath();
            nCtx.arc(26, 33, 4, 0, Math.PI * 2);
            nCtx.fill();
        } else if (narratorState.mouthOpen) {
            nCtx.fillRect(22, 32, 8, 4);
            nCtx.fillStyle = '#ff6666';
            nCtx.fillRect(24, 34, 4, 2);
        } else {
            nCtx.fillRect(22, 33, 8, 2);
        }

        nCtx.strokeStyle = '#00ffcc';
        nCtx.lineWidth = 2;
        nCtx.strokeRect(1, 1, 50, 50);
    }

