    function triggerNarratorEvent(category, driverObj, priority) {
        priority = priority || 1;
        if (narratorState.holdTimer > 0 && priority < narratorState.priority) return;
        if (narratorState.lastCategory === category && category !== 'COLLISION' && narratorState.holdTimer > 1.5) return;

        let list = NARRATOR_QUOTES[category];
        if (!list || list.length === 0) return;

        let quote = Util.randomChoice(list);
        if (driverObj) {
            let dName = driverObj.driverName || "ADVERSÁRIO";
            let dColor = driverObj.colorName || "RIVAL";
            quote = quote.replace(/%DRIVER%/g, dName).replace(/%COLOR%/g, dColor);
        }

        narratorState.currentText = quote;
        narratorState.displayedText = "";
        narratorState.charIdx = 0;
        narratorState.typeTimer = 0;
        narratorState.holdTimer = 3.5;
        narratorState.priority = priority;
        narratorState.isSpeaking = true;
        narratorState.lastCategory = category;

        if (category === 'COLLISION' || category === 'OFFROAD') {
            narratorState.expression = 'SHOCKED';
        } else if (category === 'OVERTAKE' || category === 'LEADER' || category === 'VICTORY' || category === 'SLIPSTREAM') {
            narratorState.expression = 'EXCITED';
        } else {
            narratorState.expression = 'NORMAL';
        }
    }

    function updateNarratorSystem(dt) {
        if (narratorState.holdTimer > 0) {
            narratorState.holdTimer -= dt;
            if (narratorState.holdTimer <= 0) narratorState.priority = 0;
        }

        if (narratorState.isSpeaking) {
            narratorState.typeTimer += dt;
            if (narratorState.typeTimer >= 0.03) {
                narratorState.typeTimer = 0;
                if (narratorState.charIdx < narratorState.currentText.length) {
                    narratorState.charIdx++;
                    narratorState.displayedText = narratorState.currentText.substring(0, narratorState.charIdx);
                    if (narratorState.charIdx % 2 === 0) playNarratorBeep();
                    if (narratorTextEl) narratorTextEl.innerText = narratorState.displayedText;
                } else {
                    narratorState.isSpeaking = false;
                }
            }
        }

        drawNarratorAvatar(dt);
    }

    function createSparks(x, y, count) {
        count = count || 6;
        for (let i = 0; i < count; i++) {
            sparkParticles.push({
                x: x + (Math.random() - 0.5) * 30,
                y: y + (Math.random() - 0.5) * 10,
                vx: (Math.random() - 0.5) * 160,
                vy: -40 - Math.random() * 80,
                size: 2 + Math.random() * 4,
                life: 1.0,
                color: Math.random() > 0.3 ? '#ffcc00' : '#ffffff'
            });
        }
    }

    function updateSparks(dt) {
        for (let i = sparkParticles.length - 1; i >= 0; i--) {
            let sp = sparkParticles[i];
            sp.x += sp.vx * dt;
            sp.y += sp.vy * dt;
            sp.vy += 300 * dt;
            sp.life -= dt * 3.5;
            if (sp.life <= 0) sparkParticles.splice(i, 1);
        }
    }

    function drawSparks() {
        if (sparkParticles.length === 0) return;
        ctx.save();
        for (let i = 0; i < sparkParticles.length; i++) {
            let sp = sparkParticles[i];
            ctx.fillStyle = sp.color;
            ctx.globalAlpha = Math.max(0, sp.life);
            ctx.fillRect(sp.x, sp.y, sp.size, sp.size);
        }
        ctx.restore();
    }

    function drawSpeedLines() {
        let speedPercent = speed / MAX_SPEED;
        if (speedPercent < 0.82 && !inSlipstream) return;
        
        ctx.save();
        let lineCount = inSlipstream ? 14 : 7;
        ctx.strokeStyle = inSlipstream ? 'rgba(255, 204, 0, 0.45)' : 'rgba(255, 255, 255, 0.25)';
        ctx.lineWidth = 2;
        
        for (let i = 0; i < lineCount; i++) {
            let side = (i % 2 === 0) ? -1 : 1;
            let startX = (WIDTH / 2) + side * (WIDTH * (0.28 + Math.random() * 0.22));
            let startY = HEIGHT * (0.25 + Math.random() * 0.55);
            let endX = startX + side * (40 + Math.random() * 50);
            let endY = startY + (Math.random() - 0.5) * 30;
            
            ctx.beginPath();
            ctx.moveTo(startX, startY);
            ctx.lineTo(endX, endY);
            ctx.stroke();
        }
        ctx.restore();
    }

    function addSegment(curve, y, isRamp) {
        let n = segments.length;
        segments.push({
            index: n,
            p1: { world: { y: lastY(), z:  n   *SEGMENT_LENGTH }, camera: {}, screen: {} },
            p2: { world: { y: y,       z: (n+1)*SEGMENT_LENGTH }, camera: {}, screen: {} },
            curve: curve, sprites: [], cars: [],
            color: Math.floor(n/RUMBLE_LENGTH)%2 ? COLORS.DARK : COLORS.LIGHT,
            isRamp: !!isRamp
        });
    }
    
    function lastY() { return (segments.length == 0) ? 0 : segments[segments.length-1].p2.world.y; }
    
    function addRoad(enter, hold, leave, curve, y, isRamp) {
        let startY = lastY();
        let endY = startY + (Math.floor(y) || 0) * SEGMENT_LENGTH;
        let n, total = enter + hold + leave;
        for(n = 0 ; n < enter ; n++) addSegment(Util.easeIn(0, curve, n/enter), Util.easeInOut(startY, endY, n/total), isRamp);
        for(n = 0 ; n < hold  ; n++) addSegment(curve, Util.easeInOut(startY, endY, (enter+n)/total), isRamp);
        for(n = 0 ; n < leave ; n++) addSegment(Util.easeInOut(curve, 0, n/leave), Util.easeInOut(startY, endY, (enter+hold+n)/total), isRamp);
    }

    function addRamp(upLen, crestLen, downLen, curve, height) {
        curve = curve || 0;
        height = height || 50;
        // Rampa de terra: subida acentuada com elevação 3D e marcação de salto
        addRoad(Math.max(4, Math.floor(upLen * 0.5)), Math.max(4, Math.floor(upLen * 0.5)), 2, curve * 0.4, height, true);
        // Cume do salto e descida íngreme
        addRoad(2, crestLen, downLen, curve, -height * 0.9, true);
    }

    function buildMinimapPath() {
        // Percorre os segmentos e integra curvas para gerar um traçado 2D real da pista
        minimapPoints = [];
        let px = 0, py = 0, angle = -Math.PI / 2; // começa apontando para cima
        let step = 1; // um ponto a cada N segmentos
        let N = Math.max(1, Math.floor(segments.length / 200)); // max 200 pontos

        for (let i = 0; i < segments.length; i += N) {
            // Acumula curvatura dos segmentos no bloco
            let curvSum = 0;
            for (let j = i; j < Math.min(i + N, segments.length); j++) {
                curvSum += segments[j].curve;
            }
            angle += curvSum * 0.018; // fator de escala da curva para ângulo
            px += Math.cos(angle) * N;
            py += Math.sin(angle) * N;
            minimapPoints.push({ x: px, y: py, z: i * SEGMENT_LENGTH });
        }
        // Fecha o circuito adicionando o ponto inicial no final
        minimapPoints.push({ x: minimapPoints[0].x, y: minimapPoints[0].y, z: trackLength });

        // Calcula bounds para normalização
        let minX = Infinity, maxX = -Infinity, minY = Infinity, maxY = -Infinity;
        for (let p of minimapPoints) {
            if (p.x < minX) minX = p.x; if (p.x > maxX) maxX = p.x;
            if (p.y < minY) minY = p.y; if (p.y > maxY) maxY = p.y;
        }
        minimapBounds = { minX, maxX, minY, maxY };
    }

    function resetRoad() {
        segments = [];
        let stg = STAGES[currentStage];
        stg.build(addRoad, addRamp);

        for(let n = 0; n < RUMBLE_LENGTH; n++) {
            segments[n].color = COLORS.START;
            segments[segments.length - RUMBLE_LENGTH + n].color = COLORS.FINISH;
        }

        trackLength = segments.length * SEGMENT_LENGTH;
        buildMinimapPath();
        
        // Garagens, Via Paralela (Pit Lane) com Mureta e Cones na reta principal (segmentos 8 a 46)
        for (let n = 8; n <= 46; n++) {
            segments[n].hasPitLane = true;
            if (n >= 8 && n <= 13) {
                segments[n].isPitEntry = true;
            } else if (n >= 40 && n <= 46) {
                segments[n].isPitExit = true;
            } else {
                segments[n].isPitStraight = true;
            }

            if (n === 8) {
                // Placa luminosa suspensa / pórtico de entrada de Pit Lane
                segments[n].sprites.push({ source: SPRITES.BILLBOARD, offset: 1.65 });
            }
            if (n >= 10 && n <= 14 && n % 2 === 0) {
                // Linha de cones de entrada direcionando à via paralela
                segments[n].sprites.push({ source: SPRITES.TIRE_BARRIER, offset: 1.05 });
            }
            if (n % 6 === 0) {
                segments[n].sprites.push({ source: SPRITES.PIT_GARAGE, offset: 1.85 });
            }
            if (n === 26) {
                segments[n].sprites.push({ source: SPRITES.PIT_CREW, offset: 1.45 });
            }
        }

        const isNascar = currentSeries === 'NASCAR' || (stg && stg.theme && stg.theme.startsWith('NASCAR'));
        const isRally = currentSeries === 'RALLY' || (stg && stg.theme && stg.theme.startsWith('RALLY'));
        const giantGrandstandSprite = SPRITES.NASCAR_GRANDSTAND_GIANT || SPRITES.GRANDSTAND;

        for(let n = 0; n < segments.length; n++) {
            let percentual = n / segments.length;

            if (isNascar) {
                // === CENÁRIO EQUILIBRADO NASCAR (A arquibancada 3D contínua é renderizada geometricamente em 3D) ===
                if ((percentual < 0.14 || percentual > 0.86) && n % 24 === 0) {
                    segments[n].sprites.push({ source: giantGrandstandSprite, offset: 2.3 });
                }

                // Torre de Holofotes de Iluminação (Light Towers) no Infield
                if (SPRITES.NASCAR_LIGHT_TOWER && n % 36 === 12) {
                    segments[n].sprites.push({ source: SPRITES.NASCAR_LIGHT_TOWER, offset: 2.7 });
                }

                // Painel Digital de Posições (Scoring Pylon) na largada
                if (SPRITES.NASCAR_SCORING_PYLON && (n === 6 || n === Math.floor(segments.length / 2))) {
                    segments[n].sprites.push({ source: SPRITES.NASCAR_SCORING_PYLON, offset: 1.65 });
                }

                // Caminhões transportadores das equipes (Haulers) no Infield
                if (SPRITES.NASCAR_HAULER && percentual > 0.15 && percentual < 0.85 && n % 28 === 14) {
                    segments[n].sprites.push({ source: SPRITES.NASCAR_HAULER, offset: 2.1 });
                }

                // Bandeirinha na largada
                if (n === 2) {
                    segments[n].sprites.push({ source: SPRITES.FLAG_MARSHAL, offset: 1.25, isFlagGuy: true });
                }

                // Painéis de patrocinadores NASCAR no Infield
                if (n % 40 === 20) {
                    segments[n].sprites.push({ source: SPRITES.BILLBOARD, offset: 1.85 });
                }
                continue;
            }

            if (isRally) {
                // === CENÁRIO RALLY WRC (FLORESTAS, CERCAS DE TORCIDA, ROCHEDOS E PLACAS DE SALTO) ===
                // Pórtico de Largada / Especial WRC
                if (n === 2 && SPRITES.RALLY_BANNER_ARCH) {
                    segments[n].sprites.push({ source: SPRITES.RALLY_BANNER_ARCH, offset: 0 });
                }
                if (n === 4 && SPRITES.FLAG_MARSHAL) {
                    segments[n].sprites.push({ source: SPRITES.FLAG_MARSHAL, offset: 1.25, isFlagGuy: true });
                }

                // Placa de Alerta de Salto colocada estrategicamente antes de cada rampa de terra
                if (segments[n].isRamp && n > 6 && !segments[n - 6].isRamp && SPRITES.RALLY_JUMP_SIGN) {
                    segments[n - 5].sprites.push({ source: SPRITES.RALLY_JUMP_SIGN, offset: 1.35 });
                    segments[n - 5].sprites.push({ source: SPRITES.RALLY_JUMP_SIGN, offset: -1.35 });
                }

                // Cerca de torcida vibrando e acenando bandeiras nas retas e curvas
                if (SPRITES.RALLY_SPECTATOR_FENCE && (n % 22 === 0)) {
                    let side = (n % 44 === 0) ? 1.55 : -1.55;
                    segments[n].sprites.push({ source: SPRITES.RALLY_SPECTATOR_FENCE, offset: side });
                }

                // Tendas de serviço / checkpoint WRC
                if (SPRITES.RALLY_TENT && n % 48 === 12) {
                    segments[n].sprites.push({ source: SPRITES.RALLY_TENT, offset: 1.7 });
                }

                // Pinheiros densos nos dois lados da pista
                if (SPRITES.RALLY_PINE_TREE && (n % 5 === 0)) {
                    segments[n].sprites.push({ source: SPRITES.RALLY_PINE_TREE, offset: -1.4 - Math.random() * 0.8 });
                    segments[n].sprites.push({ source: SPRITES.RALLY_PINE_TREE, offset: 1.4 + Math.random() * 0.8 });
                }

                // Rochedos e pedregulhos nas tangências de terra
                if (SPRITES.RALLY_ROCK_BOULDER && Math.abs(segments[n].curve) > 3 && (n % 4 === 0)) {
                    let rockSide = segments[n].curve > 0 ? 1.3 : -1.3;
                    segments[n].sprites.push({ source: SPRITES.RALLY_ROCK_BOULDER, offset: rockSide });
                }
                continue;
            }

            // === CENÁRIO FÓRMULA 1 ===
            if (percentual < 0.08 || percentual > 0.92) {
                if (n % 8 === 0) {
                    segments[n].sprites.push({source: SPRITES.GRANDSTAND, offset: -1.8});
                    segments[n].sprites.push({source: SPRITES.GRANDSTAND, offset: 1.8});
                }
                if (n === 2) {
                    segments[n].sprites.push({source: SPRITES.FLAG_MARSHAL, offset: -1.2, isFlagGuy: true});
                }
                continue;
            }

            if (Math.abs(segments[n].curve) > 2 && n % 3 === 0) {
                let outerOffset = segments[n].curve > 0 ? -1.2 : 1.2;
                segments[n].sprites.push({source: SPRITES.TIRE_BARRIER, offset: outerOffset});
            }

            if (stg.theme === 'BEACH') {
                if (n % 4 === 0) {
                    segments[n].sprites.push({source: SPRITES.PALM_TREE, offset: -1.4 - Math.random()*0.3});
                    segments[n].sprites.push({source: SPRITES.PALM_TREE, offset: 1.4 + Math.random()*0.3});
                }
                if (n % 12 === 0) {
                    segments[n].sprites.push({source: SPRITES.TENT, offset: -1.6});
                    segments[n].sprites.push({source: SPRITES.TENT, offset: 1.6});
                }
            } else {
                if (percentual > 0.12 && percentual < 0.35 && n % 5 === 0) {
                    segments[n].sprites.push({source: SPRITES.TREE, offset: -1.4 - Math.random()});
                    segments[n].sprites.push({source: SPRITES.TREE, offset: 1.4 + Math.random()});
                } else if (percentual > 0.40 && percentual < 0.65 && n % 6 === 0) {
                    segments[n].sprites.push({source: SPRITES.PALM_TREE, offset: -1.5});
                    segments[n].sprites.push({source: SPRITES.PALM_TREE, offset: 1.5});
                } else if (percentual > 0.70 && percentual < 0.88 && n % 5 === 0) {
                    segments[n].sprites.push({source: SPRITES.ROCK, offset: -1.3});
                    segments[n].sprites.push({source: SPRITES.ROCK, offset: 1.3});
                }
            }

            if ((segments[n].curve > 2 || segments[n].curve < -2) && n % 18 === 0) {
                let offset = segments[n].curve > 0 ? -1.6 : 1.6;
                segments[n].sprites.push({source: SPRITES.BILLBOARD, offset: offset});
            }
        }
    }

