    const RALLY_DRIVERS = [
        { name: "Colin McRae", team: "Subaru WRC", colorName: "Azul 555", speedFactor: 1.05, accelFactor: 1.07, aggressiveness: 0.95 },
        { name: "Sébastien Loeb", team: "Citroën WRC", colorName: "Vermelha", speedFactor: 1.05, accelFactor: 1.06, aggressiveness: 0.90 },
        { name: "Tommi Mäkinen", team: "Mitsubishi", colorName: "Branca", speedFactor: 1.03, accelFactor: 1.04, aggressiveness: 0.85 },
        { name: "Carlos Sainz", team: "Toyota WRC", colorName: "Amarela", speedFactor: 1.02, accelFactor: 1.03, aggressiveness: 0.80 },
        { name: "Walter Röhrl", team: "Audi Grupo B", colorName: "Dourada", speedFactor: 1.04, accelFactor: 1.08, aggressiveness: 0.92 },
        { name: "Juha Kankkunen", team: "Lancia WRC", colorName: "Verde", speedFactor: 1.01, accelFactor: 1.02, aggressiveness: 0.75 },
        { name: "Petter Solberg", team: "Subaru STi", colorName: "Azul Escuro", speedFactor: 1.02, accelFactor: 1.03, aggressiveness: 0.80 },
        { name: "Marcus Grönholm", team: "Peugeot WRC", colorName: "Prata", speedFactor: 1.02, accelFactor: 1.03, aggressiveness: 0.85 },
        { name: "Richard Burns", team: "Subaru 2001", colorName: "Preta", speedFactor: 1.01, accelFactor: 1.02, aggressiveness: 0.78 }
    ];

    function resetCars() {
        cars = [];
        if (isTrainingMode) {
            lastPlayerPosCheck = 1;
            return;
    
        }

        const aiSprites = [SPRITES.CAR01, SPRITES.CAR02, SPRITES.CAR03, SPRITES.CAR04, SPRITES.CAR05, SPRITES.CAR06];
        const driversList = currentSeries === 'NASCAR' ? NASCAR_DRIVERS : (currentSeries === 'RALLY' ? RALLY_DRIVERS : AI_DRIVERS);

        for(let i=0; i<9; i++) {
            let driverInfo = driversList[i % driversList.length];
            let car = { 
                driverName: driverInfo.name,
                teamName: driverInfo.team,
                colorName: driverInfo.colorName,
                speedFactor: driverInfo.speedFactor,
                accelFactor: driverInfo.accelFactor,
                aggressiveness: driverInfo.aggressiveness,
                offset: (i % 2 === 0) ? 0.35 : -0.35, 
                z: trackLength - ((i + 1) * 800), 
                sprite: aiSprites[i % aiSprites.length], 
                speed: 0, 
                maxSpeed: MAX_SPEED * driverInfo.speedFactor,
                lapsCompleted: 0,
                finished: false,
                isDrifting: false
            };
            findSegment(car.z).cars.push(car);
            cars.push(car);
        }
        lastPlayerPosCheck = 10;
    }

    function initAudio() {
        if (isAudioInitialized) {
            if (audioCtx && audioCtx.state === 'suspended') audioCtx.resume();
            return;
        }
        const AudioContextClass = window.AudioContext || window.webkitAudioContext;
        if (!AudioContextClass) return;
        try {
            audioCtx = new AudioContextClass();

            // Master com compressor e limiter suave para evitar clipping.
            const master = audioCtx.createGain();
            master.gain.value = 0.82;
            const compressor = audioCtx.createDynamicsCompressor();
            compressor.threshold.value = -24;
            compressor.knee.value = 18;
            compressor.ratio.value = 4;
            compressor.attack.value = 0.006;
            compressor.release.value = 0.18;
            const limiter = audioCtx.createDynamicsCompressor();
            limiter.threshold.value = -8;
            limiter.knee.value = 3;
            limiter.ratio.value = 12;
            limiter.attack.value = 0.002;
            limiter.release.value = 0.12;
            compressor.connect(limiter);
            limiter.connect(master);
            master.connect(audioCtx.destination);

            filter = audioCtx.createBiquadFilter();
            filter.type = 'lowpass';
            filter.frequency.value = 1500;
            filter.Q.value = 0.8;
            engineGain = audioCtx.createGain();
            engineGain.gain.value = 0;
            engineOsc1 = audioCtx.createOscillator();
            engineOsc2 = audioCtx.createOscillator();
            engineOsc3 = audioCtx.createOscillator();
            engineOsc4 = audioCtx.createOscillator();
            engineOsc1.type = 'sawtooth';
            engineOsc2.type = 'triangle';
            engineOsc3.type = 'sawtooth';
            engineOsc4.type = 'sine';

            const layers = [0.24, 0.27, 0.075, 0.055].map(v => {
                const g = audioCtx.createGain(); g.gain.value = v; return g;
            });
            [engineOsc1, engineOsc2, engineOsc3, engineOsc4].forEach((o, i) => {
                o.connect(layers[i]); layers[i].connect(filter);
            });
            filter.connect(engineGain);
            engineGain.connect(compressor);

            // Derrapagem: ruído filtrado em canal separado para continuar audível.
            const bufferLength = Math.max(1, Math.floor(audioCtx.sampleRate * 1.5));
            const noiseBuffer = audioCtx.createBuffer(1, bufferLength, audioCtx.sampleRate);
            const noiseData = noiseBuffer.getChannelData(0);
            for (let i = 0; i < bufferLength; i++) noiseData[i] = Math.random() * 2 - 1;
            noiseSrc = audioCtx.createBufferSource();
            noiseSrc.buffer = noiseBuffer; noiseSrc.loop = true;
            const skidFilter = audioCtx.createBiquadFilter();
            skidFilter.type = 'bandpass'; skidFilter.frequency.value = 1450; skidFilter.Q.value = 0.75;
            skidGain = audioCtx.createGain(); skidGain.gain.value = 0;
            noiseSrc.connect(skidFilter); skidFilter.connect(skidGain); skidGain.connect(compressor);

            // Três vozes para rivais: motor, panorama estéreo e atenuação por distância.
            opponentAudioVoices = [];
            for (let i = 0; i < 3; i++) {
                const osc = audioCtx.createOscillator();
                const harmonic = audioCtx.createOscillator();
                const lowpass = audioCtx.createBiquadFilter();
                const gain = audioCtx.createGain();
                const panner = audioCtx.createStereoPanner();
                osc.type = 'sawtooth'; harmonic.type = 'triangle'; lowpass.type = 'lowpass';
                gain.gain.value = 0; lowpass.frequency.value = 1100;
                osc.connect(lowpass); harmonic.connect(lowpass);
                lowpass.connect(gain); gain.connect(panner); panner.connect(compressor);
                osc.start(); harmonic.start();
                opponentAudioVoices.push({osc, harmonic, lowpass, gain, panner, previousDistance:null});
            }

            const now = audioCtx.currentTime;
            [78, 39, 156, 234].forEach((f, i) => {
                [engineOsc1, engineOsc2, engineOsc3, engineOsc4][i].frequency.setValueAtTime(f, now);
                [engineOsc1, engineOsc2, engineOsc3, engineOsc4][i].start();
            });
            noiseSrc.start();
            isAudioInitialized = true;
        } catch (error) {
            console.warn('Não foi possível inicializar o áudio:', error);
            isAudioInitialized = false;
        }
    }

    let opponentAudioVoices = [];
    let lastAudioGear = 1;
    let lastAudioRpm = 0;
    let limiterPulse = 0;
    let lastBackfireAt = 0;

    function playEngineTransient(kind, strength = 1) {
        if (!isAudioInitialized || !audioCtx) return;
        const now = audioCtx.currentTime;
        try {
            const osc = audioCtx.createOscillator();
            const osc2 = audioCtx.createOscillator();
            const gain = audioCtx.createGain();
            const filterFx = audioCtx.createBiquadFilter();
            const duration = kind === 'shift' ? 0.105 : (kind === 'blowoff' ? 0.19 : 0.14);
            filterFx.type = 'lowpass';
            filterFx.frequency.setValueAtTime(kind === 'backfire' ? 2100 : 3200, now);
            filterFx.frequency.exponentialRampToValueAtTime(280, now + duration);
            osc.type = kind === 'backfire' ? 'square' : 'sawtooth';
            osc2.type = 'triangle';
            const base = kind === 'backfire' ? 115 : (kind === 'blowoff' ? 720 : 190);
            osc.frequency.setValueAtTime(base * (0.85 + Math.random() * 0.3), now);
            osc.frequency.exponentialRampToValueAtTime(kind === 'blowoff' ? 180 : 55, now + duration);
            osc2.frequency.setValueAtTime(base * 1.7, now);
            osc2.frequency.exponentialRampToValueAtTime(75, now + duration);
            gain.gain.setValueAtTime(0.0001, now);
            gain.gain.linearRampToValueAtTime(Math.min(0.13, 0.075 * strength), now + 0.012);
            gain.gain.exponentialRampToValueAtTime(0.0001, now + duration);
            osc.connect(filterFx); osc2.connect(filterFx); filterFx.connect(gain); gain.connect(audioCtx.destination);
            osc.start(now); osc2.start(now);
            osc.stop(now + duration + 0.02); osc2.stop(now + duration + 0.02);
        } catch (e) {}
    }

    function updateOpponentAudio(now) {
        if (!opponentAudioVoices.length || !Array.isArray(cars)) return;
        const nearby = [];
        for (const car of cars) {
            if (!car || car.isDummy || car.finished) continue;
            let dz = Math.abs((car.z || 0) - (position + PLAYER_Z));
            if (trackLength > 0) dz = Math.min(dz, Math.abs(dz - trackLength), Math.abs(dz + trackLength));
            if (dz < 1250) nearby.push({car, dz});
        }
        nearby.sort((a,b) => a.dz - b.dz);
        opponentAudioVoices.forEach((voice, i) => {
            const item = nearby[i];
            if (!item) {
                voice.gain.gain.setTargetAtTime(0, now, 0.16);
                voice.previousDistance = null;
                return;
            }
            const {car, dz} = item;
            const proximity = Math.max(0, 1 - dz / 1250);
            const speedRatio = Math.max(0.12, Math.min(1.25, (car.speed || 0) / Math.max(1, MAX_SPEED)));
            const approaching = voice.previousDistance !== null && dz < voice.previousDistance - 0.8;
            const receding = voice.previousDistance !== null && dz > voice.previousDistance + 0.8;
            const doppler = approaching ? 1.055 : (receding ? 0.955 : 1);
            const base = (currentSeries === 'NASCAR' ? 62 : currentSeries === 'RALLY' ? 88 : 112);
            const hz = (base + speedRatio * (currentSeries === 'NASCAR' ? 100 : 245)) * doppler;
            voice.osc.frequency.setTargetAtTime(hz, now, 0.09);
            voice.harmonic.frequency.setTargetAtTime(hz * (currentSeries === 'NASCAR' ? 1.48 : 2.02), now, 0.09);
            voice.lowpass.frequency.setTargetAtTime(650 + proximity * 3000, now, 0.12);
            voice.panner.pan.setTargetAtTime(Math.max(-1, Math.min(1, ((car.offset || 0) - playerX) * 1.25)), now, 0.1);
            voice.gain.gain.setTargetAtTime(proximity * (0.018 + speedRatio * 0.026), now, 0.14);
            voice.previousDistance = dz;
        });
    }

    function playPneumaticWrenchSound() {
        if (!isAudioInitialized || !audioCtx) return;
        try {
            for (let i = 0; i < 6; i++) {
                setTimeout(() => {
                    let osc = audioCtx.createOscillator();
                    let g = audioCtx.createGain();
                    osc.type = 'sawtooth';
                    osc.frequency.setValueAtTime(800 + Math.random() * 600, audioCtx.currentTime);
                    osc.frequency.exponentialRampToValueAtTime(120, audioCtx.currentTime + 0.06);
                    g.gain.setValueAtTime(0.25, audioCtx.currentTime);
                    g.gain.exponentialRampToValueAtTime(0.01, audioCtx.currentTime + 0.06);
                    osc.connect(g); g.connect(audioCtx.destination);
                    osc.start(); osc.stop(audioCtx.currentTime + 0.06);
                }, i * 70);
            }
        } catch(e){}
    }

    function playJumpSound() {
        if (!isAudioInitialized || !audioCtx) return;
        try {
            let osc = audioCtx.createOscillator();
            let g = audioCtx.createGain();
            osc.type = 'sine';
            osc.frequency.setValueAtTime(190, audioCtx.currentTime);
            osc.frequency.exponentialRampToValueAtTime(480, audioCtx.currentTime + 0.18);
            g.gain.setValueAtTime(0.20, audioCtx.currentTime);
            g.gain.exponentialRampToValueAtTime(0.01, audioCtx.currentTime + 0.22);
            osc.connect(g); g.connect(audioCtx.destination);
            osc.start(); osc.stop(audioCtx.currentTime + 0.22);
        } catch(e){}
    }

    function playPitBurnoutSound() {
        if (!isAudioInitialized || !audioCtx) return;
        try {
            if (audioCtx.state === 'suspended') audioCtx.resume();
            let now = audioCtx.currentTime;
            // Ru\xc3\xaddo / guincho estridente de pneus girando em falso no asfalto
            let bufferSize = Math.floor(audioCtx.sampleRate * 0.45);
            let noiseBuffer = audioCtx.createBuffer(1, bufferSize, audioCtx.sampleRate);
            let output = noiseBuffer.getChannelData(0);
            for (let i = 0; i < bufferSize; i++) {
                output[i] = (Math.random() * 2 - 1) * 0.7;
            }
            let whiteNoise = audioCtx.createBufferSource();
            whiteNoise.buffer = noiseBuffer;
            let filter = audioCtx.createBiquadFilter();
            filter.type = 'bandpass';
            filter.frequency.setValueAtTime(1400, now);
            filter.frequency.exponentialRampToValueAtTime(2600, now + 0.25);
            filter.Q.setValueAtTime(4.0, now);
            let g = audioCtx.createGain();
            g.gain.setValueAtTime(0.35, now);
            g.gain.exponentialRampToValueAtTime(0.01, now + 0.42);
            whiteNoise.connect(filter);
            filter.connect(g);
            g.connect(audioCtx.destination);
            whiteNoise.start(now);
            whiteNoise.stop(now + 0.45);
        } catch(e){}
    }

    function playLandingSound() {
        if (!isAudioInitialized || !audioCtx) return;
        try {
            let osc = audioCtx.createOscillator();
            let g = audioCtx.createGain();
            osc.type = 'triangle';
            osc.frequency.setValueAtTime(140, audioCtx.currentTime);
            osc.frequency.exponentialRampToValueAtTime(32, audioCtx.currentTime + 0.16);
            g.gain.setValueAtTime(0.38, audioCtx.currentTime);
            g.gain.exponentialRampToValueAtTime(0.01, audioCtx.currentTime + 0.22);
            osc.connect(g); g.connect(audioCtx.destination);
            osc.start(); osc.stop(audioCtx.currentTime + 0.22);
        } catch(e){}
    }

    function updateAudio() {
        if (!isAudioInitialized || !audioCtx || !engineGain) return;
        if (audioCtx.state === 'suspended') audioCtx.resume();
        const now = audioCtx.currentTime;
        if (state !== 'RACING' && state !== 'CUTSCENE' && state !== 'FINISHED' && state !== 'PIT_STOP') {
            engineGain.gain.setTargetAtTime(0, now, 0.12);
            if (skidGain) skidGain.gain.setTargetAtTime(0, now, 0.08);
            updateOpponentAudio(now);
            return;
        }
        if (state === 'PIT_STOP') {
            engineOsc1.frequency.setTargetAtTime(68, now, 0.22);
            engineOsc2.frequency.setTargetAtTime(34, now, 0.22);
            engineOsc3.frequency.setTargetAtTime(136, now, 0.22);
            engineOsc4.frequency.setTargetAtTime(204, now, 0.22);
            filter.frequency.setTargetAtTime(900, now, 0.2);
            engineGain.gain.setTargetAtTime(0.075 * gameVolume, now, 0.18);
            if (skidGain) skidGain.gain.setTargetAtTime(0, now, 0.1);
            updateOpponentAudio(now);
            return;
        }

        const normalizedSpeed = Math.max(0, Math.min(1, speed / Math.max(1, MAX_SPEED)));
        const displaySpeed = normalizedSpeed * 320;
        let gear = 1;
        if (displaySpeed > 280) gear = 7;
        else if (displaySpeed > 230) gear = 6;
        else if (displaySpeed > 180) gear = 5;
        else if (displaySpeed > 130) gear = 4;
        else if (displaySpeed > 80) gear = 3;
        else if (displaySpeed > 30) gear = 2;

        const previousGear = currentGear;
        const gearChanged = gear !== currentGear;
        if (gearChanged) currentGear = gear;
        const gearRanges = [[0,50],[30,80],[80,130],[130,180],[180,230],[230,280],[280,320]];
        const range = gearRanges[gear - 1];
        const rpmInGear = Math.max(0, Math.min(1, (displaySpeed - range[0]) / Math.max(1, range[1] - range[0])));
        const throttle = (state === 'RACING' && keyFaster) ? 1 : 0;
        const isNASCAR = currentSeries === 'NASCAR';
        const isRally = currentSeries === 'RALLY';
        const idle = isNASCAR ? 0.20 : (isRally ? 0.16 : 0.13);
        const rpm = Math.min(1.22, idle + rpmInGear * 0.82 + throttle * (0.12 + rpmInGear * 0.16));
        const atLimiter = state === 'RACING' && throttle > 0 && rpmInGear > 0.965;
        const rpmWave = atLimiter ? (Math.sin(now * 62) > 0.12 ? 0.72 : 0.18) : 1;
        const pitchBase = isNASCAR ? 48 : (isRally ? 82 : 118);
        const pitchRange = isNASCAR ? 175 : (isRally ? 285 : 430);
        const fundamental = pitchBase + rpm * pitchRange;
        const shiftTime = gearChanged ? 0.035 : 0.075;

        // Timbre muda de verdade por categoria: V8 grave, turbo metálico ou F1 agudo.
        engineOsc1.type = isNASCAR ? 'sawtooth' : 'sawtooth';
        engineOsc2.type = isNASCAR ? 'square' : (isRally ? 'square' : 'triangle');
        engineOsc3.type = isRally ? 'square' : 'sawtooth';
        engineOsc4.type = 'sine';
        const ratio2 = isNASCAR ? 1.48 : (isRally ? 2.35 : 2.02);
        engineOsc1.frequency.setTargetAtTime(fundamental * rpmWave, now, shiftTime);
        engineOsc2.frequency.setTargetAtTime(fundamental * 0.5 * rpmWave, now, shiftTime);
        engineOsc3.frequency.setTargetAtTime(fundamental * ratio2 * rpmWave, now, shiftTime);
        engineOsc4.frequency.setTargetAtTime(fundamental * (isNASCAR ? 2.96 : 3.04) * rpmWave, now, shiftTime);

        const cutoffBase = isNASCAR ? 780 : (isRally ? 1350 : 2100);
        const cutoffRange = isNASCAR ? 2400 : (isRally ? 3600 : 5200);
        filter.frequency.setTargetAtTime(cutoffBase + rpm * cutoffRange + throttle * 450, now, 0.075);
        filter.Q.setTargetAtTime(isRally ? 1.15 : (isNASCAR ? 0.82 : 0.95), now, 0.1);

        let volume = (isNASCAR ? 0.105 : 0.09) + rpm * 0.035 + throttle * 0.018;
        if (state === 'CUTSCENE') volume = 0.075;
        if (state === 'FINISHED') volume *= 0.68;
        volume *= rpmWave;
        engineGain.gain.setTargetAtTime(Math.min(0.19, volume) * gameVolume, now, 0.075);

        if (gearChanged && state === 'RACING') {
            // Corte curto no upshift; redução tem estalo específico no Rally.
            engineGain.gain.cancelScheduledValues(now);
            engineGain.gain.setTargetAtTime(volume * gameVolume * 0.30, now, 0.012);
            engineGain.gain.setTargetAtTime(Math.min(0.19, volume) * gameVolume, now + 0.055, 0.065);
            playEngineTransient('shift', isNASCAR ? 0.8 : 1);
            if (gear < previousGear) {
                if (isRally) {
                    playEngineTransient('backfire', 1.15);
                    playEngineTransient('blowoff', 0.85);
                } else if (!isNASCAR) playEngineTransient('backfire', 0.55);
            } else if (isRally) {
                playEngineTransient('blowoff', 0.75);
            }
        }

        // Pipocos espaçados no limitador, sem criar um disparo a cada frame.
        if (atLimiter && now - lastBackfireAt > 0.19) {
            lastBackfireAt = now;
            playEngineTransient(isRally ? 'backfire' : 'shift', isNASCAR ? 0.7 : 0.85);
        }
        lastAudioGear = gear;
        lastAudioRpm = rpm;

        const isOffRoad = playerX < -1 || playerX > 1;
        if (state === 'RACING' && speed > 50 && (isDrifting || isOffRoad)) {
            skidGain.gain.setTargetAtTime(isOffRoad ? 0.105 : 0.065, now, 0.08);
        } else {
            skidGain.gain.setTargetAtTime(0, now, 0.12);
        }
        updateOpponentAudio(now);
    }

        function releaseCarFromPit() {
        if (state !== 'PIT_STOP' || !pitServiceComplete) return;

        state = 'RACING';
        isPitStopActive = false;
        pitServiceComplete = false;
        hasCompletedPitStop = true;
        pitStopCount++;
        pitCrewProgress = 0;
        
        // Aplica impulso/força inicial de aceleração imediata garantida
        speed = Math.max(speed, PIT_LIMITER_SPEED * 0.95);

        // Oculta prompts e overlays do Pit Stop
        let pReadyEl = document.getElementById('pit-ready-prompt');
        if (pReadyEl) pReadyEl.classList.add('hidden');
        let pOverlayEl = document.getElementById('pit-stop-overlay');
        if (pOverlayEl) pOverlayEl.classList.add('hidden');

        // Ativa animação de arrancada (burnout / fumaça e marcas de saída)
        pitLaunchAnimation = 1.6;
        playPitBurnoutSound();
        triggerNarratorEvent('PIT_DONE', null, 4);

        // Gera nuvens intensas de fumaça de borracha nos pneus traseiros (arrancada)
        let playerScreenX = WIDTH / 2 + (slideX * WIDTH * 1.5);
        let playerScreenY = HEIGHT - 15;
        for (let k = 0; k < 40; k++) {
            let angle = Math.random() * Math.PI * 2;
            let pSpeed = 45 + Math.random() * 95;
            tireSmokeParticles.push({
                x: playerScreenX + (Math.random() - 0.5) * 55,
                y: playerScreenY - 5,
                life: 1.1 + Math.random() * 0.5,
                vx: Math.cos(angle) * pSpeed,
                vy: -35 - Math.random() * 50,
                size: 9 + Math.random() * 18,
                colorBase: 'rgba(235, 235, 235, ',
                isOffRoad: false
            });
        }
        createSparks(playerScreenX, playerScreenY - 10, 14);
    }

    function showNitroPopup() {
        const popup = document.getElementById('nitro-popup');
        if (!popup) return;
        popup.classList.remove('show'); void popup.offsetWidth;
        popup.textContent = 'PERFECT CORNER! +NITRO'; popup.classList.add('show');
        nitroPopupTimer = 1.35;
    }
    function playNitroCornerSound() {
        if (!isAudioInitialized || !audioCtx) return;
        try {
            const now = audioCtx.currentTime, osc = audioCtx.createOscillator(), gain = audioCtx.createGain();
            osc.type = 'sine'; osc.frequency.setValueAtTime(620, now); osc.frequency.exponentialRampToValueAtTime(1120, now + .12);
            gain.gain.setValueAtTime(.0001, now); gain.gain.linearRampToValueAtTime(.12, now + .025); gain.gain.exponentialRampToValueAtTime(.0001, now + .18);
            osc.connect(gain); gain.connect(audioCtx.destination); osc.start(now); osc.stop(now + .19);
        } catch (err) {}
    }
    function activateNitro() {
        if (state !== 'RACING' || nitroCharge <= 0 || inPitLane || playerAirborne || keySlower) return;
        nitroActiveTime = 0.18;
        const container = document.getElementById('game-container');
        if (container) container.classList.add('nitro-active');
    }
    function updateNitroEffects(dt) {
        const container = document.getElementById('game-container');
        if (container) container.classList.toggle('nitro-active', nitroActiveTime > 0);
        if (!ctx || nitroActiveTime <= 0) return;
        ctx.save();
        for (let i = 0; i < 5; i++) {
            const x = WIDTH * .5 + (Math.random() - .5) * 38;
            const y = HEIGHT - 20 + Math.random() * 8;
            ctx.globalAlpha = .45 + Math.random() * .45; ctx.fillStyle = '#38bdf8';
            ctx.shadowColor = '#0ea5e9'; ctx.shadowBlur = 12;
            ctx.beginPath(); ctx.ellipse(x, y, 3 + Math.random() * 4, 7 + Math.random() * 7, 0, 0, Math.PI * 2); ctx.fill();
        }
        ctx.restore();
    }

    function update(dt) {
        if (state === 'CUTSCENE') {
            updateCutscene(dt);
            updateAudio();
            updateNarratorSystem(dt); return;
    
        }

        // LÓGICA DA ANIMAÇÃO E SEQUÊNCIA DO PIT STOP
        if (state === 'PIT_STOP') {
            pitTimer += dt;
            // Desacelera\xc3\xa7\xc3\xa3o suave e autom\xc3\xa1tica at\xc3\xa9 a parada completa no pit box
            if (speed > 0) {
                speed = Math.max(0, speed - (MAX_SPEED * 1.8 * dt));
            }
            playerX += (1.28 - playerX) * dt * 4.0; // Alinha com precis\xc3\xa3o milim\xc3\xa9trica na ba\xc3\xada

            // Efeito sonoro das parafusadeiras pneum\xc3\xa1ticas
            if (pitTimer > 0.4 && pitTimer < 0.6 && pitCrewProgress === 0) {
                pitCrewProgress = 1;
                playPneumaticWrenchSound();
                triggerNarratorEvent('PIT_STOP', null, 4);
            }
            if (pitTimer > 1.4 && pitTimer < 1.6 && pitCrewProgress === 1) {
                pitCrewProgress = 2;
                playPneumaticWrenchSound();
            }

            // Atualiza\xc3\xa7\xc3\xa3o dos indicadores do HUD Overlay retro
            let pOverlayEl = document.getElementById('pit-stop-overlay');
            let pReadyEl = document.getElementById('pit-ready-prompt');
            let pStatusText = document.getElementById('pit-service-status-text');
            let pBar = document.getElementById('pit-progress-bar');
            let hudFrontTires = document.getElementById('pit-hud-front-tires');
            let hudRearTires = document.getElementById('pit-hud-rear-tires');
            let hudFuel = document.getElementById('pit-hud-fuel');
            let hudWing = document.getElementById('pit-hud-wing');

            if (pOverlayEl) pOverlayEl.classList.remove('hidden');

            // Progresso do servi\xc3\xa7o (0 a 100% em ~2.6 segundos)
            let pProgress = Math.min(100, Math.round((pitTimer / 2.6) * 100));
            if (pBar) pBar.style.width = pProgress + '%';

            if (pProgress < 35) {
                if (pStatusText) pStatusText.innerText = 'ERGUENDO CARRO & SOLTANDO PORCAS...';
                if (hudFrontTires) { hudFrontTires.style.color = '#ffaa00'; hudFrontTires.innerText = '\xf0\x9f\x94\xb4 Pneus Dianteiros: REMOVENDO...'; }
                if (hudRearTires) { hudRearTires.style.color = '#ffaa00'; hudRearTires.innerText = '\xf0\x9f\x94\xb4 Pneus Traseiros: REMOVENDO...'; }
                if (hudFuel) { hudFuel.style.color = '#00ffff'; hudFuel.innerText = '\xe2\x9a\xbd Combust\xc3\xadvel: REABASTECENDO (' + Math.round(pProgress * 1.8) + '%)'; }
                if (hudWing) { hudWing.style.color = '#888888'; hudWing.innerText = '\xf0\x9f\x94\xa7 Asa & Ajustes: AGUARDANDO'; }
            } else if (pProgress < 75) {
                if (pStatusText) pStatusText.innerText = 'ENCAIXANDO NOVOS PNEUS SLICK MACIOS...';
                if (hudFrontTires) { hudFrontTires.style.color = '#00ff66'; hudFrontTires.innerText = '\xe2\x9c\x85 Pneus Dianteiros: OK (100%)'; }
                if (hudRearTires) { hudRearTires.style.color = '#ffaa00'; hudRearTires.innerText = '\xf0\x9f\x94\xb4 Pneus Traseiros: APERTANDO...'; }
                if (hudFuel) { hudFuel.style.color = '#00ffff'; hudFuel.innerText = '\xe2\x9a\xbd Combust\xc3\xadvel: REABASTECENDO (' + Math.round(pProgress * 1.25) + '%)'; }
                if (hudWing) { hudWing.style.color = '#00ffff'; hudWing.innerText = '\xf0\x9f\x94\xa7 Asa & Ajustes: AJUSTANDO DOWNFORCE...'; }
            } else if (pProgress < 100) {
                if (pStatusText) pStatusText.innerText = 'FINALIZANDO REPAROS & PRESS\xc3\x83O...';
                if (hudFrontTires) { hudFrontTires.style.color = '#00ff66'; hudFrontTires.innerText = '\xe2\x9c\x85 Pneus Dianteiros: OK (100%)'; }
                if (hudRearTires) { hudRearTires.style.color = '#00ff66'; hudRearTires.innerText = '\xe2\x9c\x85 Pneus Traseiros: OK (100%)'; }
                if (hudFuel) { hudFuel.style.color = '#00ff66'; hudFuel.innerText = '\xe2\x9c\x85 Combust\xc3\xadvel: 100% OK'; }
                if (hudWing) { hudWing.style.color = '#00ff66'; hudWing.innerText = '\xe2\x9c\x85 Asa & Ajustes: OK'; }
            } else {
                // Servi\xc3\xa7o conclu\xc3\xaddo (100%)
                tireHealth = 100;
                pitServiceComplete = true;
                if (pStatusText) {
                    pStatusText.innerText = '\xe2\x9c\x94 SERVI\xc3\x87O CONCLU\xc3\x8dDO COM SUCESSO!';
                    pStatusText.style.color = '#00ff66';
                }
                if (hudFrontTires) { hudFrontTires.style.color = '#00ff66'; hudFrontTires.innerText = '\xe2\x9c\x85 Pneus Dianteiros: OK (100%)'; }
                if (hudRearTires) { hudRearTires.style.color = '#00ff66'; hudRearTires.innerText = '\xe2\x9c\x85 Pneus Traseiros: OK (100%)'; }
                if (hudFuel) { hudFuel.style.color = '#00ff66'; hudFuel.innerText = '\xe2\x9c\x85 Combust\xc3\xadvel: 100% OK'; }
                if (hudWing) { hudWing.style.color = '#00ff66'; hudWing.innerText = '\xe2\x9c\x85 Asa & Ajustes: OK'; }
                if (pReadyEl) pReadyEl.classList.remove('hidden');
            }

            updateAudio();
            updateNarratorSystem(dt);
            updateHUD();
            return;
        }

        if(state !== 'RACING') {
             if (state === 'MENU' || state === 'SHOWCASE') {
                 position = Util.increase(position, dt * 1200, trackLength);
             } else if(state === 'FINISHED') {
                 speed = Util.accelerate(speed, DECEL, dt);
                 position = Util.increase(position, dt * speed, trackLength);
             }
             updateVictoryCelebration(dt);
            updateAudio();
             updateNarratorSystem(dt); return;
      
        }

        lapTime += dt;
        totalRaceTime += dt;
        if (shakeTimer > 0) shakeTimer -= dt * 10;

        // CÁLCULO DE DESGASTE DOS PNEUS
        let wearRate = (speed / MAX_SPEED) * (isDrifting ? 3.5 : 0.4) + (playerX < -1 || playerX > 1 ? 4.0 : 0);
        tireHealth = Math.max(0, tireHealth - dt * wearRate * 0.35);

        let pitWarnEl = document.getElementById('pit-warning');
        if (pitWarnEl) {
            if (tireHealth < 35) pitWarnEl.classList.remove('hidden');
            else pitWarnEl.classList.add('hidden');
        }

        let playerSegment = findSegment(position+PLAYER_Z);
        let segIdx = playerSegment.index;
        let stg = STAGES[currentStage];
        let isRallyMode = currentSeries === 'RALLY' || (stg && stg.theme && stg.theme.startsWith('RALLY'));

        // FÍSICA DE RAMPA DE TERRA E SALTO AÉREO (RALLY JUMP & AIRBORNE)
        if (playerSegment.isRamp && speed > MAX_SPEED * 0.28 && !playerAirborne) {
            playerAirborne = true;
            playerJumpVel = Math.min(680, (speed / MAX_SPEED) * 560 + 160);
            playJumpSound();
            triggerNarratorEvent('RALLY_JUMP', null, 4);
        }

        if (playerAirborne) {
            playerJumpY += playerJumpVel * dt;
            playerJumpVel -= 1200 * dt; // Gravidade atuando no salto
            if (playerJumpY <= 0) {
                playerJumpY = 0;
                playerAirborne = false;
                shakeTimer = 0.45; // Tremor de impacto de aterrissagem
                playLandingSound();
                triggerNarratorEvent('RALLY_LAND', null, 4);
                // Explosão de poeira e terra de aterrissagem
                let landX = (WIDTH / 2) + slideX * WIDTH * 0.8;
                for (let k = 0; k < 22; k++) {
                    let angle = Math.random() * Math.PI * 2;
                    let pSpeed = 40 + Math.random() * 90;
                    let pColor = weather === 'RAIN' ? 'rgba(70, 48, 30, ' : (weather === 'SUNSET' ? 'rgba(180, 105, 45, ' : 'rgba(150, 95, 45, ');
                    tireSmokeParticles.push({
                        x: landX + (Math.random() - 0.5) * 40,
                        y: HEIGHT - 10,
                        life: 1.0,
                        vx: Math.cos(angle) * pSpeed,
                        vy: -20 - Math.random() * 35,
                        size: 7 + Math.random() * 12,
                        colorBase: pColor,
                        isOffRoad: false
                    });
                }
            }
        }

        // Exibe prompt de entrada do Box quando estiver se aproximando da ramificação dos boxes
        let pitPromptEl = document.getElementById('pit-entry-prompt');
        let nearPitEntry = (segIdx >= 6 && segIdx <= 16);
        let inPitZone = (segIdx >= 8 && segIdx <= 46);
        if (pitPromptEl) {
            if (nearPitEntry && !inPitLane && !isPitStopActive && !isRallyMode) pitPromptEl.classList.remove('hidden');
            else pitPromptEl.classList.add('hidden');
        }
        
        let pitLimiterBadge = document.getElementById('pit-limiter-badge');

        // 1. MECÂNICA DE ENTRADA NA VIA PARALELA (PIT LANE):
        // Desvio à direita na reta principal ou acionamento do botão/tecla PIT
        if (nearPitEntry && (playerX > 0.45 || keyPitRequested) && !inPitLane && !hasCompletedPitStop && !isRallyMode) {
            inPitLane = true;
            keyPitRequested = false;
            if (pitPromptEl) pitPromptEl.classList.add('hidden');
            triggerNarratorEvent('PIT_ENTRY', null, 4);
        }

        // 2. CONDUÇÃO NO PIT LANE: PIT LIMITER AUTOMÁTICO E CONDUÇÃO AO PIT BOX
        if (inPitLane && !isRallyMode) {
            if (pitLimiterBadge) pitLimiterBadge.classList.remove('hidden');

            // Condução assistida no Pit Lane
            if (!hasCompletedPitStop) {
                // Entrada no pit box: alinha o carro suavemente pelo centro da via paralela (offset 1.25)
                playerX += (1.25 - playerX) * dt * 4.5;

                // Pit Limiter na entrada: limita velocidade a 80 km/h
                if (speed > PIT_LIMITER_SPEED) {
                    speed = Math.max(PIT_LIMITER_SPEED, speed - (MAX_SPEED * 2.2 * dt));
                }

                // Ao se aproximar da baía dos mecânicos (segIdx 24 a 28), para o carro para manutenção
                if (segIdx >= 24 && segIdx <= 28 && !isPitStopActive) {
                    isPitStopActive = true;
                    state = 'PIT_STOP';
                    pitTimer = 0;
                    pitCrewProgress = 0;
                }
            } else {
                // Saída do pit box após liberação: acelera automaticamente e direciona suavemente de volta à pista
                if (speed < PIT_LIMITER_SPEED) {
                    speed = Math.min(PIT_LIMITER_SPEED, speed + ACCEL * 1.5 * dt);
                } else if (speed > PIT_LIMITER_SPEED) {
                    speed = Math.max(PIT_LIMITER_SPEED, speed - (MAX_SPEED * 1.5 * dt));
                }

                // Transição gradual para a pista ao avançar para a saída
                if (segIdx >= 38) {
                    playerX += (0.55 - playerX) * dt * 3.5;
                } else {
                    playerX += (1.20 - playerX) * dt * 4.0;
                }
            }

            // Fim do Pit Lane (segIdx > 44): desativa limiter e restaura controle total de corrida
            if (segIdx > 44) {
                inPitLane = false;
                pitLaunchAnimation = 0;
                if (pitLimiterBadge) pitLimiterBadge.classList.add('hidden');
                playerX = 0.50; // Retorna à pista principal com segurança e liberdade
            }
        } else {
            if (pitLimiterBadge) pitLimiterBadge.classList.add('hidden');
        }
        let currentMaxSpeed = MAX_SPEED * (nitroActiveTime > 0 ? 1.16 : 1);
        if (inSlipstream) currentMaxSpeed = Math.max(currentMaxSpeed, MAX_SPEED * 1.18);
        let speedPercent  = speed/MAX_SPEED; 
        let dx            = dt * (isRallyMode ? 2.5 : 2.2) * speedPercent; 
        let targetSlide   = 0;
        isDrifting        = false;

        if (keyLeft) { 
            playerX = playerX - dx; 
            targetSlide = (isRallyMode ? -0.045 : -0.025) * speedPercent; 
        } 
        else if (keyRight) { 
            playerX = playerX + dx; 
            targetSlide = (isRallyMode ? 0.045 : 0.025) * speedPercent; 
        }
        
        let curveForce = playerSegment.curve * (weather === 'RAIN' ? CENTRIFUGAL * 1.4 : (isRallyMode ? CENTRIFUGAL * 1.35 : CENTRIFUGAL)) * speedPercent;
        
        if (isRallyMode && Math.abs(playerSegment.curve) >= 2.5 && speedPercent > 0.35) {
            // Derrapagem de rally autêntica em curvas de terra com contra-esterço
            isDrifting = true;
            targetSlide += curveForce * 0.09;
            let slidePush = (keySlower ? 0.5 : 1.1);
            playerX = playerX - (dx * curveForce * slidePush);
        } else if (Math.abs(playerSegment.curve) >= 4 && speedPercent > 0.5) {
            let brakeFactor = keySlower ? 0.35 : 1.25;
            playerX = playerX - (dx * curveForce * brakeFactor);
            if (!keySlower && Math.abs(playerSegment.curve) >= 5) {
                isDrifting = true;
                targetSlide += curveForce * 0.08;
                speed = Util.accelerate(speed, -MAX_SPEED * 0.6 * dt, dt);
                createSparks(WIDTH / 2 + slideX * WIDTH * 0.8, HEIGHT - 30, 2);
            }
        } else {
            playerX = playerX - (dx * curveForce);
        }

        if (speedPercent > (isRallyMode ? 0.40 : 0.55)) {
            if (Math.abs(curveForce) > 0.10) {
                 isDrifting = true; targetSlide += curveForce * (isRallyMode ? 0.08 : 0.05); 
            }
            if ((keyLeft && playerSegment.curve < -1) || (keyRight && playerSegment.curve > 1)) isDrifting = true; 
        }
        
        slideX += (targetSlide - slideX) * dt * (isRallyMode ? 6 : 5);

        if (keyFaster) {
            const accelMultiplier = nitroActiveTime > 0 ? 1.85 : (inSlipstream ? 1.25 : 1);
            speed = Util.accelerate(speed, ACCEL * accelMultiplier, dt);
        } else if (keySlower) speed = Util.accelerate(speed, BREAKING, dt);
        else speed = Util.accelerate(speed, DECEL, dt);

        if ((playerX < -1 || playerX > 1) && !inPitLane) {
            let currentOffRoadDecel = weather === 'RAIN' ? OFF_ROAD_DECEL * 1.5 : OFF_ROAD_DECEL;
            if (speed > OFF_ROAD_LIMIT) {
                speed = Util.accelerate(speed, currentOffRoadDecel, dt);
                if (Math.random() < 0.15) {
                    triggerNarratorEvent('OFFROAD', null, 3);
                }
            }
        }

        const curveMagnitude = Math.abs(playerSegment.curve || 0);
        nitroCollisionCooldown = Math.max(0, nitroCollisionCooldown - dt);
        const cleanCorner = curveMagnitude >= 2.5 && speedPercent >= 0.52 &&
            Math.abs(playerX) < 0.82 && (!isDrifting || Math.abs(slideX) < 0.42) &&
            !keySlower && !playerAirborne && !inPitLane && nitroCollisionCooldown <= 0 && state === 'RACING';
        // Regeneração passiva durante toda a corrida, mesmo parado ou em baixa velocidade.
        nitroCharge = Math.min(100, nitroCharge + dt * NITRO_PASSIVE_REGEN_PER_SEC);
        // Bônus pequeno por velocidade elevada em pista (além do ganho por curva perfeita).
        if (speedPercent >= 0.90 && Math.abs(playerX) < 0.75 && !inPitLane && !playerAirborne) {
            nitroCharge = Math.min(100, nitroCharge + dt * 1.25);
        }
        if (keyNitroHeld && state === 'RACING' && nitroCharge > 0 && !inPitLane && !playerAirborne && !keySlower) {
            nitroCharge = Math.max(0, nitroCharge - dt * NITRO_HOLD_DRAIN_PER_SEC);
            nitroActiveTime = nitroCharge > 0 ? 0.18 : 0;
        } else {
            nitroActiveTime = Math.max(0, nitroActiveTime - dt);
        }
        if (cleanCorner) {
            nitroCornerTimer += dt;
            nitroCharge = Math.min(100, nitroCharge + dt * 17.5);
            if (nitroCornerTimer >= 0.42 && !nitroCornerNotified) {
                nitroCornerNotified = true; showNitroPopup(); playNitroCornerSound();
            }
        } else { nitroCornerTimer = 0; nitroCornerNotified = false; }
        if (nitroPopupTimer > 0) nitroPopupTimer = Math.max(0, nitroPopupTimer - dt);
        updateNitroEffects(dt);
        playerX = Util.limit(playerX, -2, 2);     
        speed   = Util.limit(speed, 0, currentMaxSpeed); 

        // Grava a telemetria da volta atual no modo treino
        // Usa `position` (posição pura na pista) para sincronização correta com o ghost
        if (state === 'RACING' && isTrainingMode) {
            ghostData.currentTelemetry.push({
                t: lapTime,
                z: position,      // posição real na pista (sem PLAYER_Z)
                offset: playerX,
                speed: speed,
                slideX: slideX
            });
        }

        let oldPosition = position;
        position = Util.increase(position, dt * speed, trackLength);
        
        // Marca os três checkpoints setoriais (25%, 50% e 75% da pista).
        // A máscara só é zerada no início oficial de uma volta; assim, a linha
        // de largada não pode contar como volta concluída por estar próxima do spawn.
        if (hasCrossedStartLine && trackLength > 0 && state === 'RACING') {
            const progress = Util.limit(position / trackLength, 0, 0.999999);
            if (progress >= 0.25) lapCheckpointMask |= 0b001;
            if (progress >= 0.50) lapCheckpointMask |= 0b010;
            if (progress >= 0.75) lapCheckpointMask |= 0b100;
        }

        if (position < oldPosition) {
            // A primeira passagem apenas arma o cronômetro oficial da Volta 1.
            if (!hasCrossedStartLine) {
                hasCrossedStartLine = true;
                lap = 1;
                lapTime = 0;
                lapCheckpointMask = 0;
                if (isTrainingMode) ghostData.currentTelemetry = [];
            } else if (lapCheckpointMask === LAP_CHECKPOINT_MASK_ALL) {
                // Só conclui a volta se os três setores intermediários foram validados.
                lap++;
                lapCheckpointMask = 0;
                if (isTrainingMode) {
                    if (lap === 2) {
                        ghostData.bestTelemetry = [...ghostData.currentTelemetry];
                        ghostData.bestTime = lapTime;
                        ghostData.active = true;
                        if (bestLapTime === 0 || lapTime < bestLapTime) bestLapTime = lapTime;
                        triggerNarratorEvent('GHOST_CREATED', null, 4);
                    } else if (lap > 2) {
                        if (ghostData.bestTime === 0 || lapTime < ghostData.bestTime) {
                            ghostData.bestTelemetry = [...ghostData.currentTelemetry];
                            ghostData.bestTime = lapTime;
                            ghostData.active = true;
                            bestLapTime = lapTime;
                            triggerNarratorEvent('GHOST_BEATEN', null, 4);
                        }
                    }
                    ghostData.currentTelemetry = [];
                    lapTime = 0;
                } else {
                    if (bestLapTime === 0 || lapTime < bestLapTime) bestLapTime = lapTime;
                    lapTime = 0;
                    hasCompletedPitStop = false;
                    if (lap === TOTAL_LAPS) triggerNarratorEvent('LAST_LAP', null, 4);
                    if (lap > TOTAL_LAPS) endRace();
                }
            }
            // Se a linha foi cruzada sem todos os setores, não altera a volta nem o Best Lap.
        }

        // Atualiza a posição do Carro Sombra e o Delta no modo treino
        if (isTrainingMode && ghostData.active && ghostData.bestTelemetry.length > 1 && ghostData.bestTime > 0) {
            let tSamples = ghostData.bestTelemetry;

            // Calcula o tempo alvo do ghost dentro do loop da melhor volta
            let lapCount = Math.floor(lapTime / ghostData.bestTime);
            let targetT = lapTime - lapCount * ghostData.bestTime;

            // Busca binária do frame mais próximo
            let lo = 0, hi = tSamples.length - 2;
            while (lo < hi) {
                let mid = (lo + hi + 1) >> 1;
                if (tSamples[mid].t <= targetT) lo = mid; else hi = mid - 1;
            }
            let s1 = tSamples[lo];
            let s2 = tSamples[Math.min(lo + 1, tSamples.length - 1)];
            let dt2 = s2.t - s1.t;
            let pFactor = dt2 <= 0 ? 0 : Util.limit((targetT - s1.t) / dt2, 0, 1);

            ghostData.ghostZ    = Util.interpolate(s1.z, s2.z, pFactor);
            ghostData.ghostOffset  = Util.interpolate(s1.offset, s2.offset, pFactor);
            ghostData.ghostSpeed   = Util.interpolate(s1.speed, s2.speed, pFactor);
            ghostData.ghostSlideX  = Util.interpolate(s1.slideX, s2.slideX, pFactor);

            // Delta: diferença entre tempo atual e tempo que a sombra levaria até aqui
            let deltaSec = lapTime - (lapCount * ghostData.bestTime + targetT);
            let deltaEl = document.getElementById('delta-info');
            if (deltaEl) {
                deltaEl.classList.remove('hidden');
                let sign = deltaSec > 0 ? '+' : '';
                deltaEl.innerText = 'DELTA: ' + sign + deltaSec.toFixed(3) + 's';
                deltaEl.style.color = deltaSec <= 0 ? '#00ff00' : '#ff3333';
            }
        } else {
            let deltaEl = document.getElementById('delta-info');
            if (deltaEl) deltaEl.classList.add('hidden');
        }

        updateCars(dt, playerSegment, playerX);
        updateTireSmoke(dt, speedPercent);

        let nearbyCars = [];
        [playerSegment, findSegment(position + PLAYER_Z + SEGMENT_LENGTH)].forEach(seg => {
            seg.cars.forEach(car => nearbyCars.push(car));
        });

        inSlipstream = false;
        for (let i = 0; i < nearbyCars.length; i++) {
            let car = nearbyCars[i];
            let diffZ = car.z - (position + PLAYER_Z);
            if (diffZ < 0 && diffZ > -trackLength/2) diffZ += trackLength; 
            
            let diffW = Math.abs(car.offset - playerX);

            if (Math.abs(diffZ) < 50 && diffW < 0.5) {
                shakeTimer = 1.0;
                nitroCollisionCooldown = 0.85;
                nitroCornerTimer = 0; nitroCornerNotified = false;
                speed *= 0.4; 
                car.speed *= 1.2;
                playerX += (playerX > car.offset) ? 0.25 : -0.25; 
                createSparks(WIDTH / 2 + (car.offset * WIDTH * 0.3), HEIGHT - 80, 10);
                triggerNarratorEvent('COLLISION', car, 4);
                break; 
            }

            if (diffZ > 0 && diffZ < 400 && diffW < 0.2 && speed > MAX_SPEED * 0.5) {
                if (!inSlipstream) {
                    triggerNarratorEvent('SLIPSTREAM', car, 2);
                }
                inSlipstream = true;
            }
        }

        let aheadSegment = findSegment(position + PLAYER_Z + 800);
        curveWarningCooldown -= dt;
        if (Math.abs(aheadSegment.curve) >= 6 && speedPercent > 0.7 && curveWarningCooldown <= 0 && !keySlower) {
            triggerNarratorEvent('CURVE_WARNING', null, 2);
            curveWarningCooldown = 6.0;
        }

        straightSpeechCooldown -= dt;
        if (playerSegment.curve === 0 && aheadSegment.curve === 0 && speedPercent > 0.88 && straightSpeechCooldown <= 0) {
            triggerNarratorEvent('STRAIGHT', null, 1);
            straightSpeechCooldown = 8.0;
        }

        updateSparks(dt);
        updateNarratorSystem(dt);
        updateHUD();
        updateAudio();
    }

    function updateCutscene(dt) {
        cutsceneTime += dt;
        let startGridZ = trackLength - (10 * 800);
        let playerTargetZ = startGridZ - PLAYER_Z;

        if (cutsceneTime < 1.0) cinematicBarHeight = Util.easeInOut(0, HEIGHT * 0.12, cutsceneTime);
        else if (cutsceneTime > 8.5) cinematicBarHeight = Util.easeInOut(HEIGHT * 0.12, 0, (cutsceneTime - 8.5) / 1.5);
        else cinematicBarHeight = HEIGHT * 0.12;

        let phase = 0; let z = 0;

        if (cutsceneTime < 3.0) {
            phase = 1; let p = cutsceneTime / 3.0;
            cameraHeight = Util.easeInOut(2000, 1500, p); cutsceneCamX = Util.easeInOut(-2.0, 1.0, p);
            z = Util.easeInOut(trackLength - 2000, trackLength + 1000, p);
        } else if (cutsceneTime < 6.5) {
            phase = 2; let p = (cutsceneTime - 3.0) / 3.5;
            cameraHeight = Util.easeInOut(400, 600, p); cutsceneCamX = Util.easeInOut(1.5, -0.5, p);
            z = Util.easeInOut(trackLength - 7500, trackLength - 500, p);
        } else if (cutsceneTime < 9.5) {
            phase = 3; let p = Util.easeInOut(0, 1, (cutsceneTime - 6.5) / 3.0);
            cameraHeight = Util.easeInOut(1500, 1000, p); cutsceneCamX = Util.easeInOut(-1.0, -0.4, p);
            z = Util.easeInOut(playerTargetZ - 3000, playerTargetZ, p);
        } else {
            cutsceneTitle.style.display = 'none';
            position = playerTargetZ;
            while(position < 0) position += trackLength;
            playerX = -0.4; cameraHeight = 1500; cinematicBarHeight = 0;
            
            cars = cars.filter(c => !c.isDummy);
            segments.forEach(seg => { seg.cars = seg.cars.filter(c => !c.isDummy); });

            startLightsCountdown();
    
        }

        cutsceneCamZ = z;
        while(cutsceneCamZ < 0) cutsceneCamZ += trackLength;
        while(cutsceneCamZ >= trackLength) cutsceneCamZ -= trackLength;

        if (cutscenePhase !== phase) {
            cutscenePhase = phase;
            cutsceneTitle.style.animation = 'none';
            void cutsceneTitle.offsetWidth; 
            cutsceneTitle.classList.add('pulse-text');

            if (phase === 1) cutsceneTitle.innerHTML = STAGES[currentStage].name;
            else if (phase === 2) cutsceneTitle.innerHTML = "AQUECENDO OS PNEUS...";
            else if (phase === 3) cutsceneTitle.innerHTML = "PREPARE-SE PARA A LARGADA!";
        }
    }

    function updateCars(dt, playerSegment, playerW) {
        for(let i=0; i<cars.length; i++) {
            let car = cars[i];
            if (car.isDummy || car.isRemote) continue;
            let oldSegment = findSegment(car.z);

            if (car.finished) {
                car.speed = Math.max(0, car.speed - (MAX_SPEED * 0.8 * dt));
                let parkTarget = (i % 2 === 0) ? 0.75 : -0.75;
                car.offset += (parkTarget - car.offset) * dt * 2.0;
                car.isDrifting = false;
            } else {
                // IA AVANÇADA DE PILOTAGEM: TRAJETÓRIA DE CURVA (APEX LINE) E VELOCIDADE ADAPTATIVA
                let aheadSeg = findSegment(car.z + 800);
                let targetMaxSpeed = weather === 'RAIN' ? car.maxSpeed * 0.84 : car.maxSpeed;

                // Freada inteligente para curvas fechadas
                if (Math.abs(aheadSeg.curve) >= 5) {
                    targetMaxSpeed *= 0.65;
                } else if (Math.abs(aheadSeg.curve) >= 3) {
                    targetMaxSpeed *= 0.82;
                }

                let carAccel = ACCEL * (car.accelFactor || 1.0);
                car.speed = Util.limit(Util.accelerate(car.speed, car.speed > targetMaxSpeed ? -ACCEL * 1.2 : carAccel, dt), 0, car.maxSpeed);

                // Cálculo de Tangenciamento de Curva (Racing Apex Line: Fora -> Dentro -> Fora)
                let idealOffset = car.offset;
                if (aheadSeg.curve > 2) {
                    idealOffset = -0.55; // Curva pra direita: tangencia na esquerda
                } else if (aheadSeg.curve < -2) {
                    idealOffset = 0.55;  // Curva pra esquerda: tangencia na direita
                } else {
                    idealOffset = (i % 2 === 0) ? 0.25 : -0.25;
                }
                
                car.offset += (idealOffset - car.offset) * dt * 2.5;
            }

            let prevZ = car.z;
            car.z = Util.increase(car.z, dt * car.speed, trackLength);

            if (car.z < prevZ && !car.finished && state === 'RACING') {
                car.lapsCompleted++;
                if (car.lapsCompleted >= TOTAL_LAPS) {
                    car.finished = true;
                }
            }

            let newSegment = findSegment(car.z);
            if (oldSegment != newSegment) {
                oldSegment.cars.splice(oldSegment.cars.indexOf(car), 1);
                newSegment.cars.push(car);
            }

            if (!car.finished && Math.abs(newSegment.curve) >= 3.0 && (car.speed > car.maxSpeed * 0.55)) {
                car.isDrifting = true;
            } else {
                car.isDrifting = false;
            }

            // Salto dos carros da IA ao passar por rampas de terra no Rally
            if (newSegment.isRamp && car.speed > car.maxSpeed * 0.35 && !car.isAirborne) {
                car.isAirborne = true;
                car.jumpVel = Math.min(620, (car.speed / car.maxSpeed) * 520 + 120);
                car.jumpY = 0;
            }
            if (car.isAirborne) {
                car.jumpY = (car.jumpY || 0) + car.jumpVel * dt;
                car.jumpVel -= 1200 * dt;
                if (car.jumpY <= 0) {
                    car.jumpY = 0;
                    car.isAirborne = false;
                }
            }
        }

        // IA DE ULTRAPASSAGEM, VÁCUO E BLOQUEIO DEFENSIVO
        for(let i=0; i<cars.length; i++) {
            let carA = cars[i];
            if (carA.isDummy || carA.isRemote || carA.finished) continue;

            // Bloqueio defensivo da IA contra o jogador se o jogador estiver tentando ultrapassar
            if (carA.z > position && (carA.z - position) < 500 && Math.abs(carA.offset - playerW) < 0.4) {
                carA.offset += (playerW > carA.offset ? 0.08 : -0.08) * dt * (carA.aggressiveness || 0.7);
                carA.offset = Util.limit(carA.offset, -0.75, 0.75);
            }

            for(let j=i+1; j<cars.length; j++) {
                let carB = cars[j];
                if (carB.isDummy || carB.isRemote || carB.finished) continue;

                let diffZ = carA.z - carB.z;
                if (diffZ < -trackLength/2) diffZ += trackLength;
                if (diffZ > trackLength/2) diffZ -= trackLength;
                let absDiffZ = Math.abs(diffZ);
                let diffW = Math.abs(carA.offset - carB.offset);

                if (absDiffZ < 55 && diffW < 0.45) {
                    let push = 0.18;
                    if (carA.offset > carB.offset) {
                        carA.offset = Util.limit(carA.offset + push, -0.85, 0.85);
                        carB.offset = Util.limit(carB.offset - push, -0.85, 0.85);
                    } else {
                        carA.offset = Util.limit(carA.offset - push, -0.85, 0.85);
                        carB.offset = Util.limit(carB.offset + push, -0.85, 0.85);
                    }
                    carA.speed *= 0.90;
                    carB.speed *= 0.90;
                }

                // Manobra de ultrapassagem da IA no Vácuo
                if (absDiffZ > 55 && absDiffZ < 350 && diffW < 0.3) {
                    let chaser = diffZ < 0 ? carA : carB;
                    let target = diffZ < 0 ? carB : carA;
                    chaser.speed = Math.min(chaser.maxSpeed * 1.14, chaser.speed + ACCEL * 0.5 * dt);
                    // Bota do lado pra ultrapassar
                    chaser.offset += (chaser.offset < target.offset ? -0.2 : 0.2) * dt * 3.0;
                    chaser.offset = Util.limit(chaser.offset, -0.8, 0.8);
                }
            }
        }

        let pos = 1;
        let nearbyOpponent = null;

        for(let i=0; i<cars.length; i++) {
            if (cars[i].isDummy) continue;
            let aiDist = cars[i].z;
            if(aiDist < position && (position - aiDist) > trackLength/2) aiDist += trackLength;
            if(aiDist > position && (aiDist - position) > trackLength/2) aiDist -= trackLength;
            if(aiDist > position) pos++;

            let diffZ = Math.abs(cars[i].z - (position + PLAYER_Z));
            if (diffZ < 400) {
                nearbyOpponent = cars[i];
            }
        }

        if (state === 'RACING') {
            if (pos < lastPlayerPosCheck) {
                if (pos === 1) {
                    triggerNarratorEvent('LEADER', nearbyOpponent, 4);
                } else {
                    triggerNarratorEvent('OVERTAKE', nearbyOpponent, 3);
                }
            } else if (pos > lastPlayerPosCheck) {
                triggerNarratorEvent('OVERTAKEN', nearbyOpponent, 3);
            }
            lastPlayerPosCheck = pos;
        }

        playerPos = pos;
    }

    function drawClouds(horizonX) {
        for (let i = 0; i < cloudParticles.length; i++) {
            let cloud = cloudParticles[i];
            let cloudX = (cloud.x - horizonX * 0.4) % (WIDTH + 300);
            if (cloudX < -300) cloudX += WIDTH + 300;

            ctx.fillStyle = cloud.color;
            ctx.beginPath();
            ctx.arc(cloudX, cloud.y, cloud.radius, 0, Math.PI * 2);
            ctx.arc(cloudX + cloud.radius * 0.7, cloud.y - cloud.radius * 0.3, cloud.radius * 0.8, 0, Math.PI * 2);
            ctx.arc(cloudX + cloud.radius * 1.4, cloud.y, cloud.radius * 0.9, 0, Math.PI * 2);
            ctx.fill();

            cloud.x += cloud.speed * 0.05;
        }
    }

    function drawBackground() {
        let activePos = state === 'CUTSCENE' ? cutsceneCamZ : position;
        let baseSegment = findSegment(activePos);
        let curveTotal = 0;
        for(let i=0; i<50; i++) curveTotal += segments[(baseSegment.index+i)%segments.length].curve;
        let horizonX = -(curveTotal * 0.5);

        let stg = STAGES[currentStage];
        let isBeach = stg && stg.theme === 'BEACH';
        let isNascar = currentSeries === 'NASCAR' || (stg && stg.theme && stg.theme.startsWith('NASCAR'));
        let isRally = currentSeries === 'RALLY' || (stg && stg.theme && stg.theme.startsWith('RALLY'));

        let skyGrad = ctx.createLinearGradient(0, 0, 0, HEIGHT/2);
        if (isRally) {
            if (weather === 'RAIN') {
                skyGrad.addColorStop(0, '#111827');
                skyGrad.addColorStop(0.5, '#1e293b');
                skyGrad.addColorStop(1, '#334155');
            } else if (weather === 'SUNSET') {
                skyGrad.addColorStop(0, '#431407');
                skyGrad.addColorStop(0.35, '#9a3412');
                skyGrad.addColorStop(0.7, '#ea580c');
                skyGrad.addColorStop(1, '#fde047');
            } else {
                skyGrad.addColorStop(0, '#0369a1');
                skyGrad.addColorStop(0.5, '#38bdf8');
                skyGrad.addColorStop(1, '#bae6fd');
            }
        } else if (isNascar) {
            if (weather === 'RAIN') {
                skyGrad.addColorStop(0, '#090d16'); 
                skyGrad.addColorStop(0.5, '#1e2638'); 
                skyGrad.addColorStop(1, '#334155');
            } else if (weather === 'SUNSET') {
                skyGrad.addColorStop(0, '#180728'); 
                skyGrad.addColorStop(0.3, '#581c87'); 
                skyGrad.addColorStop(0.6, '#c026d3'); 
                skyGrad.addColorStop(0.85, '#ea580c');
                skyGrad.addColorStop(1, '#fde047');
            } else {
                skyGrad.addColorStop(0, '#0284c7'); 
                skyGrad.addColorStop(0.5, '#38bdf8'); 
                skyGrad.addColorStop(1, '#bae6fd');
            }
        } else if (isBeach) {
            if (weather === 'RAIN') {
                skyGrad.addColorStop(0, '#101820'); 
                skyGrad.addColorStop(0.6, '#2c3539');
                skyGrad.addColorStop(1, '#4a5568');
            } else if (weather === 'SUNSET') {
                skyGrad.addColorStop(0, '#2b0938'); 
                skyGrad.addColorStop(0.3, '#b5179e'); 
                skyGrad.addColorStop(0.7, '#f72585'); 
                skyGrad.addColorStop(1, '#ffb703');
            } else {
                skyGrad.addColorStop(0, '#00b4d8'); 
                skyGrad.addColorStop(0.6, '#90e0ef'); 
                skyGrad.addColorStop(1, '#caf0f8');
            }
        } else {
            if (weather === 'RAIN') {
                skyGrad.addColorStop(0, '#151921'); 
                skyGrad.addColorStop(0.7, '#2b3642');
                skyGrad.addColorStop(1, '#445363');
            } else if (weather === 'SUNSET') {
                skyGrad.addColorStop(0, '#1a0b26'); 
                skyGrad.addColorStop(0.3, '#6e1346'); 
                skyGrad.addColorStop(0.7, '#e64a19'); 
                skyGrad.addColorStop(1, '#ff8a00');
            } else {
                skyGrad.addColorStop(0, '#0f52ba'); 
                skyGrad.addColorStop(0.6, '#4682b4'); 
                skyGrad.addColorStop(1, '#87ceeb');
            }
        }
        ctx.fillStyle = skyGrad; 
        ctx.fillRect(0, 0, WIDTH, HEIGHT/2);

        if (weather === 'CLEAR') {
            let sunX = WIDTH * 0.7 + horizonX * 0.05;
            let sunY = HEIGHT/2 - 100;
            let sunGlow = ctx.createRadialGradient(sunX, sunY, 10, sunX, sunY, 90);
            sunGlow.addColorStop(0, 'rgba(255, 255, 220, 1)');
            sunGlow.addColorStop(0.4, 'rgba(255, 240, 150, 0.4)');
            sunGlow.addColorStop(1, 'rgba(255, 255, 255, 0)');
            ctx.fillStyle = sunGlow; ctx.beginPath(); ctx.arc(sunX, sunY, 90, 0, Math.PI*2); ctx.fill();
        } else if (weather === 'SUNSET') {
            let sunX = (WIDTH * 0.5 + horizonX * 0.1) % (WIDTH + 200);
            let sunY = HEIGHT/2 - 35;
            let sunGlow = ctx.createRadialGradient(sunX, sunY, 15, sunX, sunY, 120);
            sunGlow.addColorStop(0, '#ffea00');
            sunGlow.addColorStop(0.3, 'rgba(255, 100, 0, 0.6)');
            sunGlow.addColorStop(1, 'rgba(255, 0, 0, 0)');
            ctx.fillStyle = sunGlow; ctx.beginPath(); ctx.arc(sunX, sunY, 120, 0, Math.PI*2); ctx.fill();
        }

        drawClouds(horizonX);

        if (isRally) {
            // === PAISAGEM PANORÂMICA E HORIZONTE DE RALLY WRC ===
            let horizonH = HEIGHT / 2;

            // 1. Helicóptero de Transmissão da TV WRC (WRC Live Broadcast Heli)
            let heliX = ((Date.now() * 0.035 - horizonX * 0.25) % (WIDTH + 260));
            if (heliX < -130) heliX += WIDTH + 260;
            let heliY = 40 + Math.sin(Date.now() * 0.003) * 8;

            ctx.save();
            ctx.translate(heliX, heliY);
            // Fuselagem do Helicóptero
            ctx.fillStyle = '#dc2626';
            ctx.beginPath();
            ctx.ellipse(0, 0, 24, 10, 0, 0, Math.PI * 2);
            ctx.fill();
            // Cabine de vidro
            ctx.fillStyle = '#38bdf8';
            ctx.fillRect(8, -5, 12, 8);
            // Cauda e rotor de cauda
            ctx.fillStyle = '#ffffff';
            ctx.fillRect(-34, -2, 16, 4);
            ctx.fillStyle = '#dc2626';
            ctx.fillRect(-36, -8, 4, 14);
            // Rotor Principal Giratório
            ctx.strokeStyle = 'rgba(255, 255, 255, 0.7)';
            ctx.lineWidth = 2;
            let bladeAngle = (Date.now() * 0.05) % Math.PI;
            ctx.beginPath();
            ctx.moveTo(-Math.cos(bladeAngle) * 36, -11);
            ctx.lineTo(Math.cos(bladeAngle) * 36, -11);
            ctx.stroke();
            // Câmera Cineflex na ponta
            ctx.fillStyle = '#111827';
            ctx.beginPath(); ctx.arc(16, 7, 3, 0, Math.PI * 2); ctx.fill();
            ctx.restore();

            // 2. Cadeia de Montanhas / Cordilheira no Horizonte
            let mtnBaseY = horizonH;
            ctx.fillStyle = weather === 'RAIN' ? '#1e293b' : (weather === 'SUNSET' ? '#581c87' : '#1e3a5f');
            ctx.beginPath();
            ctx.moveTo(0, mtnBaseY);
            for (let mx = 0; mx <= WIDTH + 100; mx += 60) {
                let peakH = 45 + Math.sin((mx - horizonX * 0.2) * 0.02) * 30 + Math.cos((mx - horizonX * 0.15) * 0.05) * 20;
                ctx.lineTo(mx, mtnBaseY - peakH);
            }
            ctx.lineTo(WIDTH, mtnBaseY);
            ctx.closePath();
            ctx.fill();

            // 3. Silhueta de Floresta de Pinheiros no Sopé das Montanhas
            ctx.fillStyle = weather === 'RAIN' ? '#0f172a' : (weather === 'SUNSET' ? '#3b0764' : '#064e3b');
            ctx.beginPath();
            ctx.moveTo(0, mtnBaseY);
            for (let px = 0; px <= WIDTH + 40; px += 16) {
                let treeH = 18 + Math.sin((px - horizonX * 0.3) * 0.08) * 8;
                ctx.lineTo(px, mtnBaseY - treeH);
                ctx.lineTo(px + 8, mtnBaseY);
            }
            ctx.closePath();
            ctx.fill();

            // 4. Faixa de terra / verge no horizonte
            let groundCol = weather === 'RAIN' ? '#2e1c0e' : (weather === 'SUNSET' ? '#78350f' : '#543015');
            ctx.fillStyle = groundCol;
            ctx.fillRect(0, horizonH - 2, WIDTH, 4);

        } else if (isNascar) {
            // === PAISAGEM PANORÂMICA E HORIZONTE DE SUPERSPEEDWAY NASCAR ===
            let stadiumH = HEIGHT / 2;

            // 1. Dirigível Goodyear (Blimp) sobrevoando o circuito
            let blimpX = ((Date.now() * 0.02 - horizonX * 0.15) % (WIDTH + 260));
            if (blimpX < -130) blimpX += WIDTH + 260;
            let blimpY = 30 + Math.sin(Date.now() * 0.002) * 6;

            ctx.save();
            ctx.translate(blimpX, blimpY);
            // Sombra/Brilho do dirigível
            ctx.fillStyle = '#00205b';
            ctx.beginPath();
            ctx.ellipse(0, 0, 52, 18, 0, 0, Math.PI * 2);
            ctx.fill();
            // Faixa amarela Goodyear
            ctx.fillStyle = '#ffcc00';
            ctx.beginPath();
            ctx.ellipse(0, 3, 48, 6, 0, 0, Math.PI * 2);
            ctx.fill();
            // Cabine / Gondola
            ctx.fillStyle = '#ffffff';
            ctx.fillRect(-12, 14, 24, 7);
            // Luz estroboscópica de aviação
            let blink = (Date.now() % 1000 < 500);
            ctx.fillStyle = blink ? '#ff0033' : '#ffffff';
            ctx.fillRect(-2, -19, 4, 3);
            ctx.fillRect(0, 20, 3, 3);
            // Letreiro LED digital no casco
            ctx.fillStyle = '#ffcc00';
            ctx.font = '6px "Press Start 2P"';
            ctx.fillText("GOODYEAR", -22, 2);
            ctx.restore();

            // 2. Lago Interno de Daytona (Lake Lloyd Infield Water)
            let lakeY = stadiumH - 22;
            let lakeColor = weather === 'RAIN' ? '#16222f' : (weather === 'SUNSET' ? '#4c1d58' : '#0369a1');
            ctx.fillStyle = lakeColor;
            ctx.fillRect(0, lakeY, WIDTH, 18);
            // Brilho na água do lago
            ctx.strokeStyle = weather === 'SUNSET' ? 'rgba(251, 191, 36, 0.4)' : 'rgba(255, 255, 255, 0.35)';
            ctx.lineWidth = 1.5;
            for (let wy = lakeY + 3; wy < stadiumH - 4; wy += 5) {
                ctx.beginPath();
                for (let wx = 0; wx < WIDTH; wx += 25) {
                    let lx = wx + Math.sin((wx + Date.now() * 0.03) * 0.05) * 4;
                    ctx.moveTo(lx, wy);
                    ctx.lineTo(lx + 14, wy);
                }
                ctx.stroke();
            }

            // 3. Silhueta das Arquibancadas Distantes ao redor de todo o circuito (Daytona / Talladega)
            ctx.fillStyle = weather === 'RAIN' ? '#0f172a' : (weather === 'SUNSET' ? '#2e1065' : '#1e293b');
            ctx.fillRect(0, stadiumH - 44, WIDTH, 24);

            // Friso do teto da arquibancada com iluminação
            ctx.fillStyle = weather === 'RAIN' ? '#1f2937' : (weather === 'SUNSET' ? '#ea580c' : '#e10600');
            ctx.fillRect(0, stadiumH - 44, WIDTH, 3);

            // 4. Janelas de Camarotes VIP e Telões no fundo
            for (let bx = 0; bx < WIDTH; bx += 22) {
                let wx = bx - (horizonX * 0.35);
                let suiteX = (wx % (WIDTH + 44));
                if (suiteX < -22) suiteX += WIDTH + 44;
                ctx.fillStyle = (bx % 44 === 0) ? '#38bdf8' : '#fbbf24';
                ctx.fillRect(suiteX, stadiumH - 38, 12, 5);
                ctx.fillStyle = '#090d16';
                ctx.fillRect(suiteX, stadiumH - 30, 14, 8);
            }

            // 5. Infield Gramado do Speedway no horizonte
            ctx.fillStyle = weather === 'RAIN' ? '#142816' : (weather === 'SUNSET' ? '#253818' : '#255721');
            ctx.fillRect(0, stadiumH - 4, WIDTH, 4);

            // 6. Holofotes Gigantes do Estádio no Horizonte
            for (let tx = 40; tx < WIDTH + 140; tx += 140) {
                let towerX = (tx - (horizonX * 0.45)) % (WIDTH + 140);
                if (towerX < -70) towerX += WIDTH + 140;
                
                // Mastro de aço treliçado
                ctx.fillStyle = '#94a3b8';
                ctx.fillRect(towerX - 2, stadiumH - 92, 4, 88);
                // Bateria de refletores no topo
                ctx.fillStyle = '#ffffff';
                ctx.fillRect(towerX - 16, stadiumH - 98, 32, 8);
                
                // Brilho suave da luz
                let beamGrad = ctx.createLinearGradient(towerX, stadiumH - 98, towerX, stadiumH);
                beamGrad.addColorStop(0, 'rgba(255, 255, 230, 0.28)');
                beamGrad.addColorStop(1, 'rgba(255, 255, 255, 0)');
                ctx.fillStyle = beamGrad;
                ctx.beginPath();
                ctx.moveTo(towerX - 14, stadiumH - 98);
                ctx.lineTo(towerX + 14, stadiumH - 98);
                ctx.lineTo(towerX + 40, stadiumH);
                ctx.lineTo(towerX - 40, stadiumH);
                ctx.closePath();
                ctx.fill();
            }

        } else if (isBeach) {
            let oceanColor = weather === 'RAIN' ? '#1d2d44' : (weather === 'SUNSET' ? '#5c1d68' : '#0077b6');
            ctx.fillStyle = oceanColor;
            ctx.fillRect(0, HEIGHT/2 - 50, WIDTH, 50);

            ctx.strokeStyle = weather === 'RAIN' ? 'rgba(255,255,255,0.2)' : 'rgba(255,255,255,0.4)';
            ctx.lineWidth = 2;
            for(let waveY = HEIGHT/2 - 40; waveY < HEIGHT/2; waveY += 12) {
                ctx.beginPath();
                for(let x = 0; x <= WIDTH; x += 20) {
                    let wx = x - (horizonX * 0.3) + Date.now() * 0.02;
                    let wy = waveY + Math.sin(wx * 0.05) * 3;
                    if (x === 0) ctx.moveTo(x, wy); else ctx.lineTo(x, wy);
                }
                ctx.stroke();
            }

            let duneColor = weather === 'RAIN' ? '#4a4038' : (weather === 'SUNSET' ? '#a05c7b' : '#e9c46a');
            ctx.fillStyle = duneColor;
            ctx.beginPath(); ctx.moveTo(0, HEIGHT/2);
            for(let x = 0; x <= WIDTH; x += 15) {
                let wx = x - (horizonX * 0.5);
                let h = 25 + Math.sin(wx*0.015)*18 + Math.cos(wx*0.03)*12;
                ctx.lineTo(x, HEIGHT/2 - Math.max(0, h));
            }
            ctx.lineTo(WIDTH, HEIGHT/2); ctx.fill();
        } else {
            ctx.fillStyle = weather === 'RAIN' ? '#212a33' : (weather === 'SUNSET' ? '#2e1136' : '#5782a1');
            ctx.beginPath(); ctx.moveTo(0, HEIGHT/2);
            for(let x = 0; x <= WIDTH; x += 10) {
                let wx = x - (horizonX * 0.2);
                let h = 80 + Math.sin(wx*0.006)*60 + Math.cos(wx*0.01)*20;
                ctx.lineTo(x, HEIGHT/2 - Math.max(0, h));
            }
            ctx.lineTo(WIDTH, HEIGHT/2); ctx.fill();

            ctx.fillStyle = weather === 'RAIN' ? '#11161a' : (weather === 'SUNSET' ? '#1f0719' : '#1b4a25');
            ctx.beginPath(); ctx.moveTo(0, HEIGHT/2);
            for(let x = 0; x <= WIDTH; x += 10) {
                let wx = x - (horizonX * 0.7);
                let h = 15 + Math.sin(wx*0.06)*10;
                ctx.lineTo(x, HEIGHT/2 - Math.max(0, h));
            }
            ctx.lineTo(WIDTH, HEIGHT/2); ctx.fill();
        }
    }

    
    function updateVictoryCelebration(dt) {
        if (state !== 'FINISHED' || playerPos !== 1) return;
        victoryCelebrationTimer += dt;

        // Gera chuva contínua de confetes coloridos festivos
        if (victoryConfetti.length < 180) {
            const confColors = ['#ffd700', '#ff0055', '#00ffcc', '#ffffff', '#ff9900', '#33ff33', '#cc00ff'];
            for (let i = 0; i < 4; i++) {
                victoryConfetti.push({
                    x: Math.random() * WIDTH,
                    y: -15,
                    w: 5 + Math.random() * 6,
                    h: 3 + Math.random() * 4,
                    color: confColors[Math.floor(Math.random() * confColors.length)],
                    vx: (Math.random() - 0.5) * 80,
                    vy: 70 + Math.random() * 110,
                    rot: Math.random() * Math.PI * 2,
                    rotSpeed: (Math.random() - 0.5) * 6,
                    wobble: Math.random() * Math.PI * 2,
                    wobbleSpeed: 2 + Math.random() * 4
                });
            }
        }

        // Animação dos confetes
        for (let i = victoryConfetti.length - 1; i >= 0; i--) {
            let p = victoryConfetti[i];
            p.wobble += dt * p.wobbleSpeed;
            p.x += (p.vx + Math.sin(p.wobble) * 25) * dt;
            p.y += p.vy * dt;
            p.rot += p.rotSpeed * dt;
            if (p.y > HEIGHT + 20) victoryConfetti.splice(i, 1);
        }

        // Fogos de artifício no topo do céu (rockets & bursts)
        if (Math.random() < 0.08 && victoryFireworks.length < 10) {
            let colors = ['#ffcc00', '#00ffea', '#ff1493', '#00ff66', '#ffffff', '#ff4500'];
            let cx = 80 + Math.random() * (WIDTH - 160);
            let cy = 40 + Math.random() * (HEIGHT * 0.38);
            let burstColor = colors[Math.floor(Math.random() * colors.length)];
            let particles = [];
            for (let j = 0; j < 30; j++) {
                let angle = (j / 30) * Math.PI * 2;
                let spd = 30 + Math.random() * 85;
                particles.push({
                    x: cx, y: cy,
                    vx: Math.cos(angle) * spd,
                    vy: Math.sin(angle) * spd,
                    alpha: 1.0,
                    color: burstColor,
                    size: 2.5 + Math.random() * 2.5
                });
            }
            victoryFireworks.push({ particles, life: 1.0 });
        }

        for (let f = victoryFireworks.length - 1; f >= 0; f--) {
            let fw = victoryFireworks[f];
            fw.life -= dt * 1.2;
            for (let p of fw.particles) {
                p.x += p.vx * dt;
                p.y += p.vy * dt + 20 * dt; // gravidade leve
                p.alpha = Math.max(0, fw.life);
            }
            if (fw.life <= 0) victoryFireworks.splice(f, 1);
        }

        // Fumaça de celebração e pneus cantando na desaceleração da vitória
        if (speed > 80 && Math.random() < 0.3) {
            let playerScreenX = WIDTH / 2 + (slideX * WIDTH * 1.5);
            let playerScreenY = HEIGHT - 15;
            for (let k = 0; k < 2; k++) {
                tireSmokeParticles.push({
                    x: playerScreenX + (k === 0 ? -30 : 30) + (Math.random() - 0.5) * 15,
                    y: playerScreenY,
                    life: 0.9,
                    vx: (k === 0 ? -35 : 35) + (Math.random() - 0.5) * 20,
                    vy: -15 - Math.random() * 30,
                    size: 8 + Math.random() * 14,
                    colorBase: 'rgba(240, 240, 240, ',
                    isOffRoad: false
                });
            }
        }
    }

    function drawVictoryCelebration(ctx) {
        if (state !== 'FINISHED' || playerPos !== 1) return;
        ctx.save();

        // 1. Fogos de artifício estourando no céu
        for (let fw of victoryFireworks) {
            for (let p of fw.particles) {
                ctx.fillStyle = p.color;
                ctx.globalAlpha = p.alpha;
                ctx.beginPath();
                ctx.arc(p.x, p.y, p.size, 0, Math.PI * 2);
                ctx.fill();
            }
        }
        ctx.globalAlpha = 1.0;

        // 2. Chuva festiva de confetes
        for (let p of victoryConfetti) {
            ctx.save();
            ctx.translate(p.x, p.y);
            ctx.rotate(p.rot);
            ctx.fillStyle = p.color;
            ctx.fillRect(-p.w / 2, -p.h / 2, p.w, p.h);
            ctx.restore();
        }

        // 3. Bordas dinâmicas de bandeira quadriculada (Checkered Flag dynamic borders)
        let checkerSize = 14;
        let tOffset = (victoryCelebrationTimer * 28) % (checkerSize * 2);
        
        // Borda Superior
        for (let x = -checkerSize * 2; x < WIDTH + checkerSize * 2; x += checkerSize) {
            for (let y = 0; y < checkerSize * 2; y += checkerSize) {
                let row = Math.floor(y / checkerSize);
                let col = Math.floor((x + tOffset) / checkerSize);
                let isBlack = (row + col) % 2 === 0;
                ctx.fillStyle = isBlack ? 'rgba(0,0,0,0.85)' : 'rgba(255,255,255,0.95)';
                ctx.fillRect(x + tOffset, y, checkerSize, checkerSize);
            }
        }

        // Borda Inferior
        for (let x = -checkerSize * 2; x < WIDTH + checkerSize * 2; x += checkerSize) {
            for (let y = 0; y < checkerSize * 2; y += checkerSize) {
                let row = Math.floor(y / checkerSize);
                let col = Math.floor((x - tOffset) / checkerSize);
                let isBlack = (row + col) % 2 === 0;
                ctx.fillStyle = isBlack ? 'rgba(0,0,0,0.85)' : 'rgba(255,255,255,0.95)';
                ctx.fillRect(x - tOffset, HEIGHT - (checkerSize * 2) + y, checkerSize, checkerSize);
            }
        }

        // 4. Banner Retro Flutuante "1º LUGAR - GRANDE VITÓRIA!"
        let bannerY = 56 + Math.sin(victoryCelebrationTimer * 4) * 5;
        ctx.fillStyle = 'rgba(5, 10, 25, 0.94)';
        ctx.fillRect(WIDTH / 2 - 210, bannerY - 18, 420, 36);
        ctx.strokeStyle = '#ffd700';
        ctx.lineWidth = 3;
        ctx.strokeRect(WIDTH / 2 - 210, bannerY - 18, 420, 36);

        ctx.fillStyle = '#ffd700';
        ctx.font = 'bold 12px "Press Start 2P", monospace';
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        ctx.shadowColor = '#ffaa00';
        ctx.shadowBlur = 10;
        ctx.fillText("🏆 VITÓRIA! 1º LUGAR! 🏆", WIDTH / 2, bannerY);
        ctx.shadowBlur = 0;
        ctx.textAlign = 'start';

        ctx.restore();
    }
function draw() {
        ctx.save();
        if (shakeTimer > 0) {
            let sx = (Math.random() - 0.5) * shakeTimer * 20;
            let sy = (Math.random() - 0.5) * shakeTimer * 20;
            ctx.translate(sx, sy);
        }

        drawBackground();

        let renderPos = state === 'CUTSCENE' ? cutsceneCamZ : position;
        let renderX = state === 'CUTSCENE' ? cutsceneCamX : playerX;

        let baseSegment = findSegment(renderPos);
        let basePercent = Util.percentRemaining(renderPos, SEGMENT_LENGTH);
        let playerY = Util.interpolate(baseSegment.p1.world.y, baseSegment.p2.world.y, basePercent);
        let maxy = HEIGHT;

        let x = 0, dx = - (baseSegment.curve * basePercent);
        
        ctx.fillStyle = COLORS.LIGHT.grass;
        ctx.fillRect(0, HEIGHT/2, WIDTH, HEIGHT/2);

        let firstRendered = false;

        for(let n=0; n<DRAW_DISTANCE; n++) {
            let segment = segments[(baseSegment.index + n) % segments.length];
            segment.looped = segment.index < baseSegment.index;
            segment.fog = Util.exponentialFog(n/DRAW_DISTANCE, 4.5); 

            Util.project(segment.p1, (renderX * TRACK_WIDTH) - x, playerY + cameraHeight, renderPos - (segment.looped ? trackLength : 0), CAMERA_DEPTH, WIDTH, HEIGHT, TRACK_WIDTH);
            Util.project(segment.p2, (renderX * TRACK_WIDTH) - x - dx, playerY + cameraHeight, renderPos - (segment.looped ? trackLength : 0), CAMERA_DEPTH, WIDTH, HEIGHT, TRACK_WIDTH);
            
            x  = x + dx; dx = dx + segment.curve;
            segment.clip = maxy;

            if (segment.p1.camera.z <= CAMERA_DEPTH) continue;
            if (segment.p2.screen.y >= segment.p1.screen.y) continue;
            if (n > 0 && segment.p2.screen.y >= maxy) continue;

            let renderY1 = segment.p1.screen.y;
            if (!firstRendered) {
                if (renderY1 < HEIGHT) renderY1 = HEIGHT;
                firstRendered = true;
            }

            let isNascarMode = currentSeries === 'NASCAR' || (STAGES[currentStage] && STAGES[currentStage].theme && STAGES[currentStage].theme.startsWith('NASCAR'));
            let isRallyMode = currentSeries === 'RALLY' || (STAGES[currentStage] && STAGES[currentStage].theme && STAGES[currentStage].theme.startsWith('RALLY'));
            Render.segment(ctx, WIDTH, LANES,
                segment.p1.screen.x, renderY1, segment.p1.screen.w,
                segment.p2.screen.x, segment.p2.screen.y, segment.p2.screen.w,
                segment.fog, segment.color, segment.index,
                isNascarMode, isRallyMode, segment.isRamp
            );
            maxy = Math.min(maxy, segment.p1.screen.y); 
        }

        for(let n = (DRAW_DISTANCE-1); n > 0; n--) {
            let segment = segments[(baseSegment.index + n) % segments.length];
            
            for(let i=0; i<segment.sprites.length; i++) {
                let sprite = segment.sprites[i];
                let spriteScale = segment.p1.screen.scale;
                let spriteX = segment.p1.screen.x + (spriteScale * sprite.offset * TRACK_WIDTH * WIDTH/2);
                let spriteY = segment.p1.screen.y;
                
                if (sprite.isFlagGuy) {
                    let wave = Math.sin(Date.now() * 0.01) * 15;
                    Render.sprite(ctx, WIDTH, HEIGHT, RESOLUTION, TRACK_WIDTH, sprite.source, spriteScale, spriteX + wave, spriteY, -0.5, -1, segment.clip);
                } else {
                    Render.sprite(ctx, WIDTH, HEIGHT, RESOLUTION, TRACK_WIDTH, sprite.source, spriteScale, spriteX, spriteY, -0.5, -1, segment.clip);
                }
            }

            for(let i=0; i<segment.cars.length; i++) {
                let car = segment.cars[i];
                let spriteScale = Util.interpolate(segment.p1.screen.scale, segment.p2.screen.scale, 0.5); 
                let spriteX = Util.interpolate(segment.p1.screen.x, segment.p2.screen.x, 0.5) + (spriteScale * car.offset * TRACK_WIDTH * WIDTH/2);
                let spriteY = Util.interpolate(segment.p1.screen.y, segment.p2.screen.y, 0.5);
                
                // Salto visual dos carros da IA nas rampas com sombra no solo
                if (car.isAirborne && car.jumpY > 0) {
                    ctx.save();
                    ctx.fillStyle = 'rgba(0, 0, 0, 0.42)';
                    ctx.beginPath();
                    ctx.ellipse(spriteX, spriteY, Math.max(8, 24 * spriteScale * 14), Math.max(3, 6 * spriteScale * 14), 0, 0, Math.PI * 2);
                    ctx.fill();
                    ctx.restore();
                    spriteY -= car.jumpY * spriteScale * 0.85;
                }

                if (weather === 'RAIN' && car.speed > 50 && Math.random() < 0.4) {
                    sprayParticles.push({
                        x: spriteX + (Math.random() - 0.5) * 30 * spriteScale * 20,
                        y: spriteY - 5,
                        vx: (Math.random() - 0.5) * 20,
                        vy: -10 - Math.random() * 15,
                        size: 3 + Math.random() * 8 * spriteScale * 10,
                        alpha: 0.6
                    });
                }

                if (car.isDrifting && weather !== 'RAIN' && Math.random() < 0.45) {
                    let isRallyStg = currentSeries === 'RALLY' || (STAGES[currentStage] && STAGES[currentStage].theme && STAGES[currentStage].theme.startsWith('RALLY'));
                    let smokeCol = isRallyStg ? 'rgba(150, 95, 45, ' : 'rgba(200, 200, 200, ';
                    tireSmokeParticles.push({
                        x: spriteX + (Math.random() - 0.5) * 20,
                        y: spriteY - 10,
                        life: 0.8,
                        vx: (Math.random() - 0.5) * 30,
                        vy: -15 - Math.random() * 15,
                        size: 4 + Math.random() * 8,
                        colorBase: smokeCol,
                        isOffRoad: false
                    });
                }

                Render.sprite(ctx, WIDTH, HEIGHT, RESOLUTION, TRACK_WIDTH, car.sprite, spriteScale, spriteX, spriteY, -0.5, -1, segment.clip);
            }

            // Desenho 3D do Carro Sombra (Ghost) no Modo Treino
            if (isTrainingMode && ghostData.active) {
                let ghostSeg = findSegment(ghostData.ghostZ);
                if (segment.index === ghostSeg.index) {
                    let spriteScale = Util.interpolate(ghostSeg.p1.screen.scale, ghostSeg.p2.screen.scale, 0.5);
                    let spriteX = Util.interpolate(ghostSeg.p1.screen.x, ghostSeg.p2.screen.x, 0.5) + (spriteScale * ghostData.ghostOffset * TRACK_WIDTH * WIDTH / 2);
                    let spriteY = Util.interpolate(ghostSeg.p1.screen.y, ghostSeg.p2.screen.y, 0.5);

                    let ghostSprite = SPRITES.PLAYER_STRAIGHT;
                    if (ghostData.ghostSlideX < -0.02) ghostSprite = SPRITES.PLAYER_LEFT;
                    else if (ghostData.ghostSlideX > 0.02) ghostSprite = SPRITES.PLAYER_RIGHT;

                    ctx.save();
                    ctx.globalAlpha = 0.50;
                    ctx.shadowColor = '#00ffcc';
                    ctx.shadowBlur = 12;
                    Render.sprite(ctx, WIDTH, HEIGHT, RESOLUTION, TRACK_WIDTH, ghostSprite, spriteScale, spriteX, spriteY, -0.5, -1, ghostSeg.clip);
                    ctx.restore();
                }
            }
        }
        
        if (state !== 'CUTSCENE') {
            let playerSprite = SPRITES.PLAYER_STRAIGHT;
            let bounce = (1.5 * Math.random() * (speed / MAX_SPEED) * RESOLUTION) * Util.randomChoice([-1, 1]);
            
            if (slideX < -0.02 || keyLeft) playerSprite = SPRITES.PLAYER_LEFT;
            else if (slideX > 0.02 || keyRight) playerSprite = SPRITES.PLAYER_RIGHT;

            let playerScale = CAMERA_DEPTH / PLAYER_Z;
            let slideScreenOffset = slideX * WIDTH * 0.8; 
            let pitScreenShift = inPitLane ? (playerX - 0.5) * (WIDTH * 0.42) : 0;
            let playerScreenX = (WIDTH / 2) + slideScreenOffset + pitScreenShift;
            let playerScreenY = HEIGHT - 5 + bounce;

            // Salto Aéreo do Jogador nas Rampas de Terra com Sombra no Chão
            if (playerAirborne && playerJumpY > 0) {
                let jumpScreenOffset = playerJumpY * 0.42;
                ctx.save();
                ctx.fillStyle = 'rgba(0, 0, 0, 0.45)';
                let shadowScale = Math.max(0.45, 1 - (playerJumpY / 500));
                ctx.beginPath();
                ctx.ellipse(playerScreenX, playerScreenY - 6, 48 * shadowScale, 12 * shadowScale, 0, 0, Math.PI * 2);
                ctx.fill();
                ctx.restore();
                playerScreenY -= jumpScreenOffset;
            }

            if (weather === 'RAIN' && speed > 80) {
                for (let k = 0; k < 2; k++) {
                    sprayParticles.push({
                        x: playerScreenX + (k === 0 ? -35 : 35) + (Math.random()-0.5)*15,
                        y: playerScreenY - 10,
                        vx: -slideX * 80 + (Math.random() - 0.5) * 40,
                        vy: -20 - Math.random() * 30,
                        size: 6 + Math.random() * 14,
                        alpha: 0.7
                    });
                }
            }

            Render.sprite(ctx, WIDTH, HEIGHT, RESOLUTION, TRACK_WIDTH, playerSprite, playerScale, playerScreenX, playerScreenY + (state === 'PIT_STOP' && pitTimer > 0.6 && pitTimer < 2.6 ? -12 : 0), -0.5, -1, HEIGHT);

            // ANIMAÇÃO PROCEDURAL AVANÇADA DA EQUIPE DE MECÂNICOS DO PIT STOP
            if (state === 'PIT_STOP') {
                ctx.save();
                let pX = playerScreenX;
                let pY = playerScreenY - 10;
                let isJacked = pitTimer > 0.4 && (!pitServiceComplete || pitTimer < 2.8);
                let jackOffset = isJacked ? -16 : 0;
                let crewSpread = (pitTimer < 0.5) ? Util.interpolate(220, 60, pitTimer / 0.5) : 60;

                // 1. Sombra elevada do carro quando no macaco
                if (isJacked) {
                    ctx.fillStyle = 'rgba(0, 0, 0, 0.28)';
                    ctx.beginPath();
                    ctx.ellipse(pX, pY + 22, 60, 10, 0, 0, Math.PI * 2);
                    ctx.fill();
                }

                // 2. Macaco Hidráulico Dianteiro e Traseiro (Front & Rear Jacks)
                ctx.fillStyle = '#ffcc00';
                ctx.fillRect(pX - 70, pY + 12 + jackOffset, 140, 7);
                ctx.fillStyle = '#333333';
                ctx.fillRect(pX - 6, pY + 15, 12, 18);
                // Braço de alavanca do macaco dianteiro
                ctx.strokeStyle = '#e10600';
                ctx.lineWidth = 4;
                ctx.beginPath();
                ctx.moveTo(pX - 65, pY + 15 + jackOffset);
                ctx.lineTo(pX - crewSpread - 12, pY - 5 + jackOffset);
                ctx.stroke();

                // 3. Mecânico 1: Operador do Macaco Dianteiro (Front Jack Man)
                ctx.fillStyle = '#0055ff'; ctx.fillRect(pX - crewSpread - 16, pY - 24 + jackOffset, 20, 32);
                ctx.fillStyle = '#ffffff'; ctx.beginPath(); ctx.arc(pX - crewSpread - 6, pY - 30 + jackOffset, 8, 0, Math.PI * 2); ctx.fill();
                ctx.fillStyle = '#ffcc00'; ctx.fillRect(pX - crewSpread - 12, pY - 33 + jackOffset, 12, 4); // Viseira do capacete

                // 4. Mecânico 2: Operador do Macaco Traseiro (Rear Jack Man)
                ctx.fillStyle = '#0055ff'; ctx.fillRect(pX + crewSpread - 6, pY - 24 + jackOffset, 20, 32);
                ctx.fillStyle = '#ffffff'; ctx.beginPath(); ctx.arc(pX + crewSpread + 4, pY - 30 + jackOffset, 8, 0, Math.PI * 2); ctx.fill();
                ctx.fillStyle = '#ffcc00'; ctx.fillRect(pX + crewSpread, pY - 33 + jackOffset, 12, 4);

                // 5. Mecânicos Trocadores de Pneus (Esquerda e Direita)
                let tireSwapPhase = pitTimer > 1.4; // Pneu velho sai e novo entra
                let oldTireOffset = pitTimer > 0.8 && pitTimer <= 1.4 ? (pitTimer - 0.8) * 35 : 0;
                let newTireOffset = pitTimer > 1.4 && pitTimer <= 2.2 ? (2.2 - pitTimer) * 35 : 0;

                // Trocador Roda Dianteira Esquerda
                ctx.fillStyle = '#10b981'; 
                ctx.fillRect(pX - crewSpread * 0.7 - 10, pY - 36 + jackOffset, 18, 28);
                ctx.fillStyle = '#ffffff'; ctx.beginPath(); ctx.arc(pX - crewSpread * 0.7 - 1, pY - 42 + jackOffset, 7, 0, Math.PI * 2); ctx.fill();

                // Trocador Roda Traseira Esquerda
                ctx.fillStyle = '#10b981';
                ctx.fillRect(pX - crewSpread * 0.35 - 10, pY - 36 + jackOffset, 18, 28);
                ctx.fillStyle = '#ffffff'; ctx.beginPath(); ctx.arc(pX - crewSpread * 0.35 - 1, pY - 42 + jackOffset, 7, 0, Math.PI * 2); ctx.fill();

                // Trocador Roda Dianteira Direita
                ctx.fillStyle = '#10b981';
                ctx.fillRect(pX + crewSpread * 0.7 - 8, pY - 36 + jackOffset, 18, 28);
                ctx.fillStyle = '#ffffff'; ctx.beginPath(); ctx.arc(pX + crewSpread * 0.7 + 1, pY - 42 + jackOffset, 7, 0, Math.PI * 2); ctx.fill();

                // Trocador Roda Traseira Direita
                ctx.fillStyle = '#10b981';
                ctx.fillRect(pX + crewSpread * 0.35 - 8, pY - 36 + jackOffset, 18, 28);
                ctx.fillStyle = '#ffffff'; ctx.beginPath(); ctx.arc(pX + crewSpread * 0.35 + 1, pY - 42 + jackOffset, 7, 0, Math.PI * 2); ctx.fill();

                // Pneus Sendo Trocados (Animação de saída de pneu desgastado e entrada de pneu novo brilhante)
                if (pitTimer > 0.5 && !pitServiceComplete) {
                    ctx.fillStyle = '#111111';
                    // Pneus velhos sendo retirados
                    if (!tireSwapPhase) {
                        ctx.fillRect(pX - 58 - oldTireOffset, pY - 14 + jackOffset, 14, 22);
                        ctx.fillRect(pX + 44 + oldTireOffset, pY - 14 + jackOffset, 14, 22);
                    } else {
                        // Novos pneus novos de alta aderência sendo parafusados (faixa amarela macia)
                        ctx.fillRect(pX - 58 - newTireOffset, pY - 14 + jackOffset, 14, 22);
                        ctx.fillRect(pX + 44 + newTireOffset, pY - 14 + jackOffset, 14, 22);
                        ctx.fillStyle = '#ffcc00';
                        ctx.fillRect(pX - 58 - newTireOffset, pY - 8 + jackOffset, 14, 4);
                        ctx.fillRect(pX + 44 + newTireOffset, pY - 8 + jackOffset, 14, 4);
                    }
                }

                // 6. Faíscas da Parafusadeira Pneumática High-RPM
                if (pitTimer > 0.5 && !pitServiceComplete) {
                    createSparks(pX - 48, pY - 8 + jackOffset, 3);
                    createSparks(pX + 48, pY - 8 + jackOffset, 3);
                    createSparks(pX - 32, pY - 8 + jackOffset, 2);
                    createSparks(pX + 32, pY - 8 + jackOffset, 2);
                }

                // 7. Placa de Pirulito do Chefe de Equipe (Lollipop Man)
                let lollipopY = pY - 88 + jackOffset;
                ctx.fillStyle = '#475569';
                ctx.fillRect(pX - 95, lollipopY, 6, 80);
                let isGo = pitServiceComplete;
                ctx.fillStyle = isGo ? '#22c55e' : '#ef4444';
                ctx.beginPath();
                ctx.arc(pX - 92, lollipopY, 18, 0, Math.PI * 2);
                ctx.fill();
                ctx.strokeStyle = '#ffffff';
                ctx.lineWidth = 2;
                ctx.stroke();
                ctx.fillStyle = '#ffffff';
                ctx.font = 'bold 8px "Press Start 2P"';
                ctx.fillText(isGo ? "GO!" : "STOP", pX - 108, lollipopY + 3);

                // 8. Painel Holográfico de Manutenção (Troca de Pneus + Reabastecimento)
                let displayPitTime = Math.min(pitTimer, 3.0).toFixed(2);
                let pPercent = Math.min(100, Math.round((pitTimer / 2.8) * 100));
                
                ctx.fillStyle = 'rgba(3, 6, 16, 0.92)';
                ctx.fillRect(pX - 130, pY - 115, 260, 42);
                ctx.strokeStyle = isGo ? '#22c55e' : '#00e676';
                ctx.lineWidth = 2;
                ctx.strokeRect(pX - 130, pY - 115, 260, 42);

                // Título e Cronômetro
                ctx.fillStyle = isGo ? '#22c55e' : '#ffd700';
                ctx.font = '8px "Press Start 2P"';
                ctx.fillText(isGo ? "⚡ PRONTO! [ESPAÇO] ACELERAR" : `PIT STOP: ${displayPitTime}s (${pPercent}%)`, pX - 120, pY - 100);

                // Indicador 1: Troca de Pneus (Tires 4x)
                let tiresDone = pitTimer > 1.8;
                ctx.fillStyle = tiresDone ? '#22c55e' : '#38bdf8';
                ctx.font = '7px sans-serif';
                ctx.fillText(tiresDone ? "✓ 4x PNEUS NOVOS" : "⚡ TROCANDO 4 PNEUS...", pX - 120, pY - 88);

                // Indicador 2: Barra de Combustível / Reparo
                ctx.fillStyle = '#1e293b';
                ctx.fillRect(pX - 120, pY - 82, 240, 5);
                let fillW = Math.min(240, (pPercent / 100) * 240);
                ctx.fillStyle = isGo ? '#22c55e' : '#00e676';
                ctx.fillRect(pX - 120, pY - 82, fillW, 5);

                ctx.restore();
            }
        }

        drawTireSmoke();
        drawSprayParticles();
        drawSparks();
        if (state === 'RACING') {
            drawMinimap();
            drawSpeedLines();
        }
        drawWeatherEffects();

        // Chamas azuis do escapamento: efeito Canvas independente da física da pista.
        if (state === 'RACING' && nitroActiveTime > 0) {
            const exhaustX = WIDTH / 2 + slideX * WIDTH * 1.25;
            const exhaustY = HEIGHT - 17;
            ctx.save();
            ctx.globalCompositeOperation = 'lighter';
            for (let side = -1; side <= 1; side += 2) {
                const flicker = 0.75 + Math.random() * 0.45;
                const flameX = exhaustX + side * 17;
                const flameH = 18 * flicker;
                const flame = ctx.createLinearGradient(0, exhaustY - flameH, 0, exhaustY + 3);
                flame.addColorStop(0, 'rgba(224,247,255,0.95)');
                flame.addColorStop(0.35, 'rgba(56,189,248,0.95)');
                flame.addColorStop(1, 'rgba(2,132,199,0)');
                ctx.fillStyle = flame; ctx.shadowColor = '#38bdf8'; ctx.shadowBlur = 16;
                ctx.beginPath();
                ctx.moveTo(flameX - 5, exhaustY - 2);
                ctx.quadraticCurveTo(flameX - 8, exhaustY - flameH * .65, flameX, exhaustY - flameH);
                ctx.quadraticCurveTo(flameX + 8, exhaustY - flameH * .65, flameX + 5, exhaustY - 2);
                ctx.closePath(); ctx.fill();
            }
            ctx.restore();
        }

        if (lightningAlpha > 0) {
            ctx.fillStyle = `rgba(255, 255, 255, ${lightningAlpha})`;
            ctx.fillRect(0, 0, WIDTH, HEIGHT);
            lightningAlpha -= STEP * 2;
        }

        if (cinematicBarHeight > 0) {
            ctx.fillStyle = '#000';
            ctx.fillRect(0, 0, WIDTH, cinematicBarHeight);
            ctx.fillRect(0, HEIGHT - cinematicBarHeight, WIDTH, cinematicBarHeight);
        }

        drawVictoryCelebration(ctx);
        ctx.restore();
    }

    function updateTireSmoke(dt, speedPercent) {
        let isOffRoad = playerX < -1 || playerX > 1;
        let stg = STAGES[currentStage];
        let isRallyMode = currentSeries === 'RALLY' || (stg && stg.theme && stg.theme.startsWith('RALLY'));
        
        if ((isDrifting && speedPercent > (isRallyMode ? 0.25 : 0.5) && weather !== 'RAIN') || (isOffRoad && speedPercent > 0.2) || (isRallyMode && keyFaster && speedPercent > 0.4)) {
            if (Math.random() > (isOffRoad ? 0.1 : (isRallyMode ? 0.15 : 0.3))) {
                let playerScreenX = WIDTH / 2 + (slideX * WIDTH * 1.5);
                let playerScreenY = HEIGHT - 15;
                let offset = slideX < 0 ? 30 : -30; 
                let pColor = isOffRoad ? (weather === 'RAIN' ? 'rgba(46, 87, 48, 0.8)' : 'rgba(107, 102, 48, 0.8)') : 
                             (isRallyMode ? (weather === 'RAIN' ? 'rgba(70, 48, 30, ' : (weather === 'SUNSET' ? 'rgba(180, 105, 45, ' : 'rgba(150, 95, 45, ')) : 'rgba(200, 200, 200, ');
                
                tireSmokeParticles.push({
                    x: playerScreenX + offset + (Math.random()-0.5)*20, 
                    y: playerScreenY, 
                    life: 1.0,
                    vx: -slideX * 100 + (Math.random() - 0.5) * 30, 
                    vy: -20 - Math.random() * 20, 
                    size: 5 + Math.random() * (isOffRoad || isRallyMode ? 15 : 10),
                    colorBase: pColor,
                    isOffRoad: isOffRoad
                });
            }
        }

                if (pitLaunchAnimation > 0) {
            pitLaunchAnimation -= dt;
            let playerScreenX = WIDTH / 2 + (slideX * WIDTH * 1.5);
            let playerScreenY = HEIGHT - 15;
            for (let k = 0; k < 2; k++) {
                tireSmokeParticles.push({
                    x: playerScreenX + (k === 0 ? -35 : 35) + (Math.random() - 0.5) * 12,
                    y: playerScreenY,
                    life: 0.8,
                    vx: (k === 0 ? -25 : 25) + (Math.random() - 0.5) * 20,
                    vy: -15 - Math.random() * 25,
                    size: 6 + Math.random() * 10,
                    colorBase: 'rgba(210, 210, 210, ',
                    isOffRoad: false
                });
            }
        }

        for (let i = tireSmokeParticles.length - 1; i >= 0; i--) {
            let p = tireSmokeParticles[i];
            p.x += p.vx * dt; p.y += p.vy * dt; p.size += dt * 30; p.life -= dt * 2;  
            if (p.life <= 0) tireSmokeParticles.splice(i, 1);
        }

        for (let i = sprayParticles.length - 1; i >= 0; i--) {
            let sp = sprayParticles[i];
            sp.x += sp.vx * dt;
            sp.y += sp.vy * dt;
            sp.size += dt * 25;
            sp.alpha -= dt * 1.8;
            if (sp.alpha <= 0) sprayParticles.splice(i, 1);
        }
    }

    function drawTireSmoke() {
        if (tireSmokeParticles.length === 0) return;
        ctx.save();
        for (let i = 0; i < tireSmokeParticles.length; i++) {
            let p = tireSmokeParticles[i];
            if (p.isOffRoad) {
                ctx.fillStyle = p.colorBase; 
                ctx.globalAlpha = p.life;
            } else {
                ctx.fillStyle = p.colorBase + (p.life * 0.5) + ')';
                ctx.globalAlpha = 1.0;
            }
            ctx.beginPath(); ctx.arc(p.x, p.y, p.size, 0, Math.PI * 2); ctx.fill();
        }
        ctx.restore();
    }

    function drawSprayParticles() {
        if (sprayParticles.length === 0) return;
        ctx.save();
        for (let i = 0; i < sprayParticles.length; i++) {
            let sp = sprayParticles[i];
            ctx.fillStyle = 'rgba(210, 230, 255, ' + sp.alpha + ')';
            ctx.beginPath();
            ctx.arc(sp.x, sp.y, sp.size, 0, Math.PI * 2);
            ctx.fill();
        }
        ctx.restore();
    }

    function drawWeatherEffects() {
        if (weather !== 'RAIN') return;

        lightningTimer += STEP;
        if (lightningTimer > 5 + Math.random() * 8) {
            lightningAlpha = 0.8;
            lightningTimer = 0;
        }

        ctx.strokeStyle = 'rgba(210, 235, 255, 0.6)'; 
        let speedPercent = speed / MAX_SPEED;

        for (let i = 0; i < rainParticles.length; i++) {
            let p = rainParticles[i];
            ctx.lineWidth = p.thickness;
            ctx.beginPath();
            ctx.moveTo(p.x, p.y);
            let turnOffset = keyLeft ? 8 : (keyRight ? -8 : 0);
            ctx.lineTo(p.x + p.speedX - turnOffset, p.y + p.length + (speedPercent * 20));
            ctx.stroke();

            p.x += p.speedX - (turnOffset * speedPercent);
            p.y += p.speedY + (speedPercent * 30);

            if (p.y > HEIGHT) {
                if (Math.random() < 0.2) {
                    ctx.fillStyle = 'rgba(255,255,255,0.4)';
                    ctx.fillRect(p.x - 2, HEIGHT - Math.random() * 20, 4, 1);
                }
                p.y = -20; p.x = Math.random() * WIDTH; 
            }
            if (p.x > WIDTH) p.x = 0; if (p.x < 0) p.x = WIDTH;
        }
    }

    const Render = {
        polygon: function(ctx, x1, y1, x2, y2, x3, y3, x4, y4, color) {
            ctx.fillStyle = color; ctx.beginPath();
            ctx.moveTo(x1, y1); ctx.lineTo(x2, y2); ctx.lineTo(x3, y3); ctx.lineTo(x4, y4);
            ctx.closePath(); ctx.fill();
        },
        segment: function(ctx, width, lanes, x1, y1, w1, x2, y2, w2, fog, color, index, isNascar, isRally, isRamp) {
            let r1 = Render.rumbleWidth(w1, lanes), r2 = Render.rumbleWidth(w2, lanes);
            let l1 = Render.laneMarkerWidth(w1, lanes), l2 = Render.laneMarkerWidth(w2, lanes);
            let lanew1, lanew2, lanex1, lanex2, lane;
            
            ctx.fillStyle = color.grass; ctx.fillRect(0, y2, width, y1 - y2);
            
            Render.polygon(ctx, x1-w1-r1, y1, x1-w1, y1, x2-w2, y2, x2-w2-r2, y2, color.rumble);
            Render.polygon(ctx, x1+w1+r1, y1, x1+w1, y1, x2+w2, y2, x2+w2+r2, y2, color.rumble);
            Render.polygon(ctx, x1-w1, y1, x1+w1, y1, x2+w2, y2, x2-w2, y2, color.road);

            // VIA PARALELA PIT LANE SEPARADA POR MURETA E LINHA CONTÍNUA
            if (!isRally && (index >= 8 && index <= 46)) {
                let pitWidth1 = w1 * 0.48, pitWidth2 = w2 * 0.48;
                let pitStartX1 = x1 + w1 + r1, pitStartX2 = x2 + w2 + r2;
                let pitEndX1 = pitStartX1 + pitWidth1, pitEndX2 = pitStartX2 + pitWidth2;
                
                // Asfalto do Pit Lane (tonalidade límpida de box)
                let pitColor = (index % 2 === 0) ? '#1f242d' : '#191d24';
                Render.polygon(ctx, pitStartX1, y1, pitEndX1, y1, pitEndX2, y2, pitStartX2, y2, pitColor);

                // Linha de Limite de Velocidade / Demarcação Branca contínua
                let lineW1 = Math.max(1, w1 * 0.02), lineW2 = Math.max(1, w2 * 0.02);
                Render.polygon(ctx, pitStartX1, y1, pitStartX1 + lineW1, y1, pitStartX2 + lineW2, y2, pitStartX2, y2, '#ffffff');

                // Mureta de Concreto / Armco separando a pista principal da via de box (segmentos 14 a 42)
                if (index >= 14 && index <= 42) {
                    let wallH1 = Math.max(4, w1 * 0.09), wallH2 = Math.max(4, w2 * 0.09);
                    let wallColor = (Math.floor(index / 2) % 2 === 0) ? '#e2e8f0' : '#3b82f6';
                    // Face frontal da mureta
                    Render.polygon(ctx, pitStartX1 - lineW1, y1, pitStartX1 - lineW1, y1 - wallH1, pitStartX2 - lineW2, y2 - wallH2, pitStartX2 - lineW2, y2, wallColor);
                    // Topo da mureta
                    Render.polygon(ctx, pitStartX1 - lineW1, y1 - wallH1, pitStartX1 + lineW1, y1 - wallH1, pitStartX2 + lineW2, y2 - wallH2, pitStartX2 - lineW2, y2 - wallH2, '#94a3b8');
                } else if (index >= 8 && index <= 13) {
                    // Ramificação / Entrada do Pit Lane: Linhas tracejadas diagonais amarelas
                    if (index % 2 === 0) {
                        Render.polygon(ctx, pitStartX1, y1, pitStartX1 + (pitWidth1 * 0.25), y1, pitStartX2 + (pitWidth2 * 0.25), y2, pitStartX2, y2, '#ffcc00');
                    }
                }
            }
            
            if (color.type === 'START' || color.type === 'FINISH') {
                let cbLanes = 12; 
                for (let i = 0; i < cbLanes; i++) {
                    let isWhite = (i + (index || 0)) % 2 === 0;
                    let col = isWhite ? '#ffffff' : '#111111';
                    let startX1 = (x1-w1) + (w1 * 2 / cbLanes) * i, endX1 = (x1-w1) + (w1 * 2 / cbLanes) * (i + 1);
                    let startX2 = (x2-w2) + (w2 * 2 / cbLanes) * i, endX2 = (x2-w2) + (w2 * 2 / cbLanes) * (i + 1);
                    Render.polygon(ctx, startX1, y1, endX1, y1, endX2, y2, startX2, y2, col);
                }
            } else if (isRally) {
                // Sulcos de terra batida (Dirt Wheel Ruts) cavados na terra
                let rutW1 = w1 * 0.16, rutW2 = w2 * 0.16;
                let leftRutX1 = x1 - w1 * 0.45, leftRutX2 = x2 - w2 * 0.45;
                let rightRutX1 = x1 + w1 * 0.45, rightRutX2 = x2 + w2 * 0.45;
                let rutColor = (index % 2 === 0) ? 'rgba(0, 0, 0, 0.18)' : 'rgba(0, 0, 0, 0.10)';
                Render.polygon(ctx, leftRutX1 - rutW1/2, y1, leftRutX1 + rutW1/2, y1, leftRutX2 + rutW2/2, y2, leftRutX2 - rutW2/2, y2, rutColor);
                Render.polygon(ctx, rightRutX1 - rutW1/2, y1, rightRutX1 + rutW1/2, y1, rightRutX2 + rutW2/2, y2, rightRutX2 - rutW2/2, y2, rutColor);

                // Se for rampa de terra, renderiza a face e os marcadores de salto
                if (isRamp) {
                    Render.rallyRamp(ctx, x1, y1, w1, x2, y2, w2, index);
                }
            } else if (color.lane) {
                lanew1 = w1*2/lanes; lanew2 = w2*2/lanes;
                lanex1 = x1 - w1 + lanew1; lanex2 = x2 - w2 + lanew2;
                for(lane = 1 ; lane < lanes ; lanex1 += lanew1, lanex2 += lanew2, lane++)
                    Render.polygon(ctx, lanex1 - l1/2, y1, lanex1 + l1/2, y1, lanex2 + l2/2, y2, lanex2 - l2/2, y2, color.lane);
            }

            // === ARQUIBANCADA 3D PROCEDURAL CONTÍNUA NASCAR ===
            if (isNascar) {
                Render.nascar3DGrandstands(ctx, x1, y1, w1, x2, y2, w2, fog, index);
            }

            Render.fog(ctx, 0, y2, width, y1-y2, fog); 
        },
        rallyRamp: function(ctx, x1, y1, w1, x2, y2, w2, index) {
            // Sombra e elevação de terra da rampa de salto
            Render.polygon(ctx, x1 - w1 * 0.95, y1, x1 + w1 * 0.95, y1, x2 + w2 * 0.95, y2, x2 - w2 * 0.95, y2, 'rgba(0, 0, 0, 0.22)');
            // Faixas Chevron de rampa de salto
            let numArrows = 4;
            let rampCol = (index % 2 === 0) ? '#f59e0b' : '#b45309';
            for (let a = 0; a < numArrows; a++) {
                let ax1 = x1 - w1 * 0.65 + (w1 * 1.3 / numArrows) * (a + 0.5);
                let ax2 = x2 - w2 * 0.65 + (w2 * 1.3 / numArrows) * (a + 0.5);
                let aw1 = w1 * 0.10, aw2 = w2 * 0.10;
                Render.polygon(ctx, ax1 - aw1, y1, ax1 + aw1, y1, ax2 + aw2, y2, ax2 - aw2, y2, rampCol);
            }
            // Taludes laterais de terra compactada
            let kh1 = Math.max(3, w1 * 0.06), kh2 = Math.max(3, w2 * 0.06);
            Render.polygon(ctx, x1 - w1, y1, x1 - w1 * 1.08, y1 - kh1, x2 - w2 * 1.08, y2 - kh2, x2 - w2, y2, '#78350f');
            Render.polygon(ctx, x1 + w1, y1, x1 + w1 * 1.08, y1 - kh1, x2 + w2 * 1.08, y2 - kh2, x2 + w2, y2, '#78350f');
        },
        nascar3DGrandstands: function(ctx, x1, y1, w1, x2, y2, w2, fog, index) {
            let r1 = Render.rumbleWidth(w1, LANES), r2 = Render.rumbleWidth(w2, LANES);
            
            // 1. Asfalto da Área de Escape (Apron)
            let ap1 = w1 + r1, ap2 = w2 + r2;
            let apW1 = w1 * 0.28, apW2 = w2 * 0.28;
            Render.polygon(ctx, x1 - ap1, y1, x1 - ap1 - apW1, y1, x2 - ap2 - apW2, y2, x2 - ap2, y2, '#242831');

            // 2. Mureta SAFER Barrier 3D
            let wallBaseX1 = x1 - ap1 - apW1, wallBaseX2 = x2 - ap2 - apW2;
            let wallH1 = Math.max(3, w1 * 0.08), wallH2 = Math.max(3, w2 * 0.08);
            let wallColor = (Math.floor(index / 4) % 2 === 0) ? '#f8fafc' : '#dc2626';
            Render.polygon(ctx, wallBaseX1, y1, wallBaseX1, y1 - wallH1, wallBaseX2, y2 - wallH2, wallBaseX2, y2, wallColor);
            Render.polygon(ctx, wallBaseX1, y1 - wallH1, wallBaseX1 - (w1 * 0.04), y1 - wallH1, wallBaseX2 - (w2 * 0.04), y2 - wallH2, wallBaseX2, y2 - wallH2, '#e2e8f0');

            // 3. Alambrado Catch Fence 3D
            let fenceH1 = w1 * 0.24, fenceH2 = w2 * 0.24;
            ctx.save();
            ctx.fillStyle = 'rgba(148, 163, 184, 0.28)';
            ctx.beginPath();
            ctx.moveTo(wallBaseX1, y1 - wallH1);
            ctx.lineTo(wallBaseX1 - (w1 * 0.04), y1 - fenceH1);
            ctx.lineTo(wallBaseX2 - (w2 * 0.04), y2 - fenceH2);
            ctx.lineTo(wallBaseX2, y2 - wallH2);
            ctx.closePath();
            ctx.fill();
            ctx.restore();

            // 4. Arquibancada 3D Multinível
            let gsBaseX1 = wallBaseX1 - (w1 * 0.08), gsBaseX2 = wallBaseX2 - (w2 * 0.08);
            
            // Tier 1: Nível Inferior com Torcida Vibrante
            let t1X1 = gsBaseX1 - (w1 * 0.40), t1Y1 = y1 - (w1 * 0.28);
            let t1X2 = gsBaseX2 - (w2 * 0.40), t1Y2 = y2 - (w2 * 0.28);
            let crowdCol1 = ['#e11d48', '#2563eb', '#f59e0b', '#ffffff', '#10b981'][(index + 1) % 5];
            Render.polygon(ctx, gsBaseX1, y1 - wallH1, t1X1, t1Y1, t1X2, t1Y2, gsBaseX2, y2 - wallH2, '#1e293b');
            Render.polygon(ctx, gsBaseX1 - (w1 * 0.04), y1 - wallH1 - (w1 * 0.04), t1X1, t1Y1, t1X2, t1Y2, gsBaseX2 - (w2 * 0.04), y2 - wallH2 - (w2 * 0.04), crowdCol1);

            // Tier 2: Painel LED de Patrocinadores
            let t2X1 = t1X1 - (w1 * 0.15), t2Y1 = t1Y1 - (w1 * 0.10);
            let t2X2 = t1X2 - (w2 * 0.15), t2Y2 = t1Y2 - (w2 * 0.10);
            let ledCol = (Math.floor(index / 6) % 2 === 0) ? '#ffcc00' : '#00e5ff';
            Render.polygon(ctx, t1X1, t1Y1, t2X1, t2Y1, t2X2, t2Y2, t1X2, t1Y2, '#090d16');
            Render.polygon(ctx, t1X1, t1Y1 - 1, t2X1, t2Y1 + 1, t2X2, t2Y2 + 1, t1X2, t1Y2 - 1, ledCol);

            // Tier 3: Nível Superior com Torcida
            let t3X1 = t2X1 - (w1 * 0.45), t3Y1 = t2Y1 - (w1 * 0.32);
            let t3X2 = t2X2 - (w2 * 0.45), t3Y2 = t2Y2 - (w2 * 0.32);
            let crowdCol2 = ['#3b82f6', '#ef4444', '#ffffff', '#eab308'][(index + 3) % 4];
            Render.polygon(ctx, t2X1, t2Y1, t3X1, t3Y1, t3X2, t3Y2, t2X2, t2Y2, '#1e293b');
            Render.polygon(ctx, t2X1 - (w1 * 0.04), t2Y1 - (w1 * 0.04), t3X1, t3Y1, t3X2, t3Y2, t2X2 - (w2 * 0.04), t2Y2 - (w2 * 0.04), crowdCol2);

            // Tier 4: Camarotes VIP de Vidro Iluminados
            let suiteX1 = t3X1 - (w1 * 0.18), suiteY1 = t3Y1 - (w1 * 0.14);
            let suiteX2 = t3X2 - (w2 * 0.18), suiteY2 = t3Y2 - (w2 * 0.14);
            Render.polygon(ctx, t3X1, t3Y1, suiteX1, suiteY1, suiteX2, suiteY2, t3X2, t3Y2, '#0284c7');
            Render.polygon(ctx, t3X1 - 2, t3Y1 - 2, suiteX1 + 2, suiteY1 + 2, suiteX2 + 2, suiteY2 + 2, t3X2 - 2, t3Y2 - 2, 'rgba(254, 240, 138, 0.7)');

            // Marquise do Topo com Friso Vermelho
            let roofX1 = suiteX1 + (w1 * 0.30), roofY1 = suiteY1 - (w1 * 0.07);
            let roofX2 = suiteX2 + (w2 * 0.30), roofY2 = suiteY2 - (w2 * 0.07);
            Render.polygon(ctx, suiteX1, suiteY1, roofX1, roofY1, roofX2, roofY2, suiteX2, suiteY2, '#334155');
            Render.polygon(ctx, roofX1, roofY1, roofX1, roofY1 - 3, roofX2, roofY2 - 3, roofX2, roofY2, '#e10600');
        },
        rumbleWidth:     function(projectedRoadWidth, lanes) { return projectedRoadWidth/Math.max(6,  2*lanes); },
        laneMarkerWidth: function(projectedRoadWidth, lanes) { return projectedRoadWidth/Math.max(32, 8*lanes); },
        fog: function(ctx, x, y, width, height, fog) {
            if (fog < 1) {
                ctx.globalAlpha = (1-fog);
                ctx.fillStyle = COLORS.FOG;
                ctx.fillRect(x, y, width, height);
                ctx.globalAlpha = 1;
            }
        },
        sprite: function(ctx, width, height, resolution, roadWidth, sprite, scale, destX, destY, offsetX, offsetY, clipY) {
            // Usa largura de pista de referência (1350) para que carros e elementos mantenham sua escala realista e nitidez
            const BASE_ROAD_REF = 1350;
            const SPRITE_SCALE_FACTOR = 0.355 / 142;
            
            let destW  = (sprite.w * scale * width/2) * (SPRITE_SCALE_FACTOR * BASE_ROAD_REF);
            let destH  = (sprite.h * scale * width/2) * (SPRITE_SCALE_FACTOR * BASE_ROAD_REF);
            destX = destX + (destW * (offsetX || 0)); destY = destY + (destH * (offsetY || 0));
            let clipH = clipY ? Math.max(0, destY+destH-clipY) : 0;
            if (clipH < destH) {
                ctx.drawImage(spriteCanvas, sprite.x, sprite.y, sprite.w, sprite.h - (sprite.h*clipH/destH), destX, destY, destW, destH - clipH);
            }
        }
    };

    const Util = {
        easeIn: function(a,b,percent) { return a + (b-a)*Math.pow(percent,2); },
        easeInOut: function(a,b,percent) { return a + (b-a)*((-Math.cos(percent*Math.PI)/2) + 0.5); },
        exponentialFog: function(distance, density) { return 1 / (Math.pow(Math.E, (distance * distance * density))); },
        increase: function(start, increment, max) { 
            let result = start + increment;
            while (result >= max) result -= max; while (result < 0) result += max;
            return result;
        },
        project: function(p, cameraX, cameraY, cameraZ, cameraDepth, width, height, roadWidth) {
            p.camera.x     = (p.world.x || 0) - cameraX; p.camera.y     = (p.world.y || 0) - cameraY; p.camera.z     = (p.world.z || 0) - cameraZ;
            p.screen.scale = cameraDepth/p.camera.z;
            p.screen.x     = Math.round((width/2)  + (p.screen.scale * p.camera.x  * width/2));
            p.screen.y     = Math.round((height/2) - (p.screen.scale * p.camera.y  * height/2));
            p.screen.w     = Math.round(             (p.screen.scale * roadWidth   * width/2));
        },
        limit: function(value, min, max) { return Math.max(min, Math.min(value, max)); },
        randomChoice: function(arr) { return arr[Math.floor(Math.random() * arr.length)]; },
        interpolate: function(a,b,percent) { return a + (b-a)*percent; },
        percentRemaining: function(n, total) { return (n%total)/total; },
        accelerate: function(v, accel, dt) { return v + (accel * dt); },
        formatTime: function(t) {
            if(t === 0) return "--:--.---";
            let m = Math.floor(t / 60);
            let s = Math.floor(t % 60);
            let ms = Math.floor((t % 1) * 1000);
            return (m<10?'0':'')+m + ":" + (s<10?'0':'')+s + "." + (ms<100?'0':'')+(ms<10?'0':'')+ms;
        }
    };

    function findSegment(z) { return segments[Math.floor(z/SEGMENT_LENGTH) % segments.length]; }

    function updateHUD() {
        let displaySpeed = Math.round((speed/MAX_SPEED) * 320); 
        document.getElementById('speed-info').innerText = displaySpeed + " KM/H";
        if (inSlipstream) {
            document.getElementById('speed-info').style.color = '#ffcc00';
            document.getElementById('speed-info').innerText += " (+)";
        } else {
            document.getElementById('speed-info').style.color = '#fff';
        }
        
        let revPerc = (speed/MAX_SPEED) * 100;
        document.getElementById('rev-fill').style.width = revPerc + "%";
        
        let gear = 'N';
        if(displaySpeed > 280) gear = '7'; else if(displaySpeed > 230) gear = '6';
        else if(displaySpeed > 180) gear = '5'; else if(displaySpeed > 130) gear = '4';
        else if(displaySpeed > 80) gear = '3'; else if(displaySpeed > 30) gear = '2';
        else if(displaySpeed > 0) gear = '1';
        document.getElementById('gear-indicator').innerText = gear;

        let displayLap = Math.max(1, lap);
        if (isTrainingMode) {
            document.getElementById('lap-info').innerText = "VOLTA " + displayLap + " (TREINO)";
            document.getElementById('stage-info').innerText = `${getSeriesLabel()} • TREINO: FASE ${currentStage + 1}`;
            document.getElementById('time-info').innerHTML = "TEMPO: " + Util.formatTime(lapTime) + "<br>SOMBRA: " + Util.formatTime(ghostData.bestTime);
            document.getElementById('pos-info').innerText = "SOLO";
            document.getElementById('pos-info').style.color = '#00ffcc';
        } else {
            document.getElementById('lap-info').innerText = "VOLTA " + Math.min(displayLap, TOTAL_LAPS) + "/" + TOTAL_LAPS;
            document.getElementById('stage-info').innerText = `${getSeriesLabel()} • FASE ${currentStage + 1}/${STAGES.length}`;
            document.getElementById('time-info').innerHTML = "TEMPO: " + Util.formatTime(lapTime) + "<br>MELHOR: " + Util.formatTime(bestLapTime);
            document.getElementById('pos-info').innerText = "POS " + playerPos + "º";
            document.getElementById('pos-info').style.color = playerPos <= 3 ? '#ff0' : '#fff';
        }

        // Barra de Nitro: preenchimento contínuo e estado de carga máxima.
        const nitroHud = document.getElementById('nitro-hud');
        const nitroFill = document.getElementById('nitro-hud-fill');
        const nitroPercent = document.getElementById('nitro-percent');
        const nitroValue = Util.limit(nitroCharge, 0, 100);
        if (nitroFill) nitroFill.style.width = nitroValue.toFixed(1) + '%';
        if (nitroPercent) nitroPercent.innerText = Math.floor(nitroValue) + '%';
        if (nitroHud) {
            const nitroReady = nitroValue >= 99.9;
            nitroHud.classList.toggle('ready', nitroReady);
            nitroHud.classList.toggle('active', nitroActiveTime > 0);
            const readyLabel = document.getElementById('nitro-ready-label');
            if (readyLabel) readyLabel.textContent = nitroReady ? 'PRONTO!' : '';
        }

        // Atualização do medidor de pneus no HUD
        let tireValEl = document.getElementById('tire-val');
        if (tireValEl) {
            let tVal = Math.round(tireHealth);
            tireValEl.innerText = tVal + "%";
            tireValEl.style.color = tVal > 60 ? '#00ff00' : (tVal > 30 ? '#ffcc00' : '#ff0000');
        }
    }

    function drawMinimap() {
        const mCanv = document.getElementById('minimap');
        const mCtx = mCanv.getContext('2d');
        const MW = 120, MH = 120;
        if (mCanv.width !== MW) { mCanv.width = MW; mCanv.height = MH; }

        mCtx.clearRect(0, 0, MW, MH);

        // Se não houver traçado calculado, nada a fazer
        if (minimapPoints.length < 3) return;

        const PAD = 10;
        const { minX, maxX, minY, maxY } = minimapBounds;
        const rangeX = (maxX - minX) || 1;
        const rangeY = (maxY - minY) || 1;
        const scale = Math.min((MW - PAD * 2) / rangeX, (MH - PAD * 2) / rangeY);
        const offX = PAD + (MW - PAD * 2 - rangeX * scale) / 2 - minX * scale;
        const offY = PAD + (MH - PAD * 2 - rangeY * scale) / 2 - minY * scale;

        // Converte coordenada de pista para pixel do minimapa
        function toMapXY(pt) {
            return { x: pt.x * scale + offX, y: pt.y * scale + offY };
        }

        // Função: interpola posição no traçado dado z (0..trackLength)
        function getMapPos(z) {
            let norm = ((z % trackLength) + trackLength) % trackLength;
            // Busca linear no array de pontos
            for (let i = 0; i < minimapPoints.length - 1; i++) {
                let pA = minimapPoints[i], pB = minimapPoints[i + 1];
                let zA = (i / (minimapPoints.length - 1)) * trackLength;
                let zB = ((i + 1) / (minimapPoints.length - 1)) * trackLength;
                if (norm >= zA && norm < zB) {
                    let t = (zB - zA) > 0 ? (norm - zA) / (zB - zA) : 0;
                    return {
                        x: (pA.x + (pB.x - pA.x) * t) * scale + offX,
                        y: (pA.y + (pB.y - pA.y) * t) * scale + offY
                    };
                }
            }
            let last = minimapPoints[minimapPoints.length - 1];
            return { x: last.x * scale + offX, y: last.y * scale + offY };
        }

        // Fundo translúcido arredondado
        mCtx.save();
        mCtx.fillStyle = 'rgba(5, 8, 20, 0.78)';
        mCtx.beginPath();
        mCtx.roundRect(0, 0, MW, MH, 10);
        mCtx.fill();

        // Borda sutil
        mCtx.strokeStyle = 'rgba(255,255,255,0.15)';
        mCtx.lineWidth = 1;
        mCtx.beginPath();
        mCtx.roundRect(0, 0, MW, MH, 10);
        mCtx.stroke();
        mCtx.restore();

        // Recorte arredondado para o conteúdo
        mCtx.save();
        mCtx.beginPath();
        mCtx.roundRect(1, 1, MW - 2, MH - 2, 9);
        mCtx.clip();

        // Desenha sombra/brilho do traçado (linha grossa escura)
        mCtx.beginPath();
        let p0 = toMapXY(minimapPoints[0]);
        mCtx.moveTo(p0.x, p0.y);
        for (let i = 1; i < minimapPoints.length; i++) {
            let pm = toMapXY(minimapPoints[i]);
            mCtx.lineTo(pm.x, pm.y);
        }
        mCtx.closePath();
        mCtx.strokeStyle = 'rgba(0,0,0,0.5)';
        mCtx.lineWidth = 5;
        mCtx.lineJoin = 'round';
        mCtx.stroke();

        // Linha principal do traçado da pista
        mCtx.beginPath();
        mCtx.moveTo(p0.x, p0.y);
        for (let i = 1; i < minimapPoints.length; i++) {
            let pm = toMapXY(minimapPoints[i]);
            mCtx.lineTo(pm.x, pm.y);
        }
        mCtx.closePath();
        mCtx.strokeStyle = 'rgba(160, 160, 170, 0.75)';
        mCtx.lineWidth = 3;
        mCtx.stroke();

        // Linha de largada/chegada em dourado
        let startPos = getMapPos(0);
        mCtx.beginPath();
        mCtx.arc(startPos.x, startPos.y, 3, 0, Math.PI * 2);
        mCtx.fillStyle = '#ffcc00';
        mCtx.fill();

        // Pontos dos carros da IA
        if (!isTrainingMode) {
            mCtx.fillStyle = 'rgba(255, 60, 60, 0.85)';
            for (let i = 0; i < cars.length; i++) {
                if (cars[i].isDummy) continue;
                let aiPos = getMapPos(cars[i].z);
                mCtx.beginPath();
                mCtx.arc(aiPos.x, aiPos.y, 2, 0, Math.PI * 2);
                mCtx.fill();
            }
        }

        // Ponto do Ghost (modo treino)
        if (isTrainingMode && ghostData.active) {
            let ghostPos = getMapPos(ghostData.ghostZ);
            // Halo pulsante do ghost
            mCtx.beginPath();
            mCtx.arc(ghostPos.x, ghostPos.y, 5, 0, Math.PI * 2);
            mCtx.fillStyle = 'rgba(0, 255, 204, 0.2)';
            mCtx.fill();
            mCtx.beginPath();
            mCtx.arc(ghostPos.x, ghostPos.y, 3, 0, Math.PI * 2);
            mCtx.fillStyle = '#00ffcc';
            mCtx.fill();
        }

        // Ponto do jogador (sobre o traçado)
        let playerPos2D = getMapPos(position);
        // Halo externo
        mCtx.beginPath();
        mCtx.arc(playerPos2D.x, playerPos2D.y, 6, 0, Math.PI * 2);
        mCtx.fillStyle = 'rgba(255, 255, 255, 0.18)';
        mCtx.fill();
        // Ponto principal branco brilhante
        mCtx.beginPath();
        mCtx.arc(playerPos2D.x, playerPos2D.y, 3.5, 0, Math.PI * 2);
        mCtx.fillStyle = '#ffffff';
        mCtx.fill();
        // Borda de cor do carro
        mCtx.beginPath();
        mCtx.arc(playerPos2D.x, playerPos2D.y, 3.5, 0, Math.PI * 2);
        mCtx.strokeStyle = playerCarColor || '#e10600';
        mCtx.lineWidth = 1.5;
        mCtx.stroke();

        // Label "MAP" discreto no canto
        mCtx.fillStyle = 'rgba(255,255,255,0.2)';
        mCtx.font = '5px "Press Start 2P", monospace';
        mCtx.fillText('MAP', 4, MH - 4);

        mCtx.restore();
    }

