    function initWeatherSystem() {
        rainParticles = [];
        cloudParticles = [];
        sprayParticles = [];

        let cloudCount = weather === 'RAIN' ? 20 : 10;
        for (let i = 0; i < cloudCount; i++) {
            cloudParticles.push({
                x: Math.random() * WIDTH,
                y: 20 + Math.random() * (HEIGHT * 0.22),
                radius: 20 + Math.random() * 35,
                speed: 10 + Math.random() * 20,
                color: weather === 'RAIN' ? 'rgba(30, 40, 50, 0.85)' : (weather === 'SUNSET' ? 'rgba(255, 140, 100, 0.5)' : 'rgba(255, 255, 255, 0.75)')
            });
        }

        if (weather === 'RAIN') {
            for (let i = 0; i < 200; i++) {
                rainParticles.push({
                    x: Math.random() * WIDTH,
                    y: Math.random() * HEIGHT,
                    length: Math.random() * 18 + 12,
                    speedX: -2 + Math.random() * 3,
                    speedY: Math.random() * 20 + 20,
                    thickness: Math.random() * 1.5 + 0.8
                });
            }
        }
    }

    function loop(now) {
        if (!lastTime) lastTime = now;
        let dt = (now - lastTime) / 1000;
        lastTime = now;
        if (dt > 0.1) dt = 0.1;

        update(dt);
        draw();
        requestAnimationFrame(loop);
    }

    function startSequence() {
        const unlocked = getCampaignSeries().series.unlocked;
        if (currentStage > unlocked) currentStage = unlocked;
        const selector = document.getElementById('stage-select');
        if (selector) selector.value = String(currentStage);
        initAudio();
        applyStageWeather();

        state = 'CUTSCENE';
        cutsceneTime = 0;
        cutscenePhase = 0;
        cameraHeight = 1500; 
        lap = 1;
        hasCrossedStartLine = false;
        lapCheckpointMask = 0;
        keyNitroHeld = false;
        lapTime = 0;
        bestLapTime = 0;
        totalRaceTime = 0;
        nitroCharge = 0; nitroActiveTime = 0; nitroCornerTimer = 0;
        nitroCornerNotified = false; nitroPopupTimer = 0;
        nitroCollisionCooldown = 0;
        const nitroHudReset = document.getElementById('nitro-hud');
        if (nitroHudReset) nitroHudReset.classList.remove('ready','active');
        document.getElementById('game-container').classList.remove('nitro-active');
        inPitLane = false;
        isPitStopActive = false;
        pitTimer = 0;
        let pLimitBadge = document.getElementById('pit-limiter-badge');
        if (pLimitBadge) pLimitBadge.classList.add('hidden');
        
        mainMenu.classList.add('hidden');
        gameOverMenu.classList.add('hidden');
        hud.classList.add('hidden');
        if (modeShowcaseOverlay) modeShowcaseOverlay.classList.add('hidden');
        isShowcaseActive = false; 
        pitServiceComplete = false;
        hasCompletedPitStop = false;
        pitStopCount = 0;
        pitLaunchAnimation = 0;
        victoryCelebrationTimer = 0;
        victoryConfetti = [];
        victoryFireworks = [];
        let pReadyEl = document.getElementById('pit-ready-prompt');
        if (pReadyEl) pReadyEl.classList.add('hidden');
        let pOverlayEl = document.getElementById('pit-stop-overlay');
        if (pOverlayEl) pOverlayEl.classList.add('hidden');
        cutsceneTitle.style.display = 'block';
        document.getElementById('start-lights').style.display = 'none';
        
        resetRoad();
        resetCars();
        
        let dummyPlayer = {
            offset: -0.4,
            z: trackLength - (10 * 800),
            sprite: SPRITES.PLAYER_STRAIGHT,
            speed: 0, maxSpeed: 0, isDummy: true
        };
        findSegment(dummyPlayer.z).cars.push(dummyPlayer);
        cars.push(dummyPlayer);

        if (isMobile) mControls.style.display = 'flex';
    }

    function startLightsCountdown() {
        state = 'LIGHTS';
        hud.classList.remove('hidden');
        document.getElementById('start-lights').style.display = 'flex';
        let lIdx = 0; lights.forEach(l => { l.className = 'light'; }); 
        
        let interval = setInterval(() => {
            if(lIdx < 5) { lights[lIdx].classList.add('red'); lIdx++; } 
            else {
                clearInterval(interval);
                lights.forEach(l => { l.classList.remove('red'); l.classList.add('green'); });
                state = 'RACING';
                triggerNarratorEvent('START', null, 4);
                setTimeout(() => { document.getElementById('start-lights').style.display = 'none'; }, 1500);
            }
        }, 800);
    }

    function endRace() {
        state = 'FINISHED';
        let passed = playerPos <= 3;
        const campaignResult = recordCampaignResult(playerPos);
        if (passed) {
            triggerNarratorEvent('VICTORY', null, 4);
            playVictoryFanfare(playerPos);
        } else {
            // A prova continua com efeitos discretos, sem fanfarra de campeão.
        }
        setTimeout(() => {
            hud.classList.add('hidden');
        if (modeShowcaseOverlay) modeShowcaseOverlay.classList.add('hidden');
        isShowcaseActive = false;
            if (isMobile) mControls.style.display = 'none';
            gameOverMenu.classList.remove('hidden');
            
            let actionBtn = document.getElementById('action-btn');
            let retryBtn = document.getElementById('retry-btn');
            let resTitle = document.getElementById('result-title');
            let resPos = document.getElementById('result-pos');
            let resDesc = document.getElementById('result-desc');

            resPos.innerText = playerPos + "º LUGAR";
            resPos.style.color = playerPos === 1 ? '#ffd700' : (playerPos === 2 ? '#e5edf8' : (playerPos === 3 ? '#cd7f32' : '#ff5555'));
            gameOverMenu.dataset.playerPosition = String(playerPos);

            // Atualiza Resumo Estatístico da Corrida
            const totalTimeEl = document.getElementById('stat-total-time');
            const bestLapEl = document.getElementById('stat-best-lap');
            const finalPosEl = document.getElementById('stat-final-pos');
            const arcadeTag = document.getElementById('arcade-status-tag');
            
            if (totalTimeEl) totalTimeEl.innerText = Util.formatTime(totalRaceTime);
            if (bestLapEl) bestLapEl.innerText = Util.formatTime(bestLapTime);
            if (finalPosEl) finalPosEl.innerText = playerPos + "º / " + (cars.length || 10);
            const pitStopsEl = document.getElementById('stat-pit-stops');
            if (pitStopsEl) pitStopsEl.innerText = String(pitStopCount || 0);
            animateResultStats(totalRaceTime, bestLapTime, playerPos, pitStopCount || 0);

            if (passed) {
                gameOverMenu.classList.remove('defeat');
                if (arcadeTag) arcadeTag.innerText = "QUALIFICADO • TOP 3";
                if (currentStage < STAGES.length - 1) {
                    resTitle.textContent = "CORRIDA CONCLUÍDA!";
                    resDesc.innerText = "QUALIFICADO PARA A PRÓXIMA FASE!";
                    actionBtn.innerText = "PRÓXIMA FASE ▸";
                    actionBtn.classList.remove('hidden');
                    retryBtn.classList.add('hidden');
                    actionBtn.onclick = function() {
                        currentStage++;
                        startSequence();
                    };
                } else if (playerPos === 1) {
                    resTitle.textContent = "VITÓRIA!";
                    resDesc.innerText = `VOCÊ CONQUISTOU O TROFÉU OURO ${getSeriesLabel()}!`; 
                    actionBtn.innerText = "REJOGAR CAMPEONATO ▸";
                    actionBtn.classList.remove('hidden');
                    retryBtn.classList.add('hidden');
                    actionBtn.onclick = function() { currentStage = 0; startSequence(); };
                } else {
                    resTitle.textContent = "CORRIDA CONCLUÍDA!";
                    resDesc.innerText = "VOCÊ FEZ PÓDIO, MAS PRECISA VENCER A FASE FINAL PARA GANHAR O TROFÉU OURO.";
                    actionBtn.classList.add('hidden');
                    retryBtn.classList.remove('hidden');
                    retryBtn.innerText = "TENTAR NOVAMENTE ↻";
                    retryBtn.onclick = function() { startSequence(); };
                }
            } else {
                gameOverMenu.classList.add('defeat');
                if (arcadeTag) arcadeTag.innerText = "ELIMINADO • NÃO QUALIFICADO";
                resTitle.textContent = "CORRIDA FINALIZADA";
                resDesc.innerText = `Você terminou em ${playerPos}º Lugar - Necessário TOP 3 para avançar`;
                actionBtn.classList.add('hidden');
                retryBtn.classList.remove('hidden');
                retryBtn.innerText = "TENTAR NOVAMENTE ↻";
                retryBtn.onclick = function() {
                    startSequence();
                };
            }

            const podiumStrip = document.getElementById('podium-strip');
            if (podiumStrip) {
                // Sincroniza sempre os detalhes customizados do jogador na garagem
                try {
                    const gSaved = JSON.parse(localStorage.getItem('retroRacingGarage') || '{}');
                    if (gSaved.body) playerCarColor = gSaved.body;
                    if (gSaved.helmet) playerHelmetColor = gSaved.helmet;
                } catch(e) {}
                const order = [2, 1, 3];
                podiumStrip.innerHTML = order.map(place => {
                    const isPlayer = playerPos === place;
                    const className = place === 1 ? 'p1' : (place === 2 ? 'p2' : 'p3');
                    const name = isPlayer ? (place === 1 ? 'VOCÊ • CAMPEÃO' : 'VOCÊ') : `RIVAL ${place}`;
                    const trim = place === 1 ? '#ffd700' : (place === 2 ? '#dce8f7' : '#cd7f32');
                    const marker = isPlayer ? '<span class="you-marker">▼ VOCÊ ▼</span>' : '<span class="you-marker" style="visibility:hidden">▼ VOCÊ ▼</span>';
                    const driver = isPlayer ? '🏎️' : '🏁';
                    return `<div class="podium-place ${className} ${isPlayer ? 'player-podium' : ''}" style="--player-color:${isPlayer ? playerCarColor : trim};border-color:${trim}">${marker}<span class="podium-car" style="${isPlayer ? `filter:drop-shadow(0 0 9px ${playerCarColor})` : ''}">${driver}</span><b>${place}º</b><div>${name}</div><small style="color:${trim}">${place===1?'OURO':place===2?'PRATA':'BRONZE'}</small></div>`;
                }).join('');
            }
            const resultTitleNode = document.getElementById('result-title');
            if (resultTitleNode && playerPos === 1) resultTitleNode.classList.add('victory-flash');
            refreshCampaignUI();
            animateTrophyCanvas();
        }, 2000); 
    }

    function animateResultStats(totalSeconds, bestSeconds, finalPosition, pitStops) {
        const animate = (element, target, formatter, duration) => {
            if (!element) return;
            const start = performance.now();
            const frame = now => {
                const progress = Math.min(1, (now - start) / duration);
                const eased = 1 - Math.pow(1 - progress, 3);
                element.textContent = formatter(target * eased);
                if (progress < 1) requestAnimationFrame(frame);
            };
            requestAnimationFrame(frame);
        };
        animate(document.getElementById('stat-total-time'), totalSeconds, v => Util.formatTime(v), 1050);
        animate(document.getElementById('stat-best-lap'), bestSeconds, v => Util.formatTime(v), 900);
        animate(document.getElementById('stat-final-pos'), finalPosition, v => `${Math.max(1, Math.round(v))}º / ${cars.length || 10}`, 700);
        animate(document.getElementById('stat-pit-stops'), pitStops, v => String(Math.round(v)), 700);
    }

    let confettiParticles = [];
    let flashParticles = [];
    let fireworkRockets = [];
    let champagneDrops = [];
    let trophyAnimStartTime = 0;
    let lastTrophyTimestamp = 0;

    function animateTrophyCanvas() {
        confettiParticles = []; flashParticles = []; fireworkRockets = []; champagneDrops = [];
        trophyAnimStartTime = performance.now();
        lastTrophyTimestamp = performance.now();
        
        // Se NÃO se qualificar (4º Lugar ou pior): NÃO exibe confetes nem comemorações
        if (playerPos > 3) {
            requestAnimationFrame(renderTrophyFrame);
            return;
        }

        // Quantidade e paleta calibradas conforme a posição no Pódio
        let count = 80;
        if (playerPos === 1) count = 240; // 1º: Intensa de confetes dourados/multicor
        else if (playerPos === 2) count = 150; // 2º: Moderada de confetes prateados
        else if (playerPos === 3) count = 85;  // 3º: Leve chuva discreta de papéis picados

        for(let i=0; i<count; i++) {
            let pColor = '#ffd700';
            if (playerPos === 1) {
                const goldMulti = ['#ffd700','#ffea00','#ff3366','#00e676','#00b0ff','#f50057','#ffffff','#ff9100'];
                pColor = goldMulti[Math.floor(Math.random() * goldMulti.length)];
            } else if (playerPos === 2) {
                const silvers = ['#ffffff','#f8fafc','#e2e8f0','#cbd5e1','#94a3b8','#64748b'];
                pColor = silvers[Math.floor(Math.random() * silvers.length)];
            } else if (playerPos === 3) {
                const bronzeSubtle = ['#cd7f32','#e5a15b','#d49b6a','#f2d4b8','#a66a38','#b45309'];
                pColor = bronzeSubtle[Math.floor(Math.random() * bronzeSubtle.length)];
            }

            confettiParticles.push({
                x: Math.random() * trophyCanvas.width,
                y: Math.random() * trophyCanvas.height - trophyCanvas.height,
                w: 4 + Math.random() * 5,
                h: 2.5 + Math.random() * 4,
                color: pColor,
                speedY: (playerPos === 3 ? 35 + Math.random()*45 : (playerPos === 2 ? 50 + Math.random()*65 : 65 + Math.random()*95)),
                wobblePhase: Math.random() * Math.PI * 2,
                wobbleSpeed: 2.5 + Math.random() * 3.5,
                wobbleAmp: 30 + Math.random() * 45,
                rot: Math.random() * Math.PI * 2,
                rotSpeed: (Math.random() - 0.5) * 3.5
            });
        }
        requestAnimationFrame(renderTrophyFrame);
    }

    function renderTrophyFrame(currentTimestamp) {
        if (gameOverMenu.classList.contains('hidden')) return;
        if (!currentTimestamp) currentTimestamp = performance.now();
        let deltaT = Math.min(0.05, (currentTimestamp - (lastTrophyTimestamp || currentTimestamp)) / 1000);
        lastTrophyTimestamp = currentTimestamp;
        
        let elapsed = (currentTimestamp - trophyAnimStartTime) / 1000;
        let t = elapsed * 3.5;

        tCtx.clearRect(0,0,trophyCanvas.width,trophyCanvas.height);

        // Fundo degradê suave estilo arquibancada noturna com luzes
        let bgGrad = tCtx.createLinearGradient(0, 0, 0, trophyCanvas.height);
        bgGrad.addColorStop(0, '#040714');
        bgGrad.addColorStop(0.65, '#0b1329');
        bgGrad.addColorStop(1, '#02050e');
        tCtx.fillStyle = bgGrad;
        tCtx.fillRect(0, 0, trophyCanvas.width, trophyCanvas.height);

        // Recupera detalhes customizados do jogador (garagem) para garantir fidelidade visual
        let playerCustom = {
            body: playerCarColor || '#e10600',
            helmet: playerHelmetColor || '#ffcc00',
            trim: '#ffffff'
        };
        try {
            const gSaved = JSON.parse(localStorage.getItem('retroRacingGarage') || '{}');
            if (gSaved.body) playerCustom.body = gSaved.body;
            if (gSaved.helmet) playerCustom.helmet = gSaved.helmet;
            if (gSaved.trim) playerCustom.trim = gSaved.trim;
        } catch(e) {}

        const cx = trophyCanvas.width / 2, cy = 160;

        // 1. Holofotes com transição ultra-suave ease-in / ease-out cúbica
        function smoothBeam(angle) {
            let s = Math.sin(angle);
            return Math.sign(s) * (3 * Math.pow(Math.abs(s), 2) - 2 * Math.pow(Math.abs(s), 3)); // Smoothstep clássico
        }

        if (playerPos <= 3) {
            const beamCount = playerPos === 1 ? 6 : 4;
            for (let beam = 0; beam < beamCount; beam++) {
                const bx = (beam * (trophyCanvas.width / Math.max(1, beamCount - 1)));
                const swing = smoothBeam(t * 0.9 + beam * 1.05) * (playerPos === 1 ? 110 : 75);
                const glow = 0.07 + (Math.cos(t * 2.0 + beam) * 0.5 + 0.5) * (playerPos === 1 ? 0.16 : 0.10);
                tCtx.fillStyle = `rgba(255, 235, 140, ${glow})`;
                tCtx.beginPath();
                tCtx.moveTo(bx - 12, 0);
                tCtx.lineTo(bx + 12, 0);
                tCtx.lineTo(cx + swing, cy + 20);
                tCtx.closePath();
                tCtx.fill();
            }
        } else if (playerPos === 2) {
            for (let beam = 0; beam < 3; beam++) {
                const bx = (beam + 1) * (trophyCanvas.width / 4);
                const swing = smoothBeam(t * 0.7 + beam * 1.8) * 60;
                const glow = 0.07 + (Math.cos(t * 1.4 + beam) * 0.5 + 0.5) * 0.10;
                tCtx.fillStyle = `rgba(200, 225, 255, ${glow})`;
                tCtx.beginPath();
                tCtx.moveTo(bx - 10, 0);
                tCtx.lineTo(bx + 10, 0);
                tCtx.lineTo(cx + swing, cy + 25);
                tCtx.closePath();
                tCtx.fill();
            }
        } else if (playerPos === 3) {
            const bx = trophyCanvas.width / 2;
            const swing = smoothBeam(t * 0.6) * 45;
            const glow = 0.05 + (Math.cos(t * 1.0) * 0.5 + 0.5) * 0.06;
            tCtx.fillStyle = `rgba(255, 220, 180, ${glow})`;
            tCtx.beginPath();
            tCtx.moveTo(bx - 30, 0);
            tCtx.lineTo(bx + 30, 0);
            tCtx.lineTo(cx + 80 + swing, cy + 35);
            tCtx.lineTo(cx - 80 + swing, cy + 35);
            tCtx.closePath();
            tCtx.fill();
        }

        // Fogos de artifício no fundo para 1º Lugar
        if (playerPos === 1) {
            if (Math.random() < 0.10) {
                const fwColors = ['#ffd700','#ff3366','#33ccff','#33ff99','#ff9933','#ff00ff'];
                const fwX = 35 + Math.random() * (trophyCanvas.width - 70);
                const fwY = 20 + Math.random() * 75;
                const fwColor = fwColors[Math.floor(Math.random() * fwColors.length)];
                for (let k = 0; k < 18; k++) {
                    const ang = (Math.PI * 2 / 18) * k + Math.random() * 0.2;
                    const spd = 1.2 + Math.random() * 2.2;
                    fireworkRockets.push({
                        x: fwX, y: fwY,
                        vx: Math.cos(ang) * spd, vy: Math.sin(ang) * spd,
                        color: fwColor, life: 1.0, decay: 0.035 + Math.random() * 0.02
                    });
                }
            }
            for (let i = fireworkRockets.length - 1; i >= 0; i--) {
                const fw = fireworkRockets[i];
                tCtx.fillStyle = fw.color;
                tCtx.globalAlpha = Math.max(0, fw.life);
                tCtx.fillRect(fw.x, fw.y, 2.5, 2.5);
                fw.x += fw.vx; fw.y += fw.vy; fw.vy += 0.03; // gravidade leve
                fw.life -= fw.decay;
                if (fw.life <= 0) fireworkRockets.splice(i, 1);
            }
            tCtx.globalAlpha = 1.0;
        }

        // Título de celebração
        const rankAccent = playerPos === 1 ? '#ffd700' : (playerPos === 2 ? '#e5edf8' : (playerPos === 3 ? '#cd7f32' : '#9aa4b2'));
        tCtx.fillStyle=rankAccent; tCtx.font='bold 12px monospace'; tCtx.textAlign='center'; 
        tCtx.fillText(playerPos === 1 ? '★ 1º LUGAR • GRANDE CAMPEÃO ★' : (playerPos === 2 ? '◈ 2º LUGAR • VICE-CAMPEÃO ◈' : (playerPos === 3 ? '◆ 3º LUGAR • TERCEIRO COLOCADO ◆' : 'CORRIDA FINALIZADA')), cx, 22);
        tCtx.textAlign='start';

        // Flash de fotos
        if (Math.random() < (playerPos === 1 ? 0.22 : (playerPos === 2 ? 0.09 : 0.04))) {
            flashParticles.push({
                x: Math.random() * trophyCanvas.width, y: 15 + Math.random() * (trophyCanvas.height - 30),
                life: 1.0, size: 15 + Math.random() * 35
            });
        }
        for (let i = flashParticles.length - 1; i >= 0; i--) {
            let f = flashParticles[i];
            tCtx.fillStyle = `rgba(255, 255, 255, ${f.life * 0.75})`;
            tCtx.beginPath(); tCtx.arc(f.x, f.y, f.size, 0, Math.PI*2); tCtx.fill();
            f.life -= 0.12;
            if (f.life <= 0) flashParticles.splice(i, 1);
        }

        // Degraus do pódio perfeitamente centralizados e proporcionais na largura 640
        // P1: centro cx=320, largura 100, altura 85 (y: 200 a 285)
        // P2: esquerda x=205, largura 95, altura 65 (y: 220 a 285)
        // P3: direita x=435, largura 95, altura 50 (y: 235 a 285)

        // Sombra de contato da base do pódio
        tCtx.fillStyle = 'rgba(0,0,0,0.5)';
        tCtx.beginPath();
        tCtx.ellipse(cx, 287, 210, 12, 0, 0, Math.PI * 2);
        tCtx.fill();

        // Degrau 2 (Vice-Campeão - Prata)
        tCtx.fillStyle = '#9cb3c9'; tCtx.fillRect(205, 220, 95, 65);
        tCtx.fillStyle = '#6b8299'; tCtx.fillRect(290, 220, 10, 65);
        tCtx.fillStyle = '#172033'; tCtx.font = '18px "Press Start 2P"'; tCtx.fillText("2", 242, 260);

        // Degrau 3 (Terceiro Lugar - Bronze)
        tCtx.fillStyle = '#b07f59'; tCtx.fillRect(340, 235, 95, 50);
        tCtx.fillStyle = '#7a5132'; tCtx.fillRect(425, 235, 10, 50); 
        tCtx.fillStyle = '#172033'; tCtx.font = '18px "Press Start 2P"'; tCtx.fillText("3", 377, 270);

        // Degrau 1 (Grande Campeão - Ouro)
        tCtx.fillStyle = '#f0c638'; tCtx.fillRect(270, 195, 100, 90);
        tCtx.fillStyle = '#b89419'; tCtx.fillRect(360, 195, 10, 90); 
        tCtx.fillStyle = '#172033'; tCtx.font = '24px "Press Start 2P"'; tCtx.fillText("1", 308, 250);

        // Pilotos nos 3 degraus (1 = topo x:320 y:168, 2 = x:252 y:193, 3 = x:388 y:208)
        const rivalColors = [
            { body: '#0600ef', helmet: '#ffd700', trim: '#ffffff' },
            { body: '#1b1b1b', helmet: '#ffffff', trim: '#cccccc' },
            { body: '#ff8000', helmet: '#ffffff', trim: '#000000' }
        ];

        let d1 = (playerPos === 1) ? playerCustom : rivalColors[0];
        let d2 = (playerPos === 2) ? playerCustom : (playerPos === 1 ? rivalColors[0] : rivalColors[1]);
        let d3 = (playerPos === 3) ? playerCustom : (playerPos > 3 ? rivalColors[2] : (playerPos === 1 ? rivalColors[1] : rivalColors[2]));

        // Função universal de desenho de piloto com subida suave e comemorações vivas
        function drawPodiumDriver(ctx, x, targetY, driverCfg, isPlayer, place) {
            ctx.save();
            
            // 1. Animação de subida suave no degrau (Climb / Entry Transition)
            let climbProgress = Math.min(1.0, elapsed * 1.5);
            // Curva ease-out de subida suavizada
            let climbEase = 1.0 - Math.pow(1.0 - climbProgress, 3);
            let startY = targetY + 38;
            let currentY = startY + (targetY - startY) * climbEase;

            // 2. Interpolação viva e sincronizada de comemoração
            let jOffset = 0;
            let armVibration = 0;
            let trophyLift = Math.min(1.0, Math.max(0.0, (elapsed - 0.5) * 1.8)); // Ergue o troféu suavemente
            let trophyLiftEase = 1.0 - Math.pow(1.0 - trophyLift, 2);

            if (place === 1) {
                // 1º Lugar: Pulos suaves sincronizados e vibração rítmica das mãos
                jOffset = (Math.sin(t * 3.5) * 0.5 + 0.5) * 6 * trophyLiftEase;
                armVibration = Math.sin(t * 12) * 1.5 * trophyLiftEase;
            } else if (place === 2) {
                // 2º Lugar: Aceno contido e movimento de respiração
                jOffset = (Math.sin(t * 2.0) * 0.5 + 0.5) * 2.5;
            } else if (place === 3) {
                // 3º Lugar: Positivo contido
                jOffset = (Math.sin(t * 1.5) * 0.5 + 0.5) * 1.8;
            }

            ctx.translate(x, currentY - jOffset);

            // Macacão: Pernas e Detalhes
            ctx.fillStyle = driverCfg.body;
            ctx.fillRect(-10, 0, 8, 25); ctx.fillRect(2, 0, 8, 25);
            // Sapatos de corrida
            ctx.fillStyle = '#111827';
            ctx.fillRect(-12, 20, 10, 6); ctx.fillRect(2, 20, 10, 6);

            // Tronco do macacão com faixa/faixa de detalhes (trim) da garagem
            ctx.fillStyle = driverCfg.body;
            ctx.fillRect(-12, -25, 24, 25);
            // Cinto
            ctx.fillStyle = '#1e293b'; ctx.fillRect(-12, -4, 24, 4);
            // Faixas peitorais com detalhe (trim)
            ctx.fillStyle = driverCfg.trim || '#ffffff';
            ctx.fillRect(-8, -22, 16, 4);
            ctx.fillRect(-2, -22, 4, 18);

            // BRAÇOS, TROFÉUS, MEDALHAS E REAÇÕES
            if (place === 1) {
                // AMBAS AS MÃOS ERGUIDAS EM VIBRAÇÃO SEGURANDO O TROFÉU DE OURO
                ctx.fillStyle = driverCfg.body;
                ctx.fillRect(-18, -42 + armVibration, 6, 22);
                ctx.fillRect(12, -42 - armVibration, 6, 22);
                // Luvas
                ctx.fillStyle = '#f8fafc';
                ctx.fillRect(-19, -46 + armVibration, 8, 6);
                ctx.fillRect(11, -46 - armVibration, 8, 6);

                // Troféu de Ouro com brilho reluzente
                let thY = -46 + armVibration;
                ctx.fillStyle = '#78350f'; ctx.fillRect(-12, thY, 24, 6); // Base do troféu
                ctx.fillStyle = '#ffd700'; ctx.fillRect(-5, thY - 11, 10, 11); // Haste
                // Taça dourada
                ctx.beginPath();
                ctx.moveTo(-18, thY - 32); ctx.lineTo(18, thY - 32);
                ctx.lineTo(12, -46 + armVibration - 11); ctx.lineTo(-12, -46 + armVibration - 11);
                ctx.fill();
                // Alças da taça
                ctx.strokeStyle = '#ffd700'; ctx.lineWidth = 3;
                ctx.beginPath(); ctx.arc(-15, thY - 22, 8, Math.PI/2, Math.PI*1.5); ctx.stroke();
                ctx.beginPath(); ctx.arc(15, thY - 22, 8, -Math.PI/2, Math.PI/2); ctx.stroke();
                // Brilho reluzente
                if (Math.sin(t * 6) > 0) {
                    ctx.fillStyle = '#ffffff';
                    ctx.fillRect(-6, thY - 28, 4, 4);
                }

                // Garrafa e Jatos animados de Champanhe
                const bottleX = 22, bottleY = -28 + armVibration;
                ctx.fillStyle = '#14532d'; // Garrafa verde
                ctx.fillRect(bottleX, bottleY, 7, 16);
                ctx.fillStyle = '#ca8a04'; // Gargalo dourado
                ctx.fillRect(bottleX + 2, bottleY - 6, 3, 6);

                // Emissão de jatos de champanhe
                if (Math.random() < 0.6) {
                    champagneDrops.push({
                        x: x + bottleX + 3,
                        y: y - jOffset + bottleY - 6,
                        vx: 1.2 + Math.random() * 2.5,
                        vy: -2.8 - Math.random() * 2.8,
                        life: 1.0,
                        size: 2 + Math.random() * 2
                    });
                }
            } else if (place === 2) {
                // Braço esquerdo segurando Troféu/Medalha de Prata
                ctx.fillStyle = driverCfg.body;
                ctx.fillRect(-16, -18, 6, 18);
                ctx.fillStyle = '#f8fafc'; ctx.fillRect(-17, -2, 8, 6); // Luva esquerda
                
                // Medalha/Troféu de Prata na mão
                ctx.fillStyle = '#e2e8f0'; ctx.beginPath(); ctx.arc(-13, 8, 6, 0, Math.PI*2); ctx.fill();
                ctx.strokeStyle = '#94a3b8'; ctx.lineWidth = 2; ctx.stroke();
                ctx.fillStyle = '#3b82f6'; ctx.fillRect(-15, -1, 4, 6); // fita da medalha

                // Braço direito em aceno para a torcida (wave)
                const waveAngle = Math.sin(t * 7) * 0.35;
                ctx.save();
                ctx.translate(14, -20);
                ctx.rotate(-0.6 + waveAngle);
                ctx.fillStyle = driverCfg.body;
                ctx.fillRect(0, -18, 6, 18);
                ctx.fillStyle = '#f8fafc'; ctx.fillRect(-1, -22, 8, 6); // Mão acenando
                ctx.restore();
            } else if (place === 3) {
                // Braço direito segurando medalha de bronze
                ctx.fillStyle = driverCfg.body;
                ctx.fillRect(10, -18, 6, 18);
                ctx.fillStyle = '#f8fafc'; ctx.fillRect(9, -2, 8, 6);
                // Medalha de bronze
                ctx.fillStyle = '#cd7f32'; ctx.beginPath(); ctx.arc(13, 8, 6, 0, Math.PI*2); ctx.fill();
                ctx.strokeStyle = '#7c2d12'; ctx.lineWidth = 2; ctx.stroke();
                ctx.fillStyle = '#ef4444'; ctx.fillRect(11, -1, 4, 6); // fita

                // Braço esquerdo fazendo sinal de Positivo (Thumbs Up)
                ctx.fillStyle = driverCfg.body;
                ctx.fillRect(-16, -16, 6, 16);
                ctx.fillStyle = '#f8fafc';
                ctx.fillRect(-17, -22, 8, 7); // Mão
                ctx.fillRect(-15, -26, 4, 5); // Polegar erguido (thumbs up!)
            }

            // Capacete e Viseira com cores fiéis
            ctx.fillStyle = driverCfg.helmet;
            ctx.beginPath(); ctx.arc(0, -32, 14, 0, Math.PI*2); ctx.fill();
            // Viseira reflexiva estilo automobilismo
            ctx.fillStyle = '#0f172a'; ctx.fillRect(-10, -36, 20, 10);
            ctx.fillStyle = '#38bdf8'; ctx.fillRect(-6, -34, 6, 3); // reflexo azul ciano

            // Indicador piscando acima da cabeça do jogador: "▼ VOCÊ ▼"
            if (isPlayer) {
                const arrowBounce = Math.sin(t * 8) * 3;
                ctx.save();
                ctx.translate(0, -56 + arrowBounce);
                // Plaquinha / Tag "VOCÊ"
                ctx.fillStyle = '#ffcc00';
                ctx.strokeStyle = '#000000';
                ctx.lineWidth = 1.5;
                ctx.fillRect(-18, -12, 36, 13);
                ctx.strokeRect(-18, -12, 36, 13);
                ctx.fillStyle = '#111827';
                ctx.font = 'bold 8px sans-serif';
                ctx.textAlign = 'center';
                ctx.fillText('VOCÊ', 0, -3);
                // Seta apontando para o piloto
                ctx.fillStyle = '#ffcc00';
                ctx.beginPath();
                ctx.moveTo(-5, 1); ctx.lineTo(5, 1); ctx.lineTo(0, 7); ctx.closePath();
                ctx.fill();
                ctx.stroke();
                ctx.restore();
            }

            ctx.restore();
        }

        if (playerPos <= 3) {
            // CENA DE PÓDIO (QUALIFICADO / TOP 3)
            drawPodiumDriver(tCtx, 252, 193, d2, playerPos === 2, 2);
            drawPodiumDriver(tCtx, 388, 208, d3, playerPos === 3, 3);
            drawPodiumDriver(tCtx, 320, 168, d1, playerPos === 1, 1);
        } else {
            // CENA DE DERROTA SÓBRIA (PIT LANE / BOX - SEM CONFETES OU COMEMORAÇÃO)
            // Fundo sóbrio: Garagem / Pit Lane à noite
            tCtx.fillStyle = '#0f172a';
            tCtx.fillRect(0, 0, trophyCanvas.width, trophyCanvas.height);

            // Piso de asfalto do box com marcações amarelas
            tCtx.fillStyle = '#1e293b';
            tCtx.fillRect(0, 120, trophyCanvas.width, trophyCanvas.height - 120);
            tCtx.strokeStyle = 'rgba(255, 235, 59, 0.4)';
            tCtx.lineWidth = 3;
            tCtx.beginPath();
            tCtx.moveTo(0, 150); tCtx.lineTo(trophyCanvas.width, 150);
            tCtx.stroke();

            // Placa do Pit Lane
            tCtx.fillStyle = '#111827';
            tCtx.fillRect(30, 20, 160, 36);
            tCtx.strokeStyle = '#ef4444';
            tCtx.lineWidth = 2;
            tCtx.strokeRect(30, 20, 160, 36);
            tCtx.fillStyle = '#ef4444';
            tCtx.font = 'bold 9px monospace';
            tCtx.fillText('PIT LANE // BOX 07', 42, 42);

            // Carro parado no box
            const carX = 140, carY = 160;
            const drawPlayerCar = currentSeries === 'NASCAR' ? window.drawNascarSprite
                                : (currentSeries === 'RALLY' ? window.drawRallySprite : drawProceduralCarSprite);
            const selModel = currentSeries === 'NASCAR' ? selectedNascarModel : selectedRallyModel;
            if (currentSeries === 'F1') {
                drawProceduralCarSprite(tCtx, carX - 50, carY - 25, 100, 50, playerCustom.body, playerCustom.trim, 0, playerCustom.helmet);
            } else if (typeof drawPlayerCar === 'function') {
                drawPlayerCar(tCtx, carX - 50, carY - 25, 100, 50, playerCustom.body, playerCustom.trim, 0, playerCustom.helmet, selModel);
            }

            // Fumaça/Vapor leve saindo do motor
            tCtx.fillStyle = 'rgba(148, 163, 184, 0.2)';
            for (let s = 0; s < 4; s++) {
                const sY = carY - 20 - ((t * 15 + s * 12) % 30);
                const sX = carX + 30 + Math.sin(t * 2 + s) * 5;
                tCtx.beginPath();
                tCtx.arc(sX, sY, 6 + s * 2, 0, Math.PI * 2);
                tCtx.fill();
            }

            // Piloto em pé ao lado do carro, cabisbaixo / desapontado olhando o pódio ao longe
            const drX = 260, drY = 145;
            tCtx.save();
            tCtx.translate(drX, drY);
            
            // Corpo do piloto
            tCtx.fillStyle = playerCustom.body;
            tCtx.fillRect(-8, 0, 6, 24); tCtx.fillRect(2, 0, 6, 24); // Pernas
            tCtx.fillStyle = '#111827';
            tCtx.fillRect(-10, 20, 8, 5); tCtx.fillRect(2, 20, 8, 5); // Sapatos
            tCtx.fillStyle = playerCustom.body;
            tCtx.fillRect(-10, -22, 20, 22); // Tronco
            tCtx.fillStyle = playerCustom.trim;
            tCtx.fillRect(-2, -20, 4, 18); // Detalhe

            // Braços caídos de desapontamento
            tCtx.fillStyle = playerCustom.body;
            tCtx.fillRect(-14, -18, 5, 20);
            tCtx.fillRect(9, -18, 5, 20);
            tCtx.fillStyle = '#f8fafc';
            tCtx.fillRect(-15, 0, 7, 5);
            tCtx.fillRect(8, 0, 7, 5);

            // Cabeça inclinada para baixo (desapontado)
            tCtx.fillStyle = playerCustom.helmet;
            tCtx.beginPath();
            tCtx.arc(0, -26, 12, 0, Math.PI * 2);
            tCtx.fill();
            tCtx.fillStyle = '#1e293b';
            tCtx.fillRect(-8, -26, 16, 7); // Viseira virada para baixo

            // Tag "VOCÊ" sobre o piloto desapontado
            tCtx.fillStyle = '#ef4444';
            tCtx.strokeStyle = '#000000';
            tCtx.lineWidth = 1;
            tCtx.fillRect(-16, -48, 32, 12);
            tCtx.strokeRect(-16, -48, 32, 12);
            tCtx.fillStyle = '#ffffff';
            tCtx.font = 'bold 7px sans-serif';
            tCtx.textAlign = 'center';
            tCtx.fillText('VOCÊ', 0, -39);
            tCtx.beginPath();
            tCtx.moveTo(-4, -36); tCtx.lineTo(4, -36); tCtx.lineTo(0, -31);
            tCtx.fillStyle = '#ef4444';
            tCtx.fill();
            tCtx.stroke();
            tCtx.restore();

            // Pódio em miniatura ao fundo com luzes distantes
            tCtx.fillStyle = 'rgba(30, 41, 59, 0.7)';
            tCtx.fillRect(350, 80, 200, 70);
            tCtx.fillStyle = '#ffd700';
            tCtx.font = '8px monospace';
            tCtx.fillText('PÓDIO RIVAL', 410, 105);
            tCtx.fillStyle = 'rgba(255, 215, 0, 0.2)';
            tCtx.fillRect(435, 115, 30, 35);
            tCtx.fillStyle = 'rgba(200, 200, 200, 0.2)';
            tCtx.fillRect(405, 125, 30, 25);
            tCtx.fillStyle = 'rgba(205, 127, 50, 0.2)';
            tCtx.fillRect(465, 132, 30, 18);
        }

        // Render e atualização das gotas de champanhe
        for (let i = champagneDrops.length - 1; i >= 0; i--) {
            const drop = champagneDrops[i];
            tCtx.fillStyle = '#ffffff';
            tCtx.globalAlpha = drop.life;
            tCtx.beginPath();
            tCtx.arc(drop.x, drop.y, drop.size, 0, Math.PI * 2);
            tCtx.fill();
            drop.x += drop.vx;
            drop.y += drop.vy;
            drop.vy += 0.12; // gravidade
            drop.life -= 0.03;
            if (drop.life <= 0 || drop.y > trophyCanvas.height) {
                champagneDrops.splice(i, 1);
            }
        }
        tCtx.globalAlpha = 1.0;

        // Render e atualização da chuva de confetes com física de oscilação fluida orientada a deltaT
        for(let p of confettiParticles) {
            p.wobblePhase += p.wobbleSpeed * deltaT;
            let sway = Math.sin(p.wobblePhase) * p.wobbleAmp;
            p.x += sway * deltaT;
            p.y += p.speedY * deltaT;
            p.rot += p.rotSpeed * deltaT;

            // Escala 3D oscilante simulando rotação de papel no ar
            let scaleX = Math.cos(p.wobblePhase);

            tCtx.save();
            tCtx.translate(p.x, p.y);
            tCtx.rotate(p.rot);
            tCtx.scale(scaleX, 1.0);
            tCtx.fillStyle = p.color;
            tCtx.fillRect(-p.w / 2, -p.h / 2, p.w, p.h);
            tCtx.restore();

            if(p.y > trophyCanvas.height + 15) { 
                p.y = -12; 
                p.x = Math.random() * trophyCanvas.width; 
            }
            if(p.x > trophyCanvas.width + 20) p.x = -15; 
            else if(p.x < -20) p.x = trophyCanvas.width + 15;
        }

        requestAnimationFrame(renderTrophyFrame);
    }

    window.addEventListener('keydown', function(e) {
        if (state === 'RACING' && (e.code === 'ShiftLeft' || e.code === 'ShiftRight' || e.code === 'KeyN')) {
            keyNitroHeld = true;
            if (!e.repeat) activateNitro();
            e.preventDefault();
        }
        if (state === 'PIT_STOP' && pitServiceComplete && (e.code === 'Space' || e.key === ' ')) {
            e.preventDefault();
            releaseCarFromPit();
            return;
        }
        if((state === 'MENU' || state === 'SHOWCASE') && (e.code === 'Space' || e.code === 'Enter')) {
            if (typeof finishShowcaseAndLaunch === 'function' && isShowcaseActive) {
                finishShowcaseAndLaunch();
        
            }
            document.getElementById('start-btn').click(); 
        }
        if(isTrainingMode && e.code === 'Escape') {
            exitTraining();
        }
        switch(e.code) {
            case 'ArrowLeft': case 'KeyA': keyLeft = true; break;
            case 'ArrowRight': case 'KeyD': keyRight = true; break;
            case 'ArrowUp': case 'KeyW': keyFaster = true; break;
            case 'ArrowDown': case 'KeyS': keySlower = true; break;
            case 'KeyP': case 'KeyB':
                if (state === 'RACING') keyPitRequested = true;
                break;
        }
    });
    window.addEventListener('keyup', function(e) {
        if (e.code === 'ShiftLeft' || e.code === 'ShiftRight' || e.code === 'KeyN') {
            keyNitroHeld = false;
        }
    });

    window.addEventListener('keyup', function(e) {
        switch(e.code) {
            case 'ArrowLeft': case 'KeyA': keyLeft = false; break;
            case 'ArrowRight': case 'KeyD': keyRight = false; break;
            case 'ArrowUp': case 'KeyW': keyFaster = false; break;
            case 'ArrowDown': case 'KeyS': keySlower = false; break;
        }
    });

    function setupTouch(id, onDown, onUp) {
        const btn = document.getElementById(id);
        if (!btn) return;
        const press = (e) => { e.preventDefault(); onDown(); btn.classList.add('active'); };
        const rel = (e) => { e.preventDefault(); if (onUp) onUp(); btn.classList.remove('active'); };
        btn.addEventListener('touchstart', press, {passive: false});
        btn.addEventListener('touchend', rel, {passive: false});
        btn.addEventListener('touchcancel', rel, {passive: false});
    }
    setupTouch('btn-gas', ()=>keyFaster=true, ()=>keyFaster=false);
    setupTouch('btn-brake', ()=>keySlower=true, ()=>keySlower=false);
    setupTouch('btn-left', ()=>keyLeft=true, ()=>keyLeft=false);
    setupTouch('btn-right', ()=>keyRight=true, ()=>keyRight=false);
    let pitPromptBtn = document.getElementById('pit-ready-prompt');
    if (pitPromptBtn) {
        pitPromptBtn.addEventListener('click', function(e) {
            e.preventDefault();
            releaseCarFromPit();
        });
    }

    setupTouch('btn-pit', ()=>{ 
        if (state === 'RACING') keyPitRequested = true;
        else if (state === 'PIT_STOP' && pitServiceComplete) releaseCarFromPit();
    }, null);

    let isMobile = /Android|webOS|iPhone|iPad|iPod|BlackBerry|IEMobile|Opera Mini/i.test(navigator.userAgent) || window.innerWidth < 800;

    document.getElementById('f1-series-btn').addEventListener('click', function(e) {
        e.preventDefault();
        setSeries('F1');
    });
    document.getElementById('nascar-series-btn').addEventListener('click', function(e) {
        e.preventDefault();
        setSeries('NASCAR');
    });
    const rallySeriesBtn = document.getElementById('rally-series-btn');
    if (rallySeriesBtn) {
        rallySeriesBtn.addEventListener('click', function(e) {
            e.preventDefault();
            setSeries('RALLY');
        });
    }

    // ==========================================
    // SISTEMA DE TRANSIÇÃO E ANIMAÇÃO PRÉ-JOGO
    // (FÓRMULA 1, NASCAR E RALLY SHOWCASE)
    // ==========================================
    const modeShowcaseOverlay = document.getElementById('mode-showcase-overlay');
    const f1ShowcaseCanvas = document.getElementById('showcase-f1-canvas');
    const nascarShowcaseCanvas = document.getElementById('showcase-nascar-canvas');
    const rallyShowcaseCanvas = document.getElementById('showcase-rally-canvas');
    const f1ShowcaseCtx = f1ShowcaseCanvas ? f1ShowcaseCanvas.getContext('2d') : null;
    const nascarShowcaseCtx = nascarShowcaseCanvas ? nascarShowcaseCanvas.getContext('2d') : null;
    const rallyShowcaseCtx = rallyShowcaseCanvas ? rallyShowcaseCanvas.getContext('2d') : null;

    let showcaseAnimId = null;
    let showcaseStartTime = 0;
    const SHOWCASE_DURATION = 3.6; // 3.6 segundos de animação antes da transição suave
    let showcaseBeepsFired = { 3: false, 2: false, 1: false, 0: false };
    let isShowcaseActive = false;

    // Partículas de faíscas F1 (titânio)
    let f1Sparks = [];
    // Partículas de poeira e cascalho Rally
    let rallyDust = [];
    let rallyGravel = [];

    // Sintetizador de Áudio Arcade Retrô para o Showcase (Web Audio seguro)
    function playShowcaseBeep(freq, duration) {
        try {
            if (!audioCtx) initAudio();
            if (!audioCtx) return;
            if (audioCtx.state === 'suspended') audioCtx.resume();

            let osc = audioCtx.createOscillator();
            let gain = audioCtx.createGain();
            osc.type = 'sine';
            osc.frequency.setValueAtTime(freq, audioCtx.currentTime);
            gain.gain.setValueAtTime(0.12, audioCtx.currentTime);
            gain.gain.exponentialRampToValueAtTime(0.001, audioCtx.currentTime + duration);

            osc.connect(gain);
            gain.connect(audioCtx.destination);
            osc.start();
            osc.stop(audioCtx.currentTime + duration);
        } catch (e) {}
    }

    function playShowcaseWhoosh() {
        try {
            if (!audioCtx) initAudio();
            if (!audioCtx) return;
            if (audioCtx.state === 'suspended') audioCtx.resume();

            let osc = audioCtx.createOscillator();
            let gain = audioCtx.createGain();
            osc.type = 'sawtooth';
            osc.frequency.setValueAtTime(140, audioCtx.currentTime);
            osc.frequency.exponentialRampToValueAtTime(560, audioCtx.currentTime + 0.35);

            gain.gain.setValueAtTime(0.08, audioCtx.currentTime);
            gain.gain.linearRampToValueAtTime(0.001, audioCtx.currentTime + 0.4);

            osc.connect(gain);
            gain.connect(audioCtx.destination);
            osc.start();
            osc.stop(audioCtx.currentTime + 0.4);
        } catch (e) {}
    }

    // 1. ANIMAÇÃO DE FÓRMULA 1 (Grand Prix Asfalto, Zebras & Faíscas de Titânio)
    function renderF1Showcase(ctx, t, playerColor, helmetColor) {
        const W = ctx.canvas.width;
        const H = ctx.canvas.height;
        ctx.clearRect(0, 0, W, H);

        // Céu crepúsculo Grand Prix com gradiente
        let skyGrad = ctx.createLinearGradient(0, 0, 0, 60);
        skyGrad.addColorStop(0, '#0f172a');
        skyGrad.addColorStop(1, '#1e293b');
        ctx.fillStyle = skyGrad;
        ctx.fillRect(0, 0, W, 60);

        // Silhueta de autódromo distante
        ctx.fillStyle = '#0a0f1d';
        ctx.beginPath();
        ctx.moveTo(0, 60);
        ctx.lineTo(40, 48); ctx.lineTo(100, 55); ctx.lineTo(170, 45); ctx.lineTo(240, 54); ctx.lineTo(W, 46);
        ctx.lineTo(W, 60);
        ctx.closePath();
        ctx.fill();

        // Grama lateral
        let grassGrad = ctx.createLinearGradient(0, 60, 0, H);
        grassGrad.addColorStop(0, '#14532d');
        grassGrad.addColorStop(1, '#166534');
        ctx.fillStyle = grassGrad;
        ctx.fillRect(0, 60, W, H - 60);

        // Pista de asfalto em perspectiva
        const topW = 60;
        const botW = 250;
        const topY = 60;
        const botY = H;
        const cx = W / 2;

        ctx.fillStyle = '#262626';
        ctx.beginPath();
        ctx.moveTo(cx - topW / 2, topY);
        ctx.lineTo(cx + topW / 2, topY);
        ctx.lineTo(cx + botW / 2, botY);
        ctx.lineTo(cx - botW / 2, botY);
        ctx.closePath();
        ctx.fill();

        // Zebras (curbings) vermelhas e brancas em alta velocidade
        const speedOffset = (t * 22) % 1;
        const numSegments = 16;
        for (let i = 0; i < numSegments; i++) {
            let p1 = (i + speedOffset) / numSegments;
            let p2 = (i + 1 + speedOffset) / numSegments;
            if (p1 > 1) continue;
            if (p2 > 1) p2 = 1;

            let y1 = topY + (botY - topY) * (p1 * p1);
            let y2 = topY + (botY - topY) * (p2 * p2);
            let w1 = topW + (botW - topW) * p1;
            let w2 = topW + (botW - topW) * p2;
            let curbW1 = 7 * p1;
            let curbW2 = 7 * p2;

            let isRed = (i % 2 === 0);
            ctx.fillStyle = isRed ? '#dc2626' : '#ffffff';

            // Zebra esquerda
            ctx.beginPath();
            ctx.moveTo(cx - w1 / 2, y1);
            ctx.lineTo(cx - w1 / 2 - curbW1, y1);
            ctx.lineTo(cx - w2 / 2 - curbW2, y2);
            ctx.lineTo(cx - w2 / 2, y2);
            ctx.closePath();
            ctx.fill();

            // Zebra direita
            ctx.beginPath();
            ctx.moveTo(cx + w1 / 2, y1);
            ctx.lineTo(cx + w1 / 2 + curbW1, y1);
            ctx.lineTo(cx + w2 / 2 + curbW2, y2);
            ctx.lineTo(cx + w2 / 2, y2);
            ctx.closePath();
            ctx.fill();
        }

        // Faixa central tracejada branca descendo velozmente
        for (let i = 0; i < 8; i++) {
            let p1 = (i * 2 + (t * 28) % 2) / 16;
            let p2 = p1 + 0.07;
            if (p1 >= 1) continue;
            if (p2 > 1) p2 = 1;
            let y1 = topY + (botY - topY) * (p1 * p1);
            let y2 = topY + (botY - topY) * (p2 * p2);
            let lw = 1 + 3 * p1;
            ctx.fillStyle = '#f8fafc';
            ctx.fillRect(cx - lw / 2, y1, lw, Math.max(2, y2 - y1));
        }

        // Monoposto F1 acelerando com trepidação de alta rotação
        let bounce = Math.sin(t * 40) * 1.5;
        let carX = cx;
        let carY = 136 + bounce;

        // Gera faíscas incandescentes de titânio (sparks) saindo sob o fundo do assoalho
        if (Math.random() < 0.85) {
            for (let k = 0; k < 3; k++) {
                f1Sparks.push({
                    x: carX + (Math.random() - 0.5) * 22,
                    y: carY + 12,
                    vx: (Math.random() - 0.5) * 60,
                    vy: Math.random() * 90 + 50,
                    size: Math.random() * 2.5 + 1.2,
                    life: 1.0,
                    decay: Math.random() * 3.5 + 2.5,
                    color: Math.random() < 0.6 ? '#ffea00' : (Math.random() < 0.5 ? '#ff7700' : '#ffffff')
                });
            }
        }

        // Desenha e atualiza faíscas
        for (let i = f1Sparks.length - 1; i >= 0; i--) {
            let sp = f1Sparks[i];
            sp.x += sp.vx * 0.016;
            sp.y += sp.vy * 0.016;
            sp.life -= sp.decay * 0.016;
            if (sp.life <= 0 || sp.y > H) {
                f1Sparks.splice(i, 1);
                continue;
            }
            ctx.save();
            ctx.globalAlpha = Math.max(0, sp.life);
            ctx.fillStyle = sp.color;
            ctx.shadowColor = sp.color;
            ctx.shadowBlur = 6;
            ctx.beginPath();
            ctx.arc(sp.x, sp.y, sp.size, 0, Math.PI * 2);
            ctx.fill();
            ctx.restore();
        }

        // Desenha o Carro de Fórmula 1
        let f1Body = (currentSeries === 'F1' ? playerColor : '#dc2626');
        let f1Helmet = (currentSeries === 'F1' ? helmetColor : '#ffd700');
        drawProceduralCarSprite(ctx, carX - 44, carY - 32, 88, 64, f1Body, '#ffffff', 0, f1Helmet);

        // Speedlines de alta velocidade cortando o ar
        ctx.strokeStyle = 'rgba(255, 255, 255, 0.4)';
        ctx.lineWidth = 1;
        for (let i = 0; i < 4; i++) {
            let sx = cx + (i % 2 === 0 ? -1 : 1) * (45 + (i * 18));
            let sy = (topY + 10) + ((t * 220 + i * 40) % (H - 70));
            ctx.beginPath();
            ctx.moveTo(sx, sy);
            ctx.lineTo(sx + (i % 2 === 0 ? -4 : 4), sy + 18);
            ctx.stroke();
        }
    }

    // 2. ANIMAÇÃO DE NASCAR (Circuito Oval, Banking SAFER Wall & Pack Racing no Vácuo)
    function renderNascarShowcase(ctx, t, playerColor, helmetColor, modelType) {
        const W = ctx.canvas.width;
        const H = ctx.canvas.height;
        ctx.clearRect(0, 0, W, H);

        // Céu ensolarado de Daytona / Talladega
        let skyGrad = ctx.createLinearGradient(0, 0, 0, 48);
        skyGrad.addColorStop(0, '#0284c7');
        skyGrad.addColorStop(1, '#38bdf8');
        ctx.fillStyle = skyGrad;
        ctx.fillRect(0, 0, W, 48);

        // Muro de Contenção Oval SAFER Barrier com grade metálica e faixa amarela
        ctx.fillStyle = '#475569';
        ctx.fillRect(0, 40, W, 8);
        for (let gx = 0; gx < W; gx += 8) {
            ctx.strokeStyle = 'rgba(255,255,255,0.2)';
            ctx.beginPath(); ctx.moveTo(gx, 40); ctx.lineTo(gx, 48); ctx.stroke();
        }
        ctx.fillStyle = '#eab308';
        ctx.fillRect(0, 48, W, 5);
        ctx.fillStyle = '#cbd5e1';
        ctx.fillRect(0, 53, W, 9);
        // Patrocínios no muro
        ctx.fillStyle = '#dc2626';
        ctx.fillRect(40, 54, 30, 7);
        ctx.fillStyle = '#0284c7';
        ctx.fillRect(150, 54, 34, 7);

        // Asfalto inclinado do circuito oval (Banking)
        let roadGrad = ctx.createLinearGradient(0, 62, 0, H);
        roadGrad.addColorStop(0, '#334155');
        roadGrad.addColorStop(0.3, '#1e293b');
        roadGrad.addColorStop(1, '#0f172a');
        ctx.fillStyle = roadGrad;
        ctx.fillRect(0, 62, W, H - 62);

        // Duas faixas amarelas divisórias de pista oval (movendo-se em curva)
        ctx.strokeStyle = '#facc15';
        ctx.lineWidth = 2;
        ctx.setLineDash([14, 10]);
        ctx.lineDashOffset = -(t * 260);

        ctx.beginPath();
        ctx.moveTo(0, 104);
        ctx.quadraticCurveTo(W * 0.5, 98, W, 104);
        ctx.stroke();

        ctx.beginPath();
        ctx.moveTo(0, 142);
        ctx.quadraticCurveTo(W * 0.5, 136, W, 142);
        ctx.stroke();
        ctx.setLineDash([]);

        // Disputa lado a lado de 3 Stock Cars (Pack Racing / Drafting)
        let draftLead = Math.sin(t * 3.2) * 14;

        // Carro 1: Linha de fora (Top Line) - ultrapassando por fora
        let car1X = 175 - draftLead;
        let car1Y = 96;
        if (window.drawNascarSprite) {
            window.drawNascarSprite(ctx, car1X - 38, car1Y - 26, 76, 52, '#f59e0b', '#ffffff', 0, '#ffffff', 'NEXTGEN');
        }

        // Carro 2: Linha de dentro (Bottom Line) - disputando para-choque com para-choque
        let car2X = 100 + draftLead;
        let car2Y = 126;
        let nBody = (currentSeries === 'NASCAR' ? playerColor : '#0055ff');
        let nHelmet = (currentSeries === 'NASCAR' ? helmetColor : '#ffcc00');
        let nModel = modelType || 'SUPERBIRD';
        if (window.drawNascarSprite) {
            window.drawNascarSprite(ctx, car2X - 42, car2Y - 28, 84, 56, nBody, '#ffffff', 0, nHelmet, nModel);
        }

        // Carro 3: No vácuo colado atrás (Bump drafting)
        let car3X = 65 + (draftLead * 0.6);
        let car3Y = 150;
        if (window.drawNascarSprite) {
            window.drawNascarSprite(ctx, car3X - 36, car3Y - 24, 72, 48, '#dc2626', '#000000', 0, '#ffffff', 'MONTE_CARLO');
        }

        // Fumaça de escape suave saindo lateralmente
        ctx.save();
        ctx.fillStyle = 'rgba(255, 255, 255, 0.22)';
        for (let s = 0; s < 3; s++) {
            let sx = car2X - 38 - (s * 8);
            let sy = car2Y + 8 + Math.sin(t * 12 + s) * 2;
            ctx.beginPath();
            ctx.arc(sx, sy, 3 + s * 2, 0, Math.PI * 2);
            ctx.fill();
        }
        ctx.restore();
    }

    // 3. ANIMAÇÃO DE RALLY (Pista de Terra / Cascalho, Drift em Curva e Nuvens de Poeira)
    function renderRallyShowcase(ctx, t, playerColor, helmetColor, modelType) {
        const W = ctx.canvas.width;
        const H = ctx.canvas.height;
        ctx.clearRect(0, 0, W, H);

        // Céu montanhoso de Rally WRC
        let skyGrad = ctx.createLinearGradient(0, 0, 0, 50);
        skyGrad.addColorStop(0, '#1e1b4b');
        skyGrad.addColorStop(1, '#4338ca');
        ctx.fillStyle = skyGrad;
        ctx.fillRect(0, 0, W, 50);

        // Silhueta de pinheiros e montanhas ao fundo
        ctx.fillStyle = '#064e3b';
        for (let tx = 0; tx < W; tx += 18) {
            let th = 16 + Math.sin(tx * 0.15) * 6;
            ctx.beginPath();
            ctx.moveTo(tx, 50);
            ctx.lineTo(tx + 9, 50 - th);
            ctx.lineTo(tx + 18, 50);
            ctx.closePath();
            ctx.fill();
        }

        // Terreno de terra e cascalho marrom/avermelhado
        let earthGrad = ctx.createLinearGradient(0, 50, 0, H);
        earthGrad.addColorStop(0, '#78350f');
        earthGrad.addColorStop(0.5, '#92400e');
        earthGrad.addColorStop(1, '#451a03');
        ctx.fillStyle = earthGrad;
        ctx.fillRect(0, 50, W, H - 50);

        // Curva sinuosa de terra batida
        ctx.fillStyle = '#b45309';
        ctx.beginPath();
        ctx.moveTo(20, H);
        ctx.quadraticCurveTo(W * 0.45, 65, W - 20, 60);
        ctx.lineTo(W, 60);
        ctx.quadraticCurveTo(W * 0.55, 95, W - 10, H);
        ctx.closePath();
        ctx.fill();

        // Textura pontilhada de pedras e cascalho no chão
        ctx.fillStyle = 'rgba(0, 0, 0, 0.25)';
        for (let g = 0; g < 30; g++) {
            let gx = ((g * 37) + (t * 40)) % W;
            let gy = 70 + ((g * 19) % (H - 80));
            ctx.fillRect(gx, gy, 2, 2);
        }

        // Marcas de derrapagem (Drift Skidmarks) na curva de terra
        ctx.strokeStyle = 'rgba(40, 20, 10, 0.65)';
        ctx.lineWidth = 4;
        ctx.beginPath();
        ctx.moveTo(70, H);
        ctx.quadraticCurveTo(130, 125, 200, 95);
        ctx.stroke();

        ctx.beginPath();
        ctx.moveTo(95, H);
        ctx.quadraticCurveTo(155, 125, 225, 95);
        ctx.stroke();

        // Posição do carro de Rally derrapando de lado (Drift em ângulo agressivo)
        let rX = 142 + Math.sin(t * 3) * 6;
        let rY = 120 + Math.cos(t * 3) * 4;

        // Gera volumosas nuvens de poeira levantando das 4 rodas
        for (let p = 0; p < 2; p++) {
            rallyDust.push({
                x: rX - 25 + (Math.random() - 0.5) * 16,
                y: rY + 14 + (Math.random() - 0.5) * 8,
                vx: -Math.random() * 85 - 40,
                vy: -Math.random() * 25 - 10,
                radius: Math.random() * 6 + 4,
                maxRadius: Math.random() * 24 + 18,
                life: 1.0,
                decay: Math.random() * 1.8 + 1.2,
                color: Math.random() < 0.5 ? 'rgba(217, 119, 6,' : 'rgba(245, 158, 11,'
            });
        }

        // Gera pedrinhas e cascalho sendo arremessados pela tração 4x4
        if (Math.random() < 0.6) {
            rallyGravel.push({
                x: rX - 22,
                y: rY + 16,
                vx: -Math.random() * 110 - 50,
                vy: -Math.random() * 60 - 20,
                size: Math.random() * 3 + 1.5,
                life: 0.8
            });
        }

        // Desenha e atualiza poeira
        for (let i = rallyDust.length - 1; i >= 0; i--) {
            let d = rallyDust[i];
            d.x += d.vx * 0.016;
            d.y += d.vy * 0.016;
            d.radius += (d.maxRadius - d.radius) * 0.06;
            d.life -= d.decay * 0.016;
            if (d.life <= 0 || d.x < -30) {
                rallyDust.splice(i, 1);
                continue;
            }
            ctx.save();
            ctx.fillStyle = d.color + (d.life * 0.45) + ')';
            ctx.beginPath();
            ctx.arc(d.x, d.y, d.radius, 0, Math.PI * 2);
            ctx.fill();
            ctx.restore();
        }

        // Desenha e atualiza cascalhos
        ctx.fillStyle = '#1c1917';
        for (let i = rallyGravel.length - 1; i >= 0; i--) {
            let gr = rallyGravel[i];
            gr.x += gr.vx * 0.016;
            gr.y += gr.vy * 0.016;
            gr.vy += 120 * 0.016;
            gr.life -= 0.016 * 1.4;
            if (gr.life <= 0 || gr.y > H) {
                rallyGravel.splice(i, 1);
                continue;
            }
            ctx.fillRect(gr.x, gr.y, gr.size, gr.size);
        }

        // Desenha o Carro de Rally em ângulo agressivo de Drift (rodas contra-esterçadas)
        ctx.save();
        ctx.translate(rX, rY);
        ctx.rotate(-0.35);

        let rBody = (currentSeries === 'RALLY' ? playerColor : '#003893');
        let rHelmet = (currentSeries === 'RALLY' ? helmetColor : '#ffcc00');
        let rModel = modelType || 'SUBARU';
        if (window.drawRallySprite) {
            window.drawRallySprite(ctx, -42, -28, 84, 56, rBody, '#ffffff', 1, rHelmet, rModel);
        }
        ctx.restore();
    }

    // Loop de renderização fluida a 60 FPS da animação do Showcase
    function showcaseLoop(timestamp) {
        if (!isShowcaseActive) return;

        if (!showcaseStartTime) showcaseStartTime = timestamp;
        let elapsed = (timestamp - showcaseStartTime) / 1000;
        let remaining = Math.max(0, SHOWCASE_DURATION - elapsed);
        let progress = Math.min(1, elapsed / SHOWCASE_DURATION);

        // Atualiza a barra de progresso e texto de contagem regressiva
        const timerText = document.getElementById('showcase-timer-text');
        const progressFill = document.getElementById('showcase-progress-fill');
        if (progressFill) progressFill.style.width = (progress * 100) + '%';

        let countSeconds = Math.ceil(remaining);
        if (timerText) {
            if (remaining > 0.4) {
                timerText.innerText = 'PREPARANDO O GRID: ' + countSeconds + '...';
            } else {
                timerText.innerText = '🏁 LARGADA!';
            }
        }

        // Bips sonoros estilo semáforo de largada
        if (countSeconds === 3 && !showcaseBeepsFired[3]) {
            showcaseBeepsFired[3] = true;
            playShowcaseBeep(440, 0.09);
        } else if (countSeconds === 2 && !showcaseBeepsFired[2]) {
            showcaseBeepsFired[2] = true;
            playShowcaseBeep(440, 0.09);
        } else if (countSeconds === 1 && !showcaseBeepsFired[1]) {
            showcaseBeepsFired[1] = true;
            playShowcaseBeep(440, 0.09);
        } else if (remaining <= 0.25 && !showcaseBeepsFired[0]) {
            showcaseBeepsFired[0] = true;
            playShowcaseBeep(880, 0.22);
        }

        // Renderiza os 3 canvas dedicados
        const nascarModelSelect = document.getElementById('nascar-model-select');
        const rallyModelSelect = document.getElementById('rally-model-select');
        let nascarModel = nascarModelSelect ? nascarModelSelect.value : 'SUPERBIRD';
        let rallyModel = rallyModelSelect ? rallyModelSelect.value : 'SUBARU';

        if (f1ShowcaseCtx) renderF1Showcase(f1ShowcaseCtx, elapsed, playerCarColor, playerHelmetColor);
        if (nascarShowcaseCtx) renderNascarShowcase(nascarShowcaseCtx, elapsed, playerCarColor, playerHelmetColor, nascarModel);
        if (rallyShowcaseCtx) renderRallyShowcase(rallyShowcaseCtx, elapsed, playerCarColor, playerHelmetColor, rallyModel);

        if (elapsed >= SHOWCASE_DURATION) {
            finishShowcaseAndLaunch();
    
        }

        showcaseAnimId = requestAnimationFrame(showcaseLoop);
    }

    // Inicia a transição e animação pré-jogo
    function triggerPreGameShowcase(isTraining) {
        playerCarColor = document.getElementById('car-color').value;
        playerHelmetColor = document.getElementById('helmet-color').value;
        // Reaplica as cores salvas na Garagem ao iniciar a sessão.
        try {
            const garageSaved = JSON.parse(localStorage.getItem('retroRacingGarage') || '{}');
            if (garageSaved.body) playerCarColor = garageSaved.body;
            if (garageSaved.helmet) playerHelmetColor = garageSaved.helmet;
            document.getElementById('car-color').value = playerCarColor;
            document.getElementById('helmet-color').value = playerHelmetColor;
        } catch (e) {}
        currentStage = parseInt(document.getElementById('stage-select').value, 10) || 0;

        generateSprites();
        initAudio();
        playShowcaseWhoosh();

        isTrainingMode = isTraining;
        if (isTrainingMode) {
            ghostData = {
                active: false,
                bestTime: 0,
                bestTelemetry: [],
                currentTelemetry: [],
                ghostZ: 0,
                ghostOffset: 0,
                ghostSpeed: 0,
                ghostSlideX: 0
            };
            document.getElementById('training-badge').classList.remove('hidden');

        // return
        } else {
            tireHealth = 100;
            document.getElementById('training-badge').classList.add('hidden');
            document.getElementById('delta-info').classList.add('hidden');


        }

        // Atualiza cabeçalho do showcase
        const badgeEl = document.getElementById('showcase-mode-badge');
        let stageObj = STAGES[currentStage];
        let stageName = stageObj ? (stageObj.menuName || stageObj.name) : 'FASE 1';
        if (badgeEl) {
            if (isTrainingMode) {
                badgeEl.innerText = '🎯 TREINO LIVRE • ' + stageName;
                badgeEl.style.background = 'linear-gradient(90deg, #0d9488, #115e59)';
                badgeEl.style.borderColor = '#2dd4bf';
            } else {
                badgeEl.innerText = '🏆 CAMPEONATO OFICIAL • ' + stageName;
                badgeEl.style.background = 'linear-gradient(90deg, #b91c1c, #dc2626)';
                badgeEl.style.borderColor = '#ffd700';
            }
        }

        // Destaque visual dinâmico na modalidade selecionada no menu
        const f1Card = document.getElementById('showcase-f1-card');
        const nascarCard = document.getElementById('showcase-nascar-card');
        const rallyCard = document.getElementById('showcase-rally-card');
        const pillF1 = document.getElementById('pill-f1');
        const pillNascar = document.getElementById('pill-nascar');
        const pillRally = document.getElementById('pill-rally');
        const availF1 = document.getElementById('avail-pill-f1');
        const availNascar = document.getElementById('avail-pill-nascar');
        const availRally = document.getElementById('avail-pill-rally');

        [f1Card, nascarCard, rallyCard].forEach(c => { if(c) c.classList.remove('is-selected'); });
        [pillF1, pillNascar, pillRally].forEach(p => { if(p) p.classList.add('hidden'); });
        [availF1, availNascar, availRally].forEach(a => { if(a) a.classList.remove('hidden'); });

        if (currentSeries === 'NASCAR') {
            if (nascarCard) nascarCard.classList.add('is-selected');
            if (pillNascar) pillNascar.classList.remove('hidden');
            if (availNascar) availNascar.classList.add('hidden');
        } else if (currentSeries === 'RALLY') {
            if (rallyCard) rallyCard.classList.add('is-selected');
            if (pillRally) pillRally.classList.remove('hidden');
            if (availRally) availRally.classList.add('hidden');
        } else {
            if (f1Card) f1Card.classList.add('is-selected');
            if (pillF1) pillF1.classList.remove('hidden');
            if (availF1) availF1.classList.add('hidden');
        }

        // Oculta menu e exibe showcase
        mainMenu.classList.add('hidden');
        if (modeShowcaseOverlay) modeShowcaseOverlay.classList.remove('hidden');

        // Reseta variáveis e inicia animação
        f1Sparks = [];
        rallyDust = [];
        rallyGravel = [];
        showcaseBeepsFired = { 3: false, 2: false, 1: false, 0: false };
        showcaseStartTime = 0;
        isShowcaseActive = true;
        state = 'SHOWCASE';

        if (showcaseAnimId) cancelAnimationFrame(showcaseAnimId);
        showcaseAnimId = requestAnimationFrame(showcaseLoop);
    }

    // Finaliza o showcase e transiciona fluidamente para a corrida
    function finishShowcaseAndLaunch() {
        if (!isShowcaseActive) return;
        isShowcaseActive = false;
        if (showcaseAnimId) cancelAnimationFrame(showcaseAnimId);

        if (modeShowcaseOverlay) modeShowcaseOverlay.classList.add('hidden');
        startSequence();
    }

    const showcaseSkipBtn = document.getElementById('showcase-skip-btn');
    if (showcaseSkipBtn) {
        showcaseSkipBtn.onclick = function() {
            finishShowcaseAndLaunch();
        };
    }

    document.getElementById('start-btn').onclick = function() {
        triggerPreGameShowcase(false);
    };

    document.getElementById('training-btn').onclick = function() {
        triggerPreGameShowcase(true);
