    function exitTraining() {
        isTrainingMode = false;
        state = 'MENU';
        mainMenu.classList.remove('hidden');
        hud.classList.add('hidden');
        if (modeShowcaseOverlay) modeShowcaseOverlay.classList.add('hidden');
        isShowcaseActive = false;
        document.getElementById('training-badge').classList.add('hidden');
        document.getElementById('delta-info').classList.add('hidden');


        if (isMobile) mControls.style.display = 'none';
    }
    document.getElementById('exit-training-btn').onclick = exitTraining;

    function updateMenuPreview() {
        if (state !== 'MENU') return;
        const stageSelect = document.getElementById('stage-select');
        if (stageSelect) {
            currentStage = parseInt(stageSelect.value, 10) || 0;
        }
        applyStageWeather();
        resetRoad();
    }

    const stageSelectEl = document.getElementById('stage-select');
    const weatherSelectEl = document.getElementById('weather-select');
    const nascarModelSelectEl = document.getElementById('nascar-model-select');
