        if (typeof generateSprites === 'function') generateSprites();
    };
    if (rallyModelSelectEl) rallyModelSelectEl.onchange = function() {
        if (typeof generateSprites === 'function') generateSprites();
    };

    setSeries('F1');
    requestAnimationFrame(loop);


    // Garagem e lobby adicionados de forma isolada para preservar o jogo existente.
    (function setupGarageAndLobby() {
      const $ = id => document.getElementById(id);
      const garage = $('garage-overlay'), lobby = $('multiplayer-overlay');
      if (!garage || !lobby) return;
      const config = {body:'#e10600', trim:'#f8fafc', helmet:'#ffcc00', number:'7', decal:'RETRO', wing:'standard', wheels:'dark'};
      let angle = 0, dragging = false, lastX = 0, ready = false, roomCreated = false;
      try { Object.assign(config, JSON.parse(localStorage.getItem('retroRacingGarage') || '{}')); } catch(e) {}
      const fields = {'garage-body':'body','garage-trim':'trim','garage-helmet':'helmet','garage-number':'number','garage-decal':'decal','garage-wing':'wing','garage-wheels':'wheels'};
      Object.entries(fields).forEach(([id,key]) => { if($(id)) $(id).value=config[key]; });
      function drawGarage() {
        const c=$('garage-preview'), ctx=c.getContext('2d'), w=c.width,h=c.height;
        ctx.clearRect(0,0,w,h);
        const g=ctx.createLinearGradient(0,0,0,h); g.addColorStop(0,'#111c35');g.addColorStop(1,'#030610');ctx.fillStyle=g;ctx.fillRect(0,0,w,h);
        ctx.strokeStyle='rgba(148,163,184,.15)';ctx.lineWidth=1;
        for(let x=0;x<w;x+=24){ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x,h);ctx.stroke()}
        for(let y=0;y<h;y+=24){ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(w,y);ctx.stroke()}
        ctx.save();ctx.translate(w/2,h/2+8);ctx.rotate(angle*.35);
        // Sombra e carro visto em perspectiva superior, desenhado em canvas para preview leve.
        ctx.fillStyle='rgba(0,0,0,.55)';ctx.beginPath();ctx.ellipse(0,12,105,64,0,0,Math.PI*2);ctx.fill();
        ctx.fillStyle=config.wheels==='gold'?'#d4a017':config.wheels==='white'?'#e5e7eb':'#111827';
        [[-65,-42],[45,-42],[-65,28],[45,28]].forEach(([x,y])=>{ctx.fillRect(x,y,24,35);ctx.strokeStyle='#94a3b8';ctx.strokeRect(x,y,24,35)});
        ctx.fillStyle=config.body;ctx.beginPath();ctx.moveTo(-48,55);ctx.lineTo(-58,15);ctx.lineTo(-48,-48);ctx.lineTo(-30,-66);ctx.lineTo(30,-66);ctx.lineTo(48,-48);ctx.lineTo(58,15);ctx.lineTo(48,55);ctx.closePath();ctx.fill();ctx.strokeStyle='#f8fafc';ctx.lineWidth=2;ctx.stroke();
        ctx.fillStyle=config.trim;ctx.beginPath();ctx.moveTo(-31,-37);ctx.lineTo(-23,-55);ctx.lineTo(23,-55);ctx.lineTo(31,-37);ctx.lineTo(24,-15);ctx.lineTo(-24,-15);ctx.closePath();ctx.fill();
        ctx.fillStyle=config.trim;ctx.fillRect(-48,config.wing==='compact'?-52:-61,96,config.wing==='wide'?10:6);
        ctx.fillStyle=config.helmet;ctx.beginPath();ctx.arc(0,-27,10,0,Math.PI*2);ctx.fill();
        ctx.fillStyle='#111827';ctx.font='bold 22px sans-serif';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(String(config.number||'7'),0,13);
        if(config.decal==='RETRO'||config.decal==='RACING'){ctx.fillStyle=config.trim;ctx.font='bold 8px sans-serif';ctx.fillText(config.decal==='RETRO'?'RETRO RACING':'RACING',0,39)}
        if(config.decal==='STRIPE'){ctx.fillStyle=config.trim;ctx.fillRect(-5,-12,10,58)}
        ctx.restore();
        ctx.fillStyle='#ffd700';ctx.font='10px monospace';ctx.textAlign='left';ctx.fillText('GARAGE // PREVIEW',10,18);
      }
      function readConfig(){Object.entries(fields).forEach(([id,key])=>{if($(id))config[key]=$(id).value});config.number=String(Math.max(1,Math.min(99,parseInt(config.number,10)||7)));$('garage-number').value=config.number;drawGarage();}
      Object.keys(fields).forEach(id=>$(id).addEventListener('input',readConfig));
      const preview=$('garage-preview');
      preview.addEventListener('pointerdown',e=>{dragging=true;lastX=e.clientX;preview.setPointerCapture(e.pointerId)});
      preview.addEventListener('pointermove',e=>{if(!dragging)return;angle+=(e.clientX-lastX)*.012;lastX=e.clientX;drawGarage()});
      preview.addEventListener('pointerup',()=>dragging=false);preview.addEventListener('pointercancel',()=>dragging=false);
      $('open-garage-btn').addEventListener('click',()=>{readConfig();garage.classList.remove('hidden')});
      $('garage-back-btn').addEventListener('click',()=>garage.classList.add('hidden'));
      $('garage-save-btn').addEventListener('click',()=>{
        readConfig();
        try{localStorage.setItem('retroRacingGarage',JSON.stringify(config));}catch(e){}
        // Mantém a compatibilidade com a customização antiga do jogo.
        if($('car-color'))$('car-color').value=config.body;
        if($('helmet-color'))$('helmet-color').value=config.helmet;
        if(typeof playerCarColor!=='undefined')playerCarColor=config.body;
        if(typeof playerHelmetColor!=='undefined')playerHelmetColor=config.helmet;
        garage.classList.add('hidden');
      });
      // Multiplayer real por API PHP com polling: funciona em hospedagem PHP comum.
      const apiUrl = 'multiplayer_api.php';
      const playerIdKey = 'retroRacingMultiplayerId';
      let playerId = localStorage.getItem(playerIdKey);
      if (!playerId) { playerId = 'p' + Math.random().toString(36).slice(2, 12); localStorage.setItem(playerIdKey, playerId); }
      let roomCode = '', lobbyReady = false, isHost = false, networkTimer = null, lastRaceSend = 0;
      let knownRemote = new Map(), raceWasStarted = false;
      const status = $('lobby-status');
      async function api(action, extra = {}) {
        const response = await fetch(apiUrl, {method:'POST', headers:{'Content-Type':'application/json'}, body:JSON.stringify({action, player_id:playerId, room_code:roomCode, name:$('lobby-player-name')?.value.trim() || 'Piloto', color:config.body, ready:lobbyReady, ...extra})});
        const data = await response.json();
        if (!response.ok || !data.ok) throw new Error(data.error || 'Falha na comunicação com o servidor.');
        return data;
      }
      function renderLobby(data = null) {
        const list=$('lobby-player-list'); list.innerHTML='';
        const players=data?.players || [];
        players.forEach(p=>{
          const row=document.createElement('div'); row.style.cssText='display:flex;align-items:center;gap:10px;background:#0b1224;border:1px solid #334155;border-radius:8px;padding:10px;font:10px monospace';
          const sw=document.createElement('span'); sw.style.cssText=`width:22px;height:14px;background:${p.color || '#e10600'};border:1px solid white;display:inline-block`;
          const name=document.createElement('span'); name.textContent=(p.name || 'Piloto')+(p.player_id===playerId?' (VOCÊ)':'')+' — '+(p.ready?'PRONTO':'AGUARDANDO'); name.style.flex='1';
          const count=document.createElement('span'); count.textContent=(p.host?'HOST':'PILOTO'); count.style.color='#94a3b8'; row.append(sw,name,count); list.append(row);
        });
        $('lobby-start-btn').disabled = !(isHost && players.length >= 2 && players.every(p=>p.ready));
        if (data?.room_code) { roomCode=data.room_code; $('lobby-room-code').value=roomCode; }
      }
      function removeRemoteCars() {
        cars.filter(c=>c.isRemote).forEach(c=>{ const seg=findSegment(c.z); const idx=seg.cars.indexOf(c); if(idx>=0)seg.cars.splice(idx,1); });
        cars=cars.filter(c=>!c.isRemote); knownRemote.clear();
      }
      function syncRemoteCars(players) {
        const active=new Set();
        (players||[]).forEach(p=>{ if(p.player_id===playerId || !p.race) return; active.add(p.player_id);
          let c=knownRemote.get(p.player_id);
          if(!c){ c={isRemote:true,playerId:p.player_id,driverName:p.name||'Piloto',teamName:'MULTIPLAYER',offset:0,z:0,speed:0,maxSpeed:MAX_SPEED,color:p.color||'#00d4ff',sprite:SPRITES.CAR01,lapsCompleted:0,finished:false}; knownRemote.set(p.player_id,c); cars.push(c); }
          const old=findSegment(c.z); c.z=Number(p.race.position)||0; c.offset=Number(p.race.playerX)||0; c.speed=Number(p.race.speed)||0; c.lapsCompleted=Number(p.race.lap)||1;
          const next=findSegment(c.z); if(old!==next){const i=old.cars.indexOf(c);if(i>=0)old.cars.splice(i,1);next.cars.push(c);} else if(!next.cars.includes(c)) next.cars.push(c);
        });
        for(const [id,c] of knownRemote){ if(!active.has(id)){const seg=findSegment(c.z);const i=seg.cars.indexOf(c);if(i>=0)seg.cars.splice(i,1);cars=cars.filter(x=>x!==c);knownRemote.delete(id);} }
      }
      async function refreshRoom() {
        if(!roomCode) return;
        try { const data=await api('poll',{race:{position,playerX,speed,lap,state}}); renderLobby(data); syncRemoteCars(data.players);
          if(data.started && !raceWasStarted){ raceWasStarted=true; lobby.classList.add('hidden'); if(state==='MENU'||state==='FINISHED') startSequence(); }
          if(!data.started) raceWasStarted=false;
          if(data.error) status.textContent=data.error;
        } catch(e){ status.textContent='Conexão perdida: '+e.message; }
      }
      function beginPolling(){ if(networkTimer)clearInterval(networkTimer); networkTimer=setInterval(refreshRoom,700); refreshRoom(); }
      $('open-multiplayer-btn').addEventListener('click',()=>{lobby.classList.remove('hidden');status.textContent='Conectando ao servidor...';});
      $('lobby-back-btn').addEventListener('click',()=>{lobby.classList.add('hidden');if(networkTimer){clearInterval(networkTimer);networkTimer=null;} if(roomCode)api('leave').catch(()=>{});roomCode='';isHost=false;lobbyReady=false;removeRemoteCars();});
      $('lobby-ready-btn').addEventListener('click',async()=>{if(!roomCode){status.textContent='Crie ou entre em uma sala primeiro.';return;}lobbyReady=!lobbyReady;$('lobby-ready-btn').textContent=lobbyReady?'✓ PRONTO':'✓ MARCAR PRONTO';try{const d=await api('ready');renderLobby(d);}catch(e){lobbyReady=!lobbyReady;status.textContent=e.message;}});
      $('create-lobby-btn').addEventListener('click',async()=>{try{const d=await api('create',{room_name:$('lobby-name').value.trim()||'Grid Retro',privacy:$('lobby-privacy').value});roomCode=d.room_code;isHost=true;lobbyReady=false;status.textContent='Sala criada! Compartilhe o código '+roomCode+' com outro piloto.';renderLobby(d);beginPolling();}catch(e){status.textContent=e.message;}});
      $('join-lobby-btn').addEventListener('click',async()=>{roomCode=$('lobby-room-code').value.trim().toUpperCase();if(!roomCode){status.textContent='Digite o código da sala.';return;}try{const d=await api('join');isHost=false;lobbyReady=false;status.textContent='Você entrou na sala '+roomCode+'. Marque PRONTO para liberar a largada.';renderLobby(d);beginPolling();}catch(e){roomCode='';status.textContent=e.message;}});
      $('lobby-start-btn').addEventListener('click',async()=>{try{await api('start');status.textContent='Corrida iniciada!';await refreshRoom();}catch(e){status.textContent=e.message;}});
      drawGarage();

    })();

    // Fluxo em etapas: os controles existentes são reaproveitados, sem duplicar IDs.
    (function setupMenuFlowAndDash() {
      const $ = id => document.getElementById(id);
      const main = $('main-menu'), selection = $('selection-overlay'), settings = $('settings-overlay');
      const controls = $('selection-controls');
      let pendingTraining = false;
      // Move os seletores de modalidade/circuito para a sub-tela de seleção.
      const seriesSection = $('series-selector')?.closest('.menu-section');
      const raceSection = $('stage-select')?.closest('.menu-section');
      const modelSection = $('nascar-model-group')?.closest('.menu-section');
      if (seriesSection) controls.appendChild(seriesSection);
      if (raceSection) controls.appendChild(raceSection);
      if (modelSection) {
        const label = modelSection.querySelector('.menu-section-label');
        if (label) label.style.display = 'none';
        controls.appendChild(modelSection);
      }
      // Esconde os seletores antigos de cores da tela inicial; a garagem é a fonte visual de personalização.
      document.querySelectorAll('#main-menu .color-row').forEach(el => el.style.display = 'none');
      if ($('selection-mode-title')) $('selection-mode-title').textContent = 'ESCOLHA MODALIDADE, CIRCUITO E CLIMA';

      function openSelection(training) {
        pendingTraining = !!training;
        if ($('selection-mode-title')) $('selection-mode-title').textContent = training ? 'TREINO LIVRE • CONFIGURE SUA SESSÃO' : 'CAMPEONATO • CONFIGURE SUA CORRIDA';
        main.classList.add('hidden');
        settings.classList.add('hidden');
        selection.classList.remove('hidden');
      }
      $('start-btn').onclick = () => openSelection(false);
      $('training-btn').onclick = () => openSelection(true);
      $('selection-back-btn').onclick = () => { selection.classList.add('hidden'); main.classList.remove('hidden'); };
      $('selection-confirm-btn').onclick = () => {
        selection.classList.add('hidden');
        triggerPreGameShowcase(pendingTraining);
      };
      $('open-settings-btn').onclick = () => { main.classList.add('hidden'); settings.classList.remove('hidden'); };
      $('settings-back-btn').onclick = () => { settings.classList.add('hidden'); main.classList.remove('hidden'); };
      $('settings-volume').addEventListener('input', e => {
        const v = Number(e.target.value) / 100;
        gameVolume = v;
        try { localStorage.setItem('retroRacingVolume', String(v)); } catch(err) {}
        if (typeof engineGain !== 'undefined' && engineGain && typeof audioCtx !== 'undefined' && audioCtx) {
          engineGain.gain.setTargetAtTime(engineGain.gain.value, audioCtx.currentTime, 0.05);
        }
      });
      $('settings-scale').addEventListener('change', e => {
        const scale = Number(e.target.value) || 1;
        $('racing-dash').style.transform = `scale(${scale})`;
      });

      // Atualiza o painel analógico/digital a partir da velocidade real do jogo.
      const oldUpdateHUD = updateHUD;
      updateHUD = function() {
        oldUpdateHUD();
        const displaySpeedNow = Math.max(0, Math.round((speed / MAX_SPEED) * 320));
        const speedEl = $('dash-speed');
        if (speedEl) speedEl.innerHTML = `${displaySpeedNow} <small>KM/H</small>`;
        let gear = 'N';
        if (displaySpeedNow > 175) gear = '5';
        else if (displaySpeedNow > 125) gear = '4';
        else if (displaySpeedNow > 75) gear = '3';
        else if (displaySpeedNow > 25) gear = '2';
        else if (displaySpeedNow > 0) gear = '1';
        if (displaySpeedNow < 5) gear = 'R';
        $('dash-gear').textContent = gear;
        // Ponteiro de -130° a +130°, com zona vermelha no fim da faixa.
        const rpm = Math.min(10000, Math.max(800, 850 + displaySpeedNow * 27 + (gear === 'R' ? 0 : displaySpeedNow % 23 * 9)));
        const angle = -130 + (rpm / 10000) * 260;
        $('tach-needle').style.transform = `rotate(${angle}deg)`;
        const boost = Math.round(nitroCharge);
        $('dash-boost-fill').style.width = boost + '%';
        $('dash-boost-label').textContent = 'NITRO ' + boost + '% • SHIFT / N';
        $('dash-status').textContent = nitroActiveTime > 0 ? 'NITRO ATIVO!' : (inSlipstream ? 'VÁCUO ATIVO' : 'CURVA LIMPA = NITRO');
        $('dash-status').style.color = nitroActiveTime > 0 ? '#7dd3fc' : (inSlipstream ? '#ffcc00' : '#00eaff');
        const nitroHud = $('nitro-hud');
        if (nitroHud) {
          $('nitro-percent').textContent = boost + '%';
          $('nitro-hud-fill').style.width = boost + '%';
          nitroHud.classList.toggle('ready', nitroCharge >= NITRO_MIN_ACTIVATION);
          nitroHud.classList.toggle('active', nitroActiveTime > 0);
        }
        const gameContainer = $('game-container');
        if (gameContainer) gameContainer.classList.toggle('nitro-active', nitroActiveTime > 0);
      };
      // Mantém o painel fora das telas de menu.
      const dash = $('racing-dash');
      const syncDashVisibility = () => { if (dash) dash.style.display = (main.classList.contains('hidden') && !selection.classList.contains('hidden') === false && !settings.classList.contains('hidden') === false) ? '' : ''; };
      if (dash) dash.style.display = '';
      // Recupera o volume salvo quando existir.
      try { const saved = localStorage.getItem('retroRacingVolume'); if (saved !== null) { gameVolume = Math.max(0, Math.min(1, Number(saved))); $('settings-volume').value = String(Math.round(gameVolume*100)); } } catch(err) {}
    })();
</script>
</body>
</html>